// Package hyperlane is Hyperlane's wire format, byte for byte, for a mailbox on gno.land: the message and its id,
// the incremental merkle tree the validators checkpoint, the checkpoint digest they sign, a warp route's token
// message, and the multisig check a destination runs over the signatures. It keeps no state and reads no chain.
//
// Sources (hyperlane-monorepo 3cd9308, 2026-10-10): solidity/contracts/libs/Message.sol, Merkle.sol,
// CheckpointLib.sol, TypeCasts.sol, token/libs/TokenMessage.sol, isms/libs/MessageIdMultisigIsmMetadata.sol; the
// vectors in vectors/ are this package's tests.
//
// One departure, and only on the gno side: gno.land has no secp256k1, so the multisig a gno mailbox runs
// (VerifyMultisig) takes ed25519 signatures over the same checkpoint digest Hyperlane's validators sign with
// secp256k1, and each signature names its validator in one leading byte (65 bytes a signature, as in Hyperlane's
// metadata). Messages, ids, the tree and the digest are Hyperlane's exactly, so the other chain's ISM checks a gno
// checkpoint with its stock code.
package hyperlane

import (
	"crypto/bech32"
	"crypto/ed25519"
	"crypto/keccak256"
	"encoding/binary"
	"errors"
)

const (
	// Version is the message version every Hyperlane mailbox speaks (Versioned.VERSION).
	Version = 3
	// HeaderLen is the message header: version 1, nonce 4, origin 4, sender 32, destination 4, recipient 32.
	HeaderLen = 77
	// TreeDepth is the merkle tree's depth (Merkle.sol TREE_DEPTH).
	TreeDepth = 32
	// MaxLeaves is how many leaves the tree takes (Merkle.sol MAX_LEAVES, 2^32 - 1).
	MaxLeaves = 1<<TreeDepth - 1

	sigLen  = 65 // a signature's slot in multisig metadata: Hyperlane's r‖s‖v, here validator byte ‖ ed25519
	metaLen = 68 // the metadata's fixed head: merkle tree hook 32, root 32, index 4
)

// ------------------------------------------------------------- message --

// Message is a Hyperlane message (Message.sol). Sender and recipient are 32 bytes: a 20-byte address is padded on
// the left with twelve zero bytes (AddressToBytes32); a Solana pubkey is its 32 bytes as they are.
type Message struct {
	Version     uint8
	Nonce       uint32
	Origin      uint32
	Sender      [32]byte
	Destination uint32
	Recipient   [32]byte
	Body        []byte
}

// Bytes is the message on the wire: abi.encodePacked of the fields, big-endian, no length prefixes.
func (m Message) Bytes() []byte {
	b := make([]byte, 0, HeaderLen+len(m.Body))
	b = append(b, m.Version)
	b = binary.BigEndian.AppendUint32(b, m.Nonce)
	b = binary.BigEndian.AppendUint32(b, m.Origin)
	b = append(b, m.Sender[:]...)
	b = binary.BigEndian.AppendUint32(b, m.Destination)
	b = append(b, m.Recipient[:]...)
	return append(b, m.Body...)
}

// ID is the message's id: keccak256 of the whole message, body included.
func (m Message) ID() [32]byte { return ID(m.Bytes()) }

// ID is the id of a message as it came off the wire.
func ID(raw []byte) [32]byte { return keccak256.Sum256(raw) }

// ParseMessage reads a message off the wire. The body is a copy.
func ParseMessage(b []byte) (Message, error) {
	if len(b) < HeaderLen {
		return Message{}, errors.New("hyperlane: message shorter than its header")
	}
	var m Message
	m.Version = b[0]
	m.Nonce = binary.BigEndian.Uint32(b[1:5])
	m.Origin = binary.BigEndian.Uint32(b[5:9])
	copy(m.Sender[:], b[9:41])
	m.Destination = binary.BigEndian.Uint32(b[41:45])
	copy(m.Recipient[:], b[45:77])
	m.Body = append([]byte(nil), b[HeaderLen:]...)
	return m, nil
}

// ---------------------------------------------------------- addresses --

// AddressToBytes32 is a gno address as Hyperlane carries one: twelve zero bytes, then the address's twenty
// (TypeCasts.addressToBytes32).
func AddressToBytes32(a address) ([32]byte, error) {
	var out [32]byte
	hrp, bz, err := bech32.DecodeToBase256(string(a))
	if err != nil {
		return out, err
	}
	if hrp != "g" || len(bz) != 20 {
		return out, errors.New("hyperlane: not a gno address: " + string(a))
	}
	copy(out[12:], bz)
	return out, nil
}

// Bytes32ToAddress is the gno address a bytes32 names: twelve zero bytes, then the address's twenty (§13: the top
// 12 bytes must be zero). A bytes32 whose top twelve bytes are not zero — a raw Solana pubkey, say — is no gno
// address and errors, rather than landing on the address its last twenty bytes happen to spell, which nobody
// holds (the EVM's TypeCasts.bytes32ToAddress truncates; a gno route sweeps such a recipient instead, §5.4).
func Bytes32ToAddress(b [32]byte) (address, error) {
	for _, c := range b[:12] {
		if c != 0 {
			return "", errors.New("hyperlane: not a gno address: the top twelve bytes are not zero")
		}
	}
	s, err := bech32.EncodeFromBase256("g", b[12:])
	if err != nil {
		panic(err) // twenty bytes always encode
	}
	return address(s), nil
}

// -------------------------------------------------------- merkle tree --

// Tree is Hyperlane's incremental merkle tree (Merkle.sol, the eth2 deposit contract's): depth 32, nodes
// keccak256(left ‖ right), leaves the message ids themselves. The zero value is the empty tree.
type Tree struct {
	Branch [TreeDepth][32]byte
	Count  uint32
}

// zeroes[i] is the root of an empty subtree of height i: Z0 = 0, Zi+1 = keccak256(Zi ‖ Zi).
var zeroes = func() [TreeDepth][32]byte {
	var z [TreeDepth][32]byte
	for i := 1; i < TreeDepth; i++ {
		z[i] = hash2(z[i-1], z[i-1])
	}
	return z
}()

func hash2(a, b [32]byte) [32]byte {
	buf := make([]byte, 64)
	copy(buf, a[:])
	copy(buf[32:], b[:])
	return keccak256.Sum256(buf)
}

// Insert adds a leaf at index Count.
func (t *Tree) Insert(leaf [32]byte) {
	if t.Count >= MaxLeaves {
		panic("hyperlane: merkle tree full")
	}
	t.Count++
	size := t.Count
	node := leaf
	for i := 0; i < TreeDepth; i++ {
		if size&1 == 1 {
			t.Branch[i] = node
			return
		}
		node = hash2(t.Branch[i], node)
		size >>= 1
	}
	panic("hyperlane: merkle insert fell through") // unreachable: Count < 2^32 has a bit set below 32
}

// Root is the tree's root now (Merkle.sol root(), with the zero hashes).
func (t *Tree) Root() [32]byte {
	var cur [32]byte
	for i := 0; i < TreeDepth; i++ {
		if (t.Count>>uint(i))&1 == 1 {
			cur = hash2(t.Branch[i], cur)
		} else {
			cur = hash2(cur, zeroes[i])
		}
	}
	return cur
}

// ---------------------------------------------------------- checkpoint --

// DomainHash binds a checkpoint to its origin chain and that chain's merkle tree hook: keccak256(origin ‖ hook ‖
// "HYPERLANE"), 45 bytes hashed (CheckpointLib.domainHash). On Solana the hook is the mailbox program's id.
func DomainHash(origin uint32, hook [32]byte) [32]byte {
	b := make([]byte, 0, 45)
	b = binary.BigEndian.AppendUint32(b, origin)
	b = append(b, hook[:]...)
	b = append(b, "HYPERLANE"...)
	return keccak256.Sum256(b)
}

// CheckpointDigest is what a validator signs for one message: the EIP-191 personal-message hash of
// keccak256(domainHash ‖ root ‖ index ‖ messageID) (CheckpointLib.digest). root and index are the origin tree's
// right after messageID went in at index; a message-id ISM does not check them, only the signatures over them.
func CheckpointDigest(origin uint32, hook, root [32]byte, index uint32, messageID [32]byte) [32]byte {
	d := DomainHash(origin, hook)
	b := make([]byte, 0, 100)
	b = append(b, d[:]...)
	b = append(b, root[:]...)
	b = binary.BigEndian.AppendUint32(b, index)
	b = append(b, messageID[:]...)
	return EthSignedMessageHash(keccak256.Sum256(b))
}

// EthSignedMessageHash is EIP-191's hash of a 32-byte message: keccak256("\x19Ethereum Signed Message:\n32" ‖ h).
func EthSignedMessageHash(h [32]byte) [32]byte {
	b := append([]byte("\x19Ethereum Signed Message:\n32"), h[:]...)
	return keccak256.Sum256(b)
}

// -------------------------------------------------------- token message --

// TokenMessage is a warp route's body (TokenMessage.sol): the recipient on the destination, the amount as a
// big-endian uint256, then metadata (usually none).
func TokenMessage(recipient [32]byte, amount uint64, metadata []byte) []byte {
	b := make([]byte, 0, 64+len(metadata))
	b = append(b, recipient[:]...)
	b = append(b, make([]byte, 24)...)
	b = binary.BigEndian.AppendUint64(b, amount)
	return append(b, metadata...)
}

// ParseTokenMessage reads a warp route's body. An amount past 2^64 - 1 is refused; trailing metadata (Solana's
// TransferRemoteWithMemo writes a memo there) is returned, not refused.
func ParseTokenMessage(b []byte) (recipient [32]byte, amount uint64, metadata []byte, err error) {
	if len(b) < 64 {
		return recipient, 0, nil, errors.New("hyperlane: token message shorter than 64 bytes")
	}
	for _, c := range b[32:56] {
		if c != 0 {
			return recipient, 0, nil, errors.New("hyperlane: token amount past 64 bits")
		}
	}
	copy(recipient[:], b[:32])
	return recipient, binary.BigEndian.Uint64(b[56:64]), append([]byte(nil), b[64:]...), nil
}

// ------------------------------------------------------------ multisig --

// Checkpoint is the head of multisig metadata: the origin's merkle tree hook, and the root and index the
// validators signed (MessageIdMultisigIsmMetadata).
type Checkpoint struct {
	Hook  [32]byte
	Root  [32]byte
	Index uint32
}

// Signature is one validator's ed25519 signature and its place in the validator set.
type Signature struct {
	Validator uint8
	Sig       [64]byte
}

// MultisigMetadata lays out what a relayer hands a gno mailbox: hook 32 ‖ root 32 ‖ index 4, then 65 bytes a
// signature: the validator's index in the set, then its ed25519 signature over CheckpointDigest. Validator
// indexes strictly increase, so no validator counts twice.
func MultisigMetadata(c Checkpoint, sigs []Signature) []byte {
	b := make([]byte, 0, metaLen+sigLen*len(sigs))
	b = append(b, c.Hook[:]...)
	b = append(b, c.Root[:]...)
	b = binary.BigEndian.AppendUint32(b, c.Index)
	for _, s := range sigs {
		b = append(b, s.Validator)
		b = append(b, s.Sig[:]...)
	}
	return b
}

// ParseMultisigMetadata reads metadata laid out by MultisigMetadata.
func ParseMultisigMetadata(b []byte) (Checkpoint, []Signature, error) {
	var c Checkpoint
	if len(b) < metaLen || (len(b)-metaLen)%sigLen != 0 {
		return c, nil, errors.New("hyperlane: metadata is not 68 bytes and whole 65-byte signatures")
	}
	copy(c.Hook[:], b[0:32])
	copy(c.Root[:], b[32:64])
	c.Index = binary.BigEndian.Uint32(b[64:68])
	n := (len(b) - metaLen) / sigLen
	sigs := make([]Signature, n)
	for i := 0; i < n; i++ {
		o := metaLen + sigLen*i
		sigs[i].Validator = b[o]
		copy(sigs[i].Sig[:], b[o+1:o+sigLen])
	}
	return c, sigs, nil
}

// VerifyMultisig is a message-id multisig ISM over ed25519: the first threshold signatures in metadata must be
// valid signatures, by distinct validators in increasing order, over the checkpoint digest of this message from
// its own origin. validators are ed25519 public keys of 32 bytes. Signatures past the threshold are not read.
func VerifyMultisig(validators [][]byte, threshold int, metadata, message []byte) error {
	if threshold < 1 || threshold > len(validators) {
		return errors.New("hyperlane: no usable validator set for this origin")
	}
	m, err := ParseMessage(message)
	if err != nil {
		return err
	}
	c, sigs, err := ParseMultisigMetadata(metadata)
	if err != nil {
		return err
	}
	if len(sigs) < threshold {
		return errors.New("hyperlane: fewer signatures than the threshold")
	}
	digest := CheckpointDigest(m.Origin, c.Hook, c.Root, c.Index, ID(message))
	last := -1
	for _, s := range sigs[:threshold] {
		v := int(s.Validator)
		if v <= last {
			return errors.New("hyperlane: signatures out of validator order")
		}
		if v >= len(validators) {
			return errors.New("hyperlane: signature names no validator")
		}
		if !ed25519.Verify(validators[v], digest[:], s.Sig[:]) {
			return errors.New("hyperlane: a signature does not verify")
		}
		last = v
	}
	return nil
}

package hyperlane

import (
	"encoding/hex"
	"errors"
	"strings"
)

// The Bitcoin base58 alphabet, which Solana writes its 32-byte keys in.
const b58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"

// ParseKey32 reads a 32-byte key the way a person types one: 64 hex digits (with or without 0x), or a Solana
// address in base58.
func ParseKey32(s string) ([32]byte, error) {
	var out [32]byte
	s = strings.TrimSpace(s)
	if h := strings.TrimPrefix(s, "0x"); len(h) == 64 {
		b, err := hex.DecodeString(h)
		if err != nil {
			return out, errors.New("hyperlane: not hex: " + s)
		}
		copy(out[:], b)
		return out, nil
	}
	if len(s) == 0 || len(s) > 44 {
		return out, errors.New("hyperlane: not a 32-byte key in hex or base58: " + s)
	}
	digits := make([]byte, 0, 32) // the number so far, base 256, least significant first
	for i := 0; i < len(s); i++ {
		c := strings.IndexByte(b58, s[i])
		if c < 0 {
			return out, errors.New("hyperlane: not base58: " + s)
		}
		carry := c
		for j := range digits {
			carry += int(digits[j]) * 58
			digits[j] = byte(carry)
			carry >>= 8
		}
		for carry > 0 {
			digits = append(digits, byte(carry))
			carry >>= 8
		}
	}
	zeros := len(s) - len(strings.TrimLeft(s, "1")) // each leading '1' is a leading zero byte
	if zeros+len(digits) != 32 {
		return out, errors.New("hyperlane: base58 key is not 32 bytes: " + s)
	}
	for i, d := range digits {
		out[31-i] = d
	}
	return out, nil
}

// Base58 writes bytes the way Solana writes a key.
func Base58(b []byte) string {
	zeros := 0
	for zeros < len(b) && b[zeros] == 0 {
		zeros++
	}
	digits := make([]byte, 0, len(b)*138/100+1) // base 58, least significant first
	for _, x := range b[zeros:] {
		carry := int(x)
		for j := range digits {
			carry += int(digits[j]) << 8
			digits[j] = byte(carry % 58)
			carry /= 58
		}
		for carry > 0 {
			digits = append(digits, byte(carry%58))
			carry /= 58
		}
	}
	out := make([]byte, zeros+len(digits))
	for i := 0; i < zeros; i++ {
		out[i] = '1'
	}
	for i, d := range digits {
		out[len(out)-1-i] = b58[d]
	}
	return string(out)
}

// Package decisions is the ledger every bridge realm keeps of GovDAO's decisions (bridge/PLAN.md §5.3): a decision
// is born when a proposal made with one of the realm's builders executes, gets the next number, and is either
// applied at once or queued for 7 days of block time; anyone applies a queued one after its delay, and GovDAO can
// cancel it in between. The ledger keeps no closure and no proposal text: the parameters a builder wrote are the
// record. The realm decides what a decision does; this package keeps the numbers, the clocks and the page.
package decisions

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	// Day is a day of block time, in seconds.
	Day = int64(86400)
	// Factor divides every delay of the realms — Delay, Deadline, and the old router's 7 days after a swap, which
	// is Delay (§5.9): 1 for the mainnet build, which §8.3's check reads in the served source; the devnet build
	// is deployed with 8 here, so its 14 days pass in 42 hours, as the Solana programs' clock-factor-8 feature
	// does. A compiled constant beside the launch values, shown on every realm's page. The meters (§5.4) are
	// rates per real day and are not divided.
	Factor = int64(1)
	// Delay is the wait a raise, a swap, a credit, a migration or a sweep payment takes after its proposal
	// executes (§5.3: 7 days by block time), divided by Factor.
	Delay = 7 * Day / Factor
	// Deadline is how old a proposal may be when it executes; past it the closure returns an error and GovDAO
	// marks the proposal denied for good (§5.3: 14 days), divided by Factor.
	Deadline = 14 * Day / Factor
	// PageMax is how many decisions of one kind and state the page shows.
	PageMax = 100
	// DAOPath is the realm whose frame every builder's closure must be called from, once the governor has yielded
	// (or from the first block, when none was compiled): the proxy that executes GovDAO's proposals.
	DAOPath = "gno.land/r/gov/dao"
)

// ------------------------------------------------------------- governor --

// The governor (M1k, Jae 2026-10-14: "until I yield to GovDAO I want to be GovDAO alone"). Each bridge realm
// compiles a governor address beside its other launch values; while one is compiled and has not yielded, a
// decision is the governor's own direct call through the realm's Govern — the same closure, checks, queues and
// delays a proposal's execution runs, only who decides differs — and GovDAO's proposals are refused. The yield is
// one call on hlmailbox (Yield), which every realm reads, so no realm is ever governed apart from the others; from
// that block DAOPath's proxy is the only governor, as before M1k. A compiled governor of "" means GovDAO from the
// first block. This package keeps the rule and the page line; the realms keep the identity checks, since an
// identity is read from a live cur alone.

// DAOGoverns is whether DAOPath's proxy decides now: no governor was compiled, or the governor yielded at that
// block height (0 until the yield).
func DAOGoverns(governor address, yielded int64) bool { return governor == "" || yielded != 0 }

// GovernorLine is the line every bridge realm's page shows of who governs it.
func GovernorLine(governor address, yielded int64) string {
	switch {
	case governor == "":
		return "governor: " + DAOPath + " from the first block (no governor was compiled)"
	case yielded == 0:
		return "governor: " + string(governor) + " (until the yield) — it alone decides, by Govern from its own key, and " + DAOPath + "'s proposals are refused"
	}
	return "governor: " + DAOPath + " since height " + itoa(yielded) + " (" + string(governor) + " yielded)"
}

// GovernorJSON is the same for the agents: `"governor":"…","yielded":H` (no leading or trailing comma).
func GovernorJSON(governor address, yielded int64) string {
	return "\"governor\":" + strconv.Quote(string(governor)) + ",\"yielded\":" + itoa(yielded)
}

// Decision is one numbered change, as the realm's page shows it.
type Decision struct {
	ID        int64
	Kind      string // the builder's name, e.g. "set cap floor"
	Text      string // the parameters, as the builder wrote them into the proposal's description
	Params    any    // the parameters, typed, the realm's own
	Made      int64  // unix time the proposal was made (the builder call)
	Recorded  int64  // unix time the proposal executed: the decision's birth
	Due       int64  // unix time it may be applied: Recorded for an at-once change, Recorded + Delay for a queued one
	Applied   int64  // unix time it was applied; 0 while pending
	Cancelled int64  // unix time GovDAO cancelled it; 0 if it was not
	Spent     bool   // recorded with no effect (an unpause that would have cleared nothing)
	Note      string // what happened at execution, in words
}

// Pending is whether the decision still waits to be applied.
func (d *Decision) Pending() bool { return d.Applied == 0 && d.Cancelled == 0 && !d.Spent }

// Queued is whether the decision waits on its delay (pending, and not due at once).
func (d *Decision) Queued() bool { return d.Pending() && d.Due > d.Recorded }

// State is "pending", "applied", "cancelled" or "spent".
func (d *Decision) State() string {
	switch {
	case d.Cancelled != 0:
		return "cancelled"
	case d.Spent:
		return "spent"
	case d.Applied != 0:
		return "applied"
	}
	return "pending"
}

// Ledger numbers and keeps a realm's decisions. The zero value is empty.
type Ledger struct {
	seq int64
	all avl.Tree // key(id) → *Decision
}

func key(id int64) string {
	s := strconv.FormatInt(id, 10)
	return strings.Repeat("0", 12-len(s)) + s
}

// Record gives a decision the next number and keeps it. due is when it may be applied (now for at once).
func (l *Ledger) Record(kind, text string, params any, made, now, due int64) *Decision {
	l.seq++
	d := &Decision{ID: l.seq, Kind: kind, Text: text, Params: params, Made: made, Recorded: now, Due: due}
	l.all.Set(key(d.ID), d)
	return d
}

// Get is the decision with this number, or nil.
func (l *Ledger) Get(id int64) *Decision {
	v := l.all.Get(key(id))
	if v == nil {
		return nil
	}
	return v.(*Decision)
}

// Last is the number of the newest decision (0 if none).
func (l *Ledger) Last() int64 { return l.seq }

// Size is how many decisions were ever recorded.
func (l *Ledger) Size() int { return l.all.Size() }

// Apply marks a decision applied now, with a note.
func (l *Ledger) Apply(d *Decision, now int64, note string) {
	d.Applied = now
	if note != "" {
		d.Note = note
	}
}

// Spend marks a decision spent: recorded, no effect.
func (l *Ledger) Spend(d *Decision, note string) {
	d.Spent = true
	d.Note = note
}

// Cancel marks a pending decision cancelled now. It errors on a number that is not pending.
func (l *Ledger) Cancel(id, now int64) (*Decision, error) {
	d := l.Get(id)
	if d == nil {
		return nil, errors.New("no decision " + strconv.FormatInt(id, 10))
	}
	if !d.Pending() {
		return nil, errors.New("decision " + strconv.FormatInt(id, 10) + " is " + d.State() + ", not pending")
	}
	d.Cancelled = now
	return d, nil
}

// Due is a pending decision whose delay has passed, by number; it errors otherwise.
func (l *Ledger) Due(id, now int64) (*Decision, error) {
	d := l.Get(id)
	if d == nil {
		return nil, errors.New("no decision " + strconv.FormatInt(id, 10))
	}
	if !d.Pending() {
		return nil, errors.New("decision " + strconv.FormatInt(id, 10) + " is " + d.State() + ", not pending")
	}
	if now < d.Due {
		return nil, errors.New("decision " + strconv.FormatInt(id, 10) + " is due at " + strconv.FormatInt(d.Due, 10) + ", not before")
	}
	return d, nil
}

// Each walks every decision, oldest first, until fn returns true.
func (l *Ledger) Each(fn func(d *Decision) bool) {
	l.all.Iterate("", "", func(_ string, v any) bool { return fn(v.(*Decision)) })
}

// Expired is the one error a builder's closure returns: the proposal was made more than Deadline ago, so GovDAO
// marks it denied for good. Everything else a closure refuses is a panic, which leaves the proposal for a retry.
func Expired(made, now int64) error {
	if now-made > Deadline {
		return errors.New("the proposal is past its 14-day deadline (made at " + strconv.FormatInt(made, 10) + ", now " + strconv.FormatInt(now, 10) + ")")
	}
	return nil
}

// ---------------------------------------------------------------- pages --

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// Clocks says the clock factor and the delays it gives, for every realm's page: §8.3's check reads it against
// the served source, where the mainnet build's factor is 1.
func Clocks() string {
	return "clock factor " + itoa(Factor) + " (1 on mainnet; a devnet build is compiled with 8): the 7-day delay is " + itoa(Delay) +
		" s and the 14-day deadline " + itoa(Deadline) + " s of block time"
}

// ClocksJSON is the same for the agents: {"factor":…,"delay":…,"deadline":…}.
func ClocksJSON() string {
	return "{\"factor\":" + itoa(Factor) + ",\"delay\":" + itoa(Delay) + ",\"deadline\":" + itoa(Deadline) + "}"
}

// Page is the decisions page: for every kind, the pending decisions (up to PageMax) and the last PageMax executed
// ones, newest first.
func (l *Ledger) Page() string {
	if l.all.Size() == 0 {
		return "No decision yet: one exists only when a proposal made with a builder executes.\n"
	}
	kinds := []string{}
	pending := map[string][]*Decision{}
	done := map[string][]*Decision{}
	l.all.ReverseIterate("", "", func(_ string, v any) bool {
		d := v.(*Decision)
		if _, ok := pending[d.Kind]; !ok {
			kinds = append(kinds, d.Kind)
			pending[d.Kind] = nil
			done[d.Kind] = nil
		}
		if d.Pending() {
			if len(pending[d.Kind]) < PageMax {
				pending[d.Kind] = append(pending[d.Kind], d)
			}
		} else if len(done[d.Kind]) < PageMax {
			done[d.Kind] = append(done[d.Kind], d)
		}
		return false
	})
	var b strings.Builder
	for _, k := range kinds {
		b.WriteString("### " + k + "\n\n")
		if len(pending[k]) == 0 {
			b.WriteString("pending: none\n")
		} else {
			b.WriteString("pending:\n")
			for _, d := range pending[k] {
				b.WriteString("- " + line(d) + "\n")
			}
		}
		if len(done[k]) > 0 {
			b.WriteString("\nexecuted:\n")
			for _, d := range done[k] {
				b.WriteString("- " + line(d) + "\n")
			}
		}
		b.WriteString("\n")
	}
	return b.String()
}

func line(d *Decision) string {
	s := "#" + itoa(d.ID) + " " + d.State() + ": " + d.Text + " (recorded " + itoa(d.Recorded)
	if d.Queued() {
		s += ", due " + itoa(d.Due)
	}
	switch {
	case d.Applied != 0:
		s += ", applied " + itoa(d.Applied)
	case d.Cancelled != 0:
		s += ", cancelled " + itoa(d.Cancelled)
	}
	s += ")"
	if d.Note != "" {
		s += " — " + d.Note
	}
	return s
}

// JSON is every decision, oldest first, as a JSON array.
func (l *Ledger) JSON() string {
	var b strings.Builder
	b.WriteString("[")
	first := true
	l.all.Iterate("", "", func(_ string, v any) bool {
		d := v.(*Decision)
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString("{\"id\":" + itoa(d.ID) + ",\"kind\":" + strconv.Quote(d.Kind) + ",\"text\":" + strconv.Quote(d.Text) +
			",\"state\":" + strconv.Quote(d.State()) + ",\"made\":" + itoa(d.Made) + ",\"recorded\":" + itoa(d.Recorded) +
			",\"due\":" + itoa(d.Due) + ",\"applied\":" + itoa(d.Applied) + ",\"cancelled\":" + itoa(d.Cancelled) +
			",\"note\":" + strconv.Quote(d.Note) + "}")
		return false
	})
	b.WriteString("]")
	return b.String()
}

// Package hlroute is the state a bridge route realm keeps (bridge/PLAN.md §5.2–§5.5, §5.9), shared by r/hlgnot and
// r/hlbubble: the lock's counters and the supply identity, the claims in per-recipient queues, the two meters that
// rate-limit what is paid, the sweep queue, the send records a successor refunds by id, and GovDAO's decisions on
// the route's settings. It holds no coins and makes no call: the realm that owns a State moves the asset through
// the Env callbacks and asks hlmailbox what only the realm can ask. Every clock here is unix time, passed in.
package hlroute

import (
	"encoding/hex"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
)

const (
	Day = decisions.Day
	// MaxClaims is the most claims one Claim call pays (§5.4: n ≤ 20).
	MaxClaims = 20
	// MaxIDs is the most message ids one void, restore, credit or refund names.
	MaxIDs = 256
	// PageLines is how many waiting claims, and how many sweep entries, the route's page lists; the rest are
	// counted there and read by hundreds at claims/<from> and sweeps/<from>, so a flood of dust can never make
	// the page a member reads exceed a query's gas.
	PageLines = 100
	// PullPage is how many records one Pull hands to a successor (R13): the migration moves the claims, the sweep
	// entries and the sends a page at a time, so no page outgrows a block however long the route ran.
	PullPage = 500
	// MaxRangeClaims is the most credits (claims and sweep entries, voidable or not, R23) a range void's scan may
	// visit when it is made (R14): at ≈0.4M gas a credit on chain a thousand is ≈0.4B, inside a block with room;
	// GovDAO splits a bigger range by heights, from the last height a decision's note says it voided. The range is
	// closed at the height the proposal is made, so what it covers never grows after.
	MaxRangeClaims = 1000
	// guardianSeats are seats 1–4 (hlmailbox's numbering); a void's unpause option vacates at most maxGuardianSeats
	// of them (§5.3: two guardians at most per proposal).
	guardianSeats    = 4
	maxGuardianSeats = 2

	// Claim states.
	Open     = "open"     // credited, unpaid or paying
	Withheld = "withheld" // voided as withheld: the remainder stays booked, restorable at once
	Forged   = "forged"   // voided as forged: the remainder dropped, the paid part lost; restorable after 7 days
	Done     = "done"     // paid in full

	// Who credited a claim.
	BySigners = "signers" // the verifier (the signers until Proposal 2)
	ByVote    = "vote"    // GovDAO's credit by id

	// Decision kinds.
	KindCapFloor = "set cap floor"
	KindMaximum  = "set maximum"
	KindFee      = "set fee and minimum"
	KindFeeFloor = "set fee floor"
	KindRouter   = "set router"
	KindVoid     = "void"
	KindRestore  = "restore"
	KindCredit   = "credit"
	KindSweep    = "sweep"
	KindRefund   = "refund"
	// KindApplyRefund is GovDAO's own at-once apply of a queued refund decision (AT2): a refund is never Execute's.
	KindApplyRefund = "apply refund"
	KindWriteOff    = "write off"
	KindMigrate     = "migrate"
	KindCancel      = "cancel"

	one = int64(1_000_000) // 6 decimals on both sides

	maxInt64  = int64(1<<63 - 1)
	maxHeight = int64(9_999_999_999_999_999) // the height index's keys are 16 digits
)

// Launch are a route's compiled launch values.
type Launch struct {
	Symbol   string // "GNOT" or "BUBBLE"
	Fee      int64  // the flat fee on every send and the first installment of every claim
	Minimum  int64  // the least a send may carry
	FeeFloor int64  // the fee and the minimum never go below it
	CapFloor int64  // the day cap is max(CapFloor, 10% of the lock)
	Maximum  int64  // the most a send may carry
	Domain   uint32 // the destination's domain
	Router   [32]byte
	Now      int64 // deploy time: the meters start empty here
}

// Claim is one IOU the route owes a recipient (§5.4).
type Claim struct {
	ID     string // the message id, lowercase hex
	To     address
	Amount int64
	Paid   int64 // fee included
	At     int64 // credited at (unix time)
	Height int64 // credited at (block height): what a range names
	By     string
	State  string
	Seq    int64 // its place in the recipient's queue
	// QueueNext is set in a migration page only (R20): the predecessor's final counter for the recipient's queue, so
	// the successor's own credits land above every place a later page can claim. It is 0 on a stored claim.
	QueueNext int64
}

// Range names claims by when they were credited rather than by id: every claim credited at a block height from
// From to To inclusive, or — Since — every claim the verifier credited at a height at or above From, open above
// while a flag stands (the verifier's later credits are covered too) and closed by a void at the height it
// executes (claims credited after the vote were not decided on). Written "heights:<from>-<to>" or
// "since:<from>"; a guardian's payouts flag and the void builder take one in place of a list of ids, so one flag
// and one closure cover a flood larger than a list.
type Range struct {
	From, To int64
	Since    bool
}

// ParseRange reads a range; ok is false when s is not one (a list of ids, then). A malformed range panics.
func ParseRange(s string) (r Range, ok bool) {
	s = strings.TrimSpace(s)
	switch {
	case strings.HasPrefix(s, "heights:"):
		body := s[len("heights:"):]
		i := strings.Index(body, "-")
		if i < 0 {
			panic("hlroute: a height range is heights:<from>-<to>, not " + s)
		}
		from, to := parseHeight(body[:i]), parseHeight(body[i+1:])
		if to < from {
			panic("hlroute: the range runs from the lower height to the higher")
		}
		return Range{From: from, To: to}, true
	case strings.HasPrefix(s, "since:"):
		return Range{From: parseHeight(s[len("since:"):]), Since: true}, true
	}
	return Range{}, false
}

func parseHeight(s string) int64 {
	n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil || n < 1 || n > maxHeight {
		panic("hlroute: not a block height: " + s)
	}
	return n
}

// Covers is whether a claim credited at height — by the verifier, or not — is in the range.
func (r Range) Covers(height int64, verifier bool) bool {
	if r.Since {
		return verifier && height >= r.From && (r.To == 0 || height <= r.To)
	}
	return height >= r.From && height <= r.To
}

// String says the range in words.
func (r Range) String() string {
	if r.Since {
		s := "the verifier's credits since height " + itoa(r.From)
		if r.To != 0 {
			s += " up to height " + itoa(r.To)
		}
		return s
	}
	return "claims credited at heights " + itoa(r.From) + "-" + itoa(r.To)
}

// closed is the range as a void takes it at height: a Since range, or one reaching past height, ends there.
func (r Range) closed(height int64) Range {
	if r.Since && (r.To == 0 || r.To > height) || !r.Since && r.To > height {
		r.To = height
	}
	return r
}

// Remaining is what the claim still owes.
func (c *Claim) Remaining() int64 { return c.Amount - c.Paid }

// Meter is §5.4's bucket: a level that refills at a rate per day up to a ceiling, emptied at every payouts epoch.
// Frac carries the refill's remainder (in base units × seconds, below a day), so refills in any pieces sum to
// exactly rate a day.
type Meter struct {
	Level int64
	At    int64 // last refill
	Epoch int64 // the payouts epoch it last saw
	Frac  int64
}

// refill brings the meter up to now at rate a day, never above ceil; a new epoch empties it as of epochAt first.
// rate and ceil are at most a few billion tokens (2^63 base units over a day would overflow nothing here, as the
// elapsed seconds are capped at a day and rate%Day × Day < 2^33).
func (m *Meter) refill(now, rate, ceil, epoch, epochAt int64) {
	if m.Epoch != epoch {
		m.Level, m.At, m.Epoch, m.Frac = 0, epochAt, epoch, 0
	}
	if now <= m.At {
		return
	}
	el := now - m.At
	if el > Day {
		el = Day
		m.Frac = 0
	}
	num := (rate%Day)*el + m.Frac
	m.Level += (rate/Day)*el + num/Day
	m.Frac = num % Day
	if m.Level > ceil {
		m.Level, m.Frac = ceil, 0
	}
	m.At = now
}

// Queue is one recipient's claims, oldest first, and that recipient's own meter (a quarter of the bridge's).
type Queue struct {
	items    avl.Tree // seqKey(seq) → claim id: the open claims only (a voided or paid claim leaves the queue, R12)
	meter    Meter
	next     int64
	base     int64 // an import places a predecessor's claim at base + its old seq, so the pages keep the queue's order
	imported bool
}

// Send is one outgoing transfer's record, kept so a successor can refund it by id if it was never delivered.
type Send struct {
	From       address
	Amount     int64
	At         int64
	Refunded   int64 // when it was refunded, 0 if not
	WrittenOff int64 // when it was written off as delivered on Solana after its refund (AR1), 0 if not
	Imported   bool  // brought by a predecessor's page (AQ2): the only sends a refund may name
}

// SweepEntry is one entry of the sweep queue (§5.4): a credit that pays nobody until GovDAO directs it — a burn
// below the fee, to a realm or non-gno recipient, or above the lock — kept by id with the height it was credited
// at and who credited it, so a void names it by id or by range like a claim (R11): a forged entry is voided as
// forged (Voided: its amount leaves the sweep queue's balance and what is owed, so the identity closes) and
// restored after 7 days; a credit by id to its owner replaces it with a claim.
type SweepEntry struct {
	ID     string
	Amount int64
	Height int64
	By     string
	Voided bool
}

// Env is what the realm does for the state: the calls only a realm can make. Every field is set.
type Env struct {
	Flagged    func(id string, height int64, verifier bool) bool // a guardian's standing payouts flag on this route names the claim: by id, or by a range covering the height it was credited at (and whether the verifier credited it)
	ClearFlags func(fn string) bool                              // clears every key's flag for fn on this route (the void's unpause option)
	RemoveSeat func(seat int, holder address) bool               // vacates a guardian or watch-key seat if holder still has it (the void's unpause option); false, nothing done, if the occupant changed (R17)
	Delivered  func(id string) bool                              // hlmailbox marked the id done
	MarkDone   func(id string)                                   // marks an id done in hlmailbox (credit by vote)
	Epoch      func() int64                                      // hlmailbox's payouts epoch for this route now (a queue made by a decision starts there)
	Height     func() int64                                      // the block height now (a claim credited by a decision is credited at it; a range void closes at it)
	Pay        func(to address, amount int64)
	PayFee     func(amount int64)
	AddRoute     func(path string)        // registers a successor route with hlmailbox
	AnnouncedFor func(path string) string // the route ("GNOT" or "BUBBLE") a realm at this pkgpath announced itself to hlmailbox as a successor of (R25, AQ5), "" if it never did: a migrate names only a path announced for this route
	Predecessor  func() string            // the route whose migrate registered this realm with hlmailbox (hlmailbox.Predecessor of this realm's own path), "" for a launch route or a realm not registered yet (R31): a successor migrates on only once its own import has ended
	IsRoute      func(path string) bool   // whether hlmailbox registers a route at this pkgpath (R31): a migrate never names one
	Enrolled     func() (height, at int64) // the block height and time r/hlgov last dispatched a kind 6 enrolling this realm as the token's router on Solana, as it noted with hlmailbox (hlmailbox.Enrolled of this realm's own path); 0, 0 if never, or cleared by r/hlgov's cancel (AR1, R37): a refund waits 14 days after it, and a successor sends nothing before it (AT7)
}

// The three functions of a route a flag can pause (hlmailbox's names).
const (
	FnSends   = "sends"
	FnCredits = "credits"
	FnPayouts = "payouts"
)

// State is a route's whole state but the asset itself.
type State struct {
	Symbol string
	Domain uint32

	Fee, Minimum, FeeFloor, CapFloor, Maximum int64
	LaunchMinimum, LaunchCapFloor             int64 // the compiled floors no builder goes below

	Router   [32]byte
	OldRouter [32]byte
	OldUntil int64 // the old router's messages are accepted until this time (7 days after a swap)

	// The identity (§5.9): Lock = SentTotal − PaidTotal = supply + Owed + Voided − Lost, up to in-flight messages.
	SentTotal int64 // locked by sends (fees excluded)
	PaidTotal int64 // paid out of claims, fees included, and sweep payments
	Owed      int64 // credited, unpaid; the sweep queue included
	Voided    int64 // the unpaid remainder of claims voided as withheld
	Lost      int64 // the paid part of claims voided as forged, and the sends delivered on Solana after their refund, written off (AR1)
	Lock      int64
	Sweep     int64 // the sweep queue's balance, part of Owed

	claims   avl.Tree // id → *Claim, every claim ever credited
	credits  avl.Tree // heightKey(height, id) → id: the claims and the sweep entries by the height they were credited at, what a range walks
	queues   avl.Tree // recipient → *Queue
	waiting  avl.Tree // recipient → true while its queue holds an open claim — exact (set at a credit or a restore, dropped with the last open claim, R12): the cursor's ring and the page's walk
	cursor   string   // the last recipient served
	meter    Meter    // the bridge's meter
	sweeps   avl.Tree // id → *SweepEntry
	sends    avl.Tree // id → *Send
	refunds  avl.Tree // id → true: the sends refunded here, what refunds/<from> pages (AQ2)
	nRefunded     int64 // sends refunded here (the records held here: a refunded send goes with its page, R33)
	refundedTotal int64 // what they summed to
	nWrittenOff     int64 // sends written off as delivered on Solana after their refund (AR1), held here
	writtenOffTotal int64 // what they summed to
	nClaims  int64    // claims ever credited
	nOpen    int64    // claims open now
	exported int      // pages handed to the successor by Export (R13)
	imported int      // pages taken from a predecessor by Import, in order (R20)
	importing bool    // between a predecessor's first page and its last (AP4): Credit refuses, so no credit of this route's own can collide with a place a page still to come claims

	Ledger     decisions.Ledger
	MigratedTo string // the successor realm, once a migrate decision applied; every function then refuses
	MigratedAt int64
	LaunchSeen int64 // the launch time the meters were last emptied for
}

// New is a route's state with its launch values, the meters empty as of l.Now.
func New(l Launch) *State {
	s := &State{Symbol: l.Symbol, Domain: l.Domain, Fee: l.Fee, Minimum: l.Minimum, FeeFloor: l.FeeFloor, CapFloor: l.CapFloor,
		Maximum: l.Maximum, LaunchMinimum: l.Minimum, LaunchCapFloor: l.CapFloor, Router: l.Router}
	s.meter.At = l.Now
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func seqKey(n int64) string {
	s := itoa(n)
	return strings.Repeat("0", 12-len(s)) + s
}

// heightKey sorts the credits by height, then id.
func heightKey(h int64, id string) string {
	s := itoa(h)
	return strings.Repeat("0", 16-len(s)) + s + "|" + id
}

// Amount writes base units as whole tokens with the symbol: 12,000,000 → "12 GNOT".
func (s *State) Amount(n int64) string {
	neg := ""
	if n < 0 {
		neg, n = "-", -n
	}
	w := itoa(n / one)
	if f := n % one; f != 0 {
		fs := strconv.FormatInt(f+one, 10)[1:]
		w += "." + strings.TrimRight(fs, "0")
	}
	return neg + w + " " + s.Symbol
}

// CleanID is a message id as the state keys it: lowercase hex, no 0x; it errors on anything but 32 bytes.
func CleanID(id string) (string, error) {
	id = strings.TrimPrefix(strings.ToLower(strings.TrimSpace(id)), "0x")
	if b, err := hex.DecodeString(id); err != nil || len(b) != 32 {
		return "", errors.New("not a 32-byte message id in hex: " + id)
	}
	return id, nil
}

func mustID(id string) string {
	c, err := CleanID(id)
	if err != nil {
		panic("hlroute: " + err.Error())
	}
	return c
}

// ParseIDs reads a comma-separated list of message ids, refusing an empty list, a bad id and a repeat.
func ParseIDs(list string) []string {
	parts := strings.Split(list, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if strings.TrimSpace(p) == "" {
			continue
		}
		id := mustID(p)
		for _, x := range out {
			if x == id {
				panic("hlroute: id named twice: " + id)
			}
		}
		out = append(out, id)
	}
	if len(out) == 0 {
		panic("hlroute: no ids")
	}
	if len(out) > MaxIDs {
		panic("hlroute: more than " + strconv.Itoa(MaxIDs) + " ids")
	}
	return out
}

// Cap is the day cap: max(the floor, a tenth of the lock).
func (s *State) Cap() int64 {
	c := s.Lock / 10
	if c < s.CapFloor {
		c = s.CapFloor
	}
	return c
}

// Migrated is whether the lock went to a successor; every function refuses then.
func (s *State) Migrated() bool { return s.MigratedTo != "" }

func (s *State) mustNotBeMigrated() {
	if s.Migrated() {
		panic("hlroute: migrated to " + s.MigratedTo)
	}
}

// mustNotBeImporting refuses what a partial record set would mislead (R28) while a predecessor's pages are still
// arriving: a range void (a page brings claims at their old heights, inside any range closed earlier) and a
// migrate (the pages still at the predecessor could never reach the next route).
func (s *State) mustNotBeImporting(what string) {
	if s.importing {
		panic("hlroute: the predecessor's pages are still arriving (" + strconv.Itoa(s.imported) + " so far): " + what + " waits for the last page")
	}
}

// ---------------------------------------------------------------- sends --

// CheckSend is what a send must satisfy: a positive amount between the minimum and the maximum.
func (s *State) CheckSend(amount int64) {
	s.mustNotBeMigrated()
	if amount <= 0 {
		panic("hlroute: the amount must be positive")
	}
	if amount < s.Minimum {
		panic("hlroute: below the minimum of " + s.Amount(s.Minimum))
	}
	if amount > s.Maximum {
		panic("hlroute: above the per-message maximum of " + s.Amount(s.Maximum))
	}
}

// Send records an outgoing transfer that locked amount.
func (s *State) Send(now int64, id string, from address, amount int64) {
	id = mustID(id)
	if s.sends.Has(id) {
		panic("hlroute: a send with this id exists")
	}
	s.sends.Set(id, &Send{From: from, Amount: amount, At: now})
	s.SentTotal += amount
	s.Lock += amount
}

// SendOf is the record of a send by id, or nil.
func (s *State) SendOf(id string) *Send {
	v := s.sends.Get(mustID(id))
	if v == nil {
		return nil
	}
	return v.(*Send)
}

// Sends is how many sends are recorded.
func (s *State) Sends() int { return s.sends.Size() }

// RouterAccepts is whether a message from this sender is from the route's router: the current one, or the old one
// within the 7 days after a swap.
func (s *State) RouterAccepts(now int64, sender [32]byte) bool {
	if sender == s.Router {
		return true
	}
	return s.OldUntil > now && sender == s.OldRouter && s.OldRouter != ([32]byte{})
}

// -------------------------------------------------------------- credits --

// queue is a recipient's queue, made on first use with its meter empty as of now under the payouts epoch of now:
// a queue made after an epoch's reset never takes that reset (which would fill it from the reset's time, up to a
// whole quarter at once); it starts empty at its first credit, as §5.4 says of every meter.
func (s *State) queue(to address, now, epoch int64) *Queue {
	v := s.queues.Get(string(to))
	if v != nil {
		return v.(*Queue)
	}
	q := &Queue{}
	q.meter.At, q.meter.Epoch = now, epoch
	s.queues.Set(string(to), q)
	return q
}

// ClaimOf is a claim by id, or nil.
func (s *State) ClaimOf(id string) *Claim {
	v := s.claims.Get(mustID(id))
	if v == nil {
		return nil
	}
	return v.(*Claim)
}

// SweptOf is the amount swept under an id (0 if none), voided or not.
func (s *State) SweptOf(id string) int64 {
	if e := s.SweepOf(id); e != nil {
		return e.Amount
	}
	return 0
}

// SweepOf is a sweep entry by id, or nil.
func (s *State) SweepOf(id string) *SweepEntry {
	v := s.sweeps.Get(mustID(id))
	if v == nil {
		return nil
	}
	return v.(*SweepEntry)
}

// Credit books an incoming transfer: a claim in the recipient's queue, or — for a burn below the fee, one to a
// realm address (sweep), or one above the lock — the sweep queue. height is the block height now (what a range
// names the claim by); epoch is hlmailbox's payouts epoch for the route now (a fresh queue's meter starts there).
// It returns whether it was swept.
//
// A burn above the lock cannot be honest (a mint needs a lock and a burn needs supply, so the supply is never
// above the lock): it is swept, owed and paying nobody until GovDAO directs it, which also bounds every claim by
// the lock. An amount that would overflow what is owed is refused outright (the message stays undelivered), and so
// is every credit while a predecessor's pages are still arriving (AP4): the relayer brings the message again once
// the last page is in.
func (s *State) Credit(now, height, epoch int64, id string, to address, amount int64, by string, sweep bool) bool {
	s.mustNotBeMigrated()
	if s.importing {
		panic("hlroute: importing a predecessor's pages (" + strconv.Itoa(s.imported) + " so far): credits are refused until the last page has arrived")
	}
	id = mustID(id)
	if s.claims.Has(id) || s.sweeps.Has(id) {
		panic("hlroute: credited already: " + id)
	}
	if amount < 0 {
		panic("hlroute: a negative amount")
	}
	if amount > maxInt64-s.Owed {
		panic("hlroute: the amount would overflow what is owed")
	}
	if sweep || amount < s.Fee || amount > s.Lock {
		s.sweepIn(height, id, amount, by)
		return true
	}
	s.enqueue(now, height, epoch, id, to, amount, by)
	return false
}

// sweepIn books a credit in the sweep queue: owed, paying nobody, indexed by its credit height like a claim.
func (s *State) sweepIn(height int64, id string, amount int64, by string) {
	if height < 0 || height > maxHeight {
		panic("hlroute: not a block height")
	}
	s.sweeps.Set(id, &SweepEntry{ID: id, Amount: amount, Height: height, By: by})
	s.credits.Set(heightKey(height, id), id)
	s.Sweep += amount
	s.Owed += amount
}

func (s *State) enqueue(now, height, epoch int64, id string, to address, amount int64, by string) *Claim {
	if height < 0 || height > maxHeight {
		panic("hlroute: not a block height")
	}
	q := s.queue(to, now, epoch)
	q.next++
	c := &Claim{ID: id, To: to, Amount: amount, At: now, Height: height, By: by, State: Open, Seq: q.next}
	s.claims.Set(id, c)
	s.credits.Set(heightKey(height, id), id)
	q.items.Set(seqKey(c.Seq), id)
	s.waiting.Set(string(to), true)
	s.Owed += amount
	s.nClaims++
	s.nOpen++
	return c
}

// oldestOpen is the first open claim in a queue, or nil.
func (s *State) oldestOpen(q *Queue) *Claim {
	var found *Claim
	q.items.Iterate("", "", func(_ string, v any) bool {
		c := s.claims.Get(v.(string)).(*Claim)
		if c.State == Open {
			found = c
			return true
		}
		return false
	})
	return found
}

// nextRecipient is the recipient after the cursor in the ring, wrapping.
func (s *State) nextRecipient() string {
	next := ""
	s.waiting.Iterate(s.cursor+"\x00", "", func(k string, _ any) bool {
		next = k
		return true
	})
	if next == "" {
		s.waiting.Iterate("", "", func(k string, _ any) bool {
			next = k
			return true
		})
	}
	return next
}

// ResetMeters empties both meters as of now (the launch).
func (s *State) ResetMeters(now int64) {
	s.meter.Level, s.meter.At, s.meter.Frac = 0, now, 0
	s.queues.Iterate("", "", func(_ string, v any) bool {
		q := v.(*Queue)
		q.meter.Level, q.meter.At, q.meter.Frac = 0, now, 0
		return false
	})
}

// MeterLevels is the bridge meter's level now and a recipient's, after refilling under the given epoch.
func (s *State) MeterLevels(now int64, to address, epoch, epochAt int64) (bridge, recipient int64) {
	c := s.Cap()
	s.meter.refill(now, c, c, epoch, epochAt)
	bridge = s.meter.Level
	if v := s.queues.Get(string(to)); v != nil {
		q := v.(*Queue)
		q.meter.refill(now, c/4, c/4, epoch, epochAt)
		recipient = q.meter.Level
	}
	return bridge, recipient
}

// Claim pays up to n claims (n ≤ 20) taking recipients in turns: the oldest open claim of each recipient with
// something waiting, as much of it as both meters allow, the fee as its first installment, skipping a recipient
// whose meter is dry. epoch and epochAt are hlmailbox's payouts epoch for this route. It returns how many claims
// it paid something on; the payments went through env.PayFee and env.Pay.
func (s *State) Claim(now int64, n int, epoch, epochAt int64, env Env) int {
	s.mustNotBeMigrated()
	if n < 1 {
		panic("hlroute: n must be positive")
	}
	if n > MaxClaims {
		n = MaxClaims
	}
	paid := 0
	for visits := 0; paid < n && visits < 4*n && s.waiting.Size() > 0; visits++ {
		addr := s.nextRecipient()
		s.cursor = addr
		q := s.queues.Get(addr).(*Queue)
		c := s.oldestOpen(q)
		if c == nil {
			s.waiting.Remove(addr)
			continue
		}
		dayCap := s.Cap()
		s.meter.refill(now, dayCap, dayCap, epoch, epochAt)
		q.meter.refill(now, dayCap/4, dayCap/4, epoch, epochAt)
		avail := s.meter.Level
		if q.meter.Level < avail {
			avail = q.meter.Level
		}
		// never more than the lock holds (R26): a claim left standing above the lock — honest claims after a
		// forgery drained part of it, or a hand credit — is paid what the lock holds, and a dry lock is a skip, not
		// a payment the realm's SendCoins would revert, the cursor with it, for every recipient behind
		if avail > s.Lock {
			avail = s.Lock
		}
		fee := int64(0)
		if c.Paid == 0 {
			fee = s.Fee
			if fee > c.Amount {
				fee = c.Amount
			}
			if avail < fee || avail <= 0 {
				continue // dry: the fee is the first installment, whole
			}
		} else if avail <= 0 {
			continue
		}
		pay := c.Remaining() - fee
		if pay > avail-fee {
			pay = avail - fee
		}
		if fee > 0 {
			env.PayFee(fee)
		}
		if pay > 0 {
			env.Pay(c.To, pay)
		}
		total := fee + pay
		c.Paid += total
		s.meter.Level -= total
		q.meter.Level -= total
		s.PaidTotal += total
		s.Owed -= total
		s.Lock -= total
		if c.Remaining() == 0 {
			s.finish(c, q)
		}
		paid++
	}
	return paid
}

// finish takes a claim paid in full out of its queue; the record stays, as done.
func (s *State) finish(c *Claim, q *Queue) {
	c.State = Done
	s.dequeue(c, q)
	s.nOpen--
}

// dequeue takes a claim out of its queue; a queue left with no open claim leaves the ring (R12: nothing but
// open claims ever sits in a queue, so a flood of voided claims never stands ahead of the open ones).
func (s *State) dequeue(c *Claim, q *Queue) {
	q.items.Remove(seqKey(c.Seq))
	if q.items.Size() == 0 {
		s.waiting.Remove(string(c.To))
	}
}

// ------------------------------------------------------------ the void --

// void applies one void to a claim: withheld keeps the remainder booked; forged drops it and books the paid part
// as lost. A withheld claim may be re-voided as forged; a claim paid in full may be voided as forged (its paid
// part becomes lost), not as withheld. An open claim voided leaves its queue (R12).
func (s *State) void(c *Claim, forged bool) {
	rem := c.Remaining()
	switch c.State {
	case Open:
		s.Owed -= rem
		s.nOpen--
		s.dequeue(c, s.queues.Get(string(c.To)).(*Queue))
		if forged {
			s.Lost += c.Paid
			c.State = Forged
		} else {
			s.Voided += rem
			c.State = Withheld
		}
	case Withheld:
		if !forged {
			panic("hlroute: " + c.ID + " is withheld already")
		}
		s.Voided -= rem
		s.Lost += c.Paid
		c.State = Forged
	case Done:
		if !forged {
			panic("hlroute: " + c.ID + " is paid in full; only a void as forged books it")
		}
		s.Lost += c.Paid
		c.State = Forged
	default:
		panic("hlroute: " + c.ID + " is forged already")
	}
}

// voidable is whether a void as forged, or as withheld, can take the claim as it stands: an open claim either way,
// a withheld or a paid one as forged only. The list form refuses such ids when the proposal is made; the range
// form skips them.
func voidable(c *Claim, forged bool) bool {
	switch c.State {
	case Open:
		return true
	case Withheld, Done:
		return forged
	}
	return false
}

// voidSweep voids a sweep entry as forged (R11): its amount leaves the sweep queue's balance and what is owed, so
// a forged entry no longer holds the identity open; nothing was paid, so nothing is lost. The balance is the sum of
// the live entries (the queue is settled by id, R19), so an entry above it is a broken invariant, refused.
func (s *State) voidSweep(e *SweepEntry) {
	if e.Voided {
		panic("hlroute: " + e.ID + " is voided already")
	}
	if e.Amount > s.Sweep {
		panic("hlroute: " + e.ID + "'s " + s.Amount(e.Amount) + " exceeds the sweep queue's balance of " + s.Amount(s.Sweep))
	}
	e.Voided = true
	s.Sweep -= e.Amount
	s.Owed -= e.Amount
}

// restoreSweep is the inverse of voidSweep.
func (s *State) restoreSweep(e *SweepEntry) {
	if !e.Voided {
		panic("hlroute: " + e.ID + " is not voided")
	}
	e.Voided = false
	s.Sweep += e.Amount
	s.Owed += e.Amount
}

// sweepVoidable is whether a void can take a sweep entry as it stands: as forged only (an entry is withheld by
// nature — owed, paying nobody — so a void as withheld has nothing to do), and once.
func sweepVoidable(e *SweepEntry, forged bool) bool { return forged && !e.Voided }

// mustFitRange counts the credits a range covers now, voidable or not, and refuses above MaxRangeClaims (R28): the
// range was under the cap when the proposal was made (DraftVoid), but a predecessor's pages bring claims at their
// old heights — inside a range closed before they arrived — so the walk that voids it, at once or after the delay,
// is counted again before it voids anything; one above the cap holds the decision for GovDAO's cancel, who splits
// the range by heights.
func (s *State) mustFitRange(r Range) {
	n := 0
	s.eachInRange(r, func(*Claim) bool {
		n++
		return n > MaxRangeClaims
	}, func(*SweepEntry) bool {
		n++
		return n > MaxRangeClaims
	})
	if n > MaxRangeClaims {
		panic("hlroute: more than " + strconv.Itoa(MaxRangeClaims) + " credits in " + r.String() + " now (a predecessor's pages brought more since the proposal was made): cancel it and split the range by heights")
	}
}

// eachInRange walks the credits a range covers — the claims and the sweep entries, by height then id — until a
// callback returns true. A Since range still open (To 0) runs to the newest credit and covers the verifier's
// credits only.
func (s *State) eachInRange(r Range, fn func(c *Claim) bool, sfn func(e *SweepEntry) bool) {
	end := "~"
	if r.To != 0 {
		end = heightKey(r.To+1, "")
	}
	s.credits.Iterate(heightKey(r.From, ""), end, func(_ string, v any) bool {
		id := v.(string)
		if cv := s.claims.Get(id); cv != nil {
			c := cv.(*Claim)
			if r.Since && c.By != BySigners {
				return false
			}
			return fn(c)
		}
		e := s.sweeps.Get(id).(*SweepEntry)
		if r.Since && e.By != BySigners {
			return false
		}
		return sfn(e)
	})
}

// restore is the full inverse of either void; a claim with a remainder goes back into its queue at its place
// (R12). now and epoch make the recipient's queue if it has none (a successor restoring an imported claim).
func (s *State) restore(c *Claim, now, epoch int64) {
	rem := c.Remaining()
	switch c.State {
	case Withheld:
		s.Voided -= rem
		s.Owed += rem
	case Forged:
		s.Lost -= c.Paid
		s.Owed += rem
	default:
		panic("hlroute: " + c.ID + " is not voided")
	}
	if rem == 0 {
		c.State = Done
		return
	}
	c.State = Open
	s.nOpen++
	q := s.queue(c.To, now, epoch)
	q.items.Set(seqKey(c.Seq), c.ID)
	s.waiting.Set(string(c.To), true)
}

// ------------------------------------------------------------- drafts --

// Draft is a builder's checked parameters: what a proposal carries, decided and applied when it executes.
type Draft struct {
	Kind   string
	Text   string
	Params any
}

type (
	capFloorParams struct{ n int64 }
	maximumParams  struct{ n int64 }
	feeParams      struct{ fee, minimum int64 }
	feeFloorParams struct{ n int64 }
	routerParams   struct{ router [32]byte }
	// VoidParams are a void's: the ids left to void (the at-once ones are gone from the list once applied) or,
	// Ranged, the range of credits to void (closed at the height the proposal executed), and the unpause option's
	// parameters — the functions whose flags to clear and the seats to vacate — applied in the executing
	// transaction.
	VoidParams struct {
		IDs         []string
		Ranged      bool
		Range       Range
		Forged      bool
		UnpauseFns  []string
		RemoveSeats []int
		RemoveAddrs []address // the seats' holders when the proposal was made: a seat whose occupant changed is skipped (R17)
	}
	restoreParams struct{ ids []string }
	creditParams  struct {
		id     string
		to     address
		amount int64
	}
	sweepParams struct {
		ids []string // the entries to pay, by id (R19): their sum goes to `to` and they are dropped
		to  address
	}
	refundParams      struct{ ids []string }
	applyRefundParams struct{ id int64 } // the queued refund decision GovDAO applies at once (AT2)
	writeOffParams    struct{ ids []string }
	migrateParams     struct{ to string }
	cancelParams      struct{ id int64 }
)

// DraftCapFloor: the day cap's floor; never below the compiled launch floor, and its quarter never below the fee
// (a recipient's meter holds a quarter of the cap at most and the fee is a claim's first installment, whole: a
// quarter under the fee would stall every new recipient's first payment, with no flag and no alarm).
func (s *State) DraftCapFloor(n int64) Draft {
	s.mustNotBeMigrated()
	if n < s.LaunchCapFloor {
		panic("hlroute: the cap floor never goes below the launch floor of " + s.Amount(s.LaunchCapFloor))
	}
	if n/4 < s.Fee {
		panic("hlroute: the cap floor's quarter never goes below the fee of " + s.Amount(s.Fee) + " (a recipient's meter must hold the fee, the first installment)")
	}
	if n == s.CapFloor {
		panic("hlroute: the cap floor is " + s.Amount(n) + " already")
	}
	return Draft{KindCapFloor, "set cap floor to " + s.Amount(n) + " (now " + s.Amount(s.CapFloor) + ")", capFloorParams{n}}
}

// DraftMaximum: the per-message maximum; never below the minimum. The description reminds GovDAO of the order a
// raise takes (R15): the pausable ISM's per-message maximum on Solana (r/hlgov's kind 12) is raised first, since a
// send above it leaves gno.land and is refused at delivery for good — stranded until a refund by id.
func (s *State) DraftMaximum(n int64) Draft {
	s.mustNotBeMigrated()
	if n < s.Minimum || n < s.LaunchMinimum {
		panic("hlroute: the maximum never goes below the minimum of " + s.Amount(s.Minimum))
	}
	if n == s.Maximum {
		panic("hlroute: the maximum is " + s.Amount(n) + " already")
	}
	return Draft{KindMaximum, "set maximum to " + s.Amount(n) + " (now " + s.Amount(s.Maximum) + "); raise the Solana limit (kind 12) first; a send above the Solana maximum strands", maximumParams{n}}
}

// DraftFee: the fee and the minimum together; the fee not below the fee floor and not above a quarter of the cap
// floor (the most a recipient's meter can hold, and the fee is the first installment, whole), the minimum positive
// and not above the maximum.
func (s *State) DraftFee(fee, minimum int64) Draft {
	s.mustNotBeMigrated()
	if fee < s.FeeFloor {
		panic("hlroute: the fee never goes below the fee floor of " + s.Amount(s.FeeFloor))
	}
	if fee > s.CapFloor/4 {
		panic("hlroute: the fee never goes above a quarter of the cap floor (" + s.Amount(s.CapFloor/4) + "): a recipient's meter holds a quarter at most and the fee is the first installment, whole")
	}
	if minimum <= 0 || minimum > s.Maximum {
		panic("hlroute: the minimum must be positive and not above the maximum of " + s.Amount(s.Maximum))
	}
	if fee == s.Fee && minimum == s.Minimum {
		panic("hlroute: nothing changes")
	}
	return Draft{KindFee, "set fee to " + s.Amount(fee) + " and minimum to " + s.Amount(minimum) + " (now " + s.Amount(s.Fee) + " and " + s.Amount(s.Minimum) + ")", feeParams{fee, minimum}}
}

// DraftFeeFloor: the fee floor; not above the fee, not negative.
func (s *State) DraftFeeFloor(n int64) Draft {
	s.mustNotBeMigrated()
	if n < 0 || n > s.Fee {
		panic("hlroute: the fee floor must be between 0 and the fee of " + s.Amount(s.Fee))
	}
	if n == s.FeeFloor {
		panic("hlroute: the fee floor is " + s.Amount(n) + " already")
	}
	return Draft{KindFeeFloor, "set fee floor to " + s.Amount(n) + " (now " + s.Amount(s.FeeFloor) + ")", feeFloorParams{n}}
}

// DraftRouter: the remote router; the old one's messages stay accepted 7 days after the swap applies.
func (s *State) DraftRouter(router [32]byte, text string) Draft {
	s.mustNotBeMigrated()
	if router == ([32]byte{}) {
		panic("hlroute: the router is all zeros")
	}
	if router == s.Router {
		panic("hlroute: that is the router already")
	}
	return Draft{KindRouter, "set router to " + text, routerParams{router}}
}

// ParseFns reads a comma-separated list of the three functions, "" for none; no repeats.
func ParseFns(fns string) []string {
	var out []string
	for _, p := range strings.Split(fns, ",") {
		fn := strings.TrimSpace(p)
		if fn == "" {
			continue
		}
		if fn != FnSends && fn != FnCredits && fn != FnPayouts {
			panic("hlroute: the functions are sends, credits and payouts, not " + fn)
		}
		for _, x := range out {
			if x == fn {
				panic("hlroute: " + fn + " named twice")
			}
		}
		out = append(out, fn)
	}
	return out
}

// ParseSeats reads a comma-separated list of seat numbers (1–6), "" for none; no repeats, and two guardian seats
// (1–4) at most — §5.3's cap on guardian changes per proposal, the same as hlmailbox's rotate seats, so no void
// vacates the four guardians in one stroke.
func ParseSeats(seats string) []int {
	var out []int
	g := 0
	for _, p := range strings.Split(seats, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil || n < 1 || n > 6 {
			panic("hlroute: the seat must be 1 to 6, not " + p)
		}
		for _, x := range out {
			if x == n {
				panic("hlroute: seat " + p + " named twice")
			}
		}
		if n <= guardianSeats {
			g++
		}
		out = append(out, n)
	}
	if g > maxGuardianSeats {
		panic("hlroute: two guardian seats at most per proposal")
	}
	return out
}

// seatsText writes seat removals as seat:address pairs.
func seatsText(seats []int, addrs []address) string {
	parts := make([]string, len(seats))
	for i, n := range seats {
		parts[i] = strconv.Itoa(n) + ":" + string(addrs[i])
	}
	return strings.Join(parts, ",")
}

// DraftVoid: void credits by id — a list of up to MaxIDs ids, claims or sweep entries (an entry as forged only),
// or a Range ("heights:<from>-<to>", every credit at those heights; "since:<from>", every credit the verifier made
// at or after it), closed at height — the block height the proposal is made at (R14), so what it covers never
// grows before it executes — and covering at most MaxRangeClaims credits, voidable or not (R23: the walk at
// execution visits them all), else GovDAO splits it by heights — as withheld or forged, with the unpause option —
// the functions whose flags to clear (comma
// separated, "" for none) and the seats to vacate (comma separated, "" for none; seatOf gives each seat's holder
// now, recorded so a seat whose occupant changes before the proposal executes is skipped, R17), applied in the
// same closure as the void so the void and the reopening never execute in the wrong order (§5.3). A range must
// cover a credit the void can take when the proposal is made; one in it the void cannot take as it stands
// (forged already; withheld, paid or a sweep entry, for a void as withheld) is skipped, not refused.
func (s *State) DraftVoid(ids string, forged bool, unpauseFns, removeSeats string, height int64, seatOf func(seat int) address) Draft {
	s.mustNotBeMigrated()
	fns, seats := ParseFns(unpauseFns), ParseSeats(removeSeats)
	addrs := make([]address, len(seats))
	for i, seat := range seats {
		if addrs[i] = seatOf(seat); addrs[i] == "" {
			panic("hlroute: seat " + strconv.Itoa(seat) + " is empty")
		}
	}
	how := "withheld"
	if forged {
		how = "forged"
	}
	p := VoidParams{Forged: forged, UnpauseFns: fns, RemoveSeats: seats, RemoveAddrs: addrs}
	var text string
	if r, ok := ParseRange(ids); ok {
		s.mustNotBeImporting("a range void")
		r = r.closed(height)
		// the cap counts every credit the scan visits, voidable or not (R23): the walk at execution covers them
		// all, so a range over a flood voided already costs as much as the flood; the decision's note names the
		// last height it voided, where the next range starts
		n, v := 0, 0
		s.eachInRange(r, func(c *Claim) bool {
			n++
			if voidable(c, forged) {
				v++
			}
			return n > MaxRangeClaims
		}, func(e *SweepEntry) bool {
			n++
			if sweepVoidable(e, forged) {
				v++
			}
			return n > MaxRangeClaims
		})
		if n > MaxRangeClaims {
			panic("hlroute: more than " + strconv.Itoa(MaxRangeClaims) + " credits in " + r.String() + ", voidable or not: split the range by heights")
		}
		if v == 0 {
			panic("hlroute: no claim to void in " + r.String())
		}
		p.Ranged, p.Range = true, r
		text = "void as " + how + ": " + r.String()
	} else {
		list := ParseIDs(ids)
		for _, id := range list {
			if e := s.SweepOf(id); e != nil {
				switch {
				case !forged:
					panic("hlroute: " + id + " is a sweep entry: voided as forged only")
				case e.Voided:
					panic("hlroute: " + id + " is voided already")
				}
				continue
			}
			c := s.ClaimOf(id)
			if c == nil {
				panic("hlroute: no claim or sweep entry " + id)
			}
			switch {
			case c.State == Forged:
				panic("hlroute: " + id + " is forged already")
			case c.State == Withheld && !forged:
				panic("hlroute: " + id + " is withheld already")
			case c.State == Done && !forged:
				panic("hlroute: " + id + " is paid in full; only a void as forged books it")
			}
		}
		p.IDs = list
		text = "void as " + how + ": " + strings.Join(list, ",")
	}
	if len(fns) > 0 {
		text += ", and unpause " + strings.Join(fns, ",")
	}
	if len(seats) > 0 {
		text += ", removing seats " + seatsText(seats, addrs)
	}
	return Draft{KindVoid, text, p}
}

// DraftRestore: restore voided claims, voided sweep entries, or written-off sends, by id — a write-off's inverse
// (R38): a mistaken write-off (a record two providers showed differently read as delivered, a neighbouring id in
// a list) books lost for the deployment's life, the watch's "mistaken void" alarm stands as long, and a later
// forged credit up to that amount moves the alarm's figure and trips nothing; the restore clears the mark and
// takes the amount back out of lost, after 7 days like a forged claim's restore, since it re-opens the identity.
func (s *State) DraftRestore(ids string) Draft {
	s.mustNotBeMigrated()
	list := ParseIDs(ids)
	for _, id := range list {
		if e := s.SweepOf(id); e != nil {
			if !e.Voided {
				panic("hlroute: " + id + " is not voided")
			}
			continue
		}
		if sd := s.SendOf(id); sd != nil {
			if sd.WrittenOff == 0 {
				panic("hlroute: " + id + " is a send that is not written off: nothing to restore")
			}
			continue
		}
		c := s.ClaimOf(id)
		if c == nil || (c.State != Withheld && c.State != Forged) {
			panic("hlroute: " + id + " is not voided")
		}
	}
	return Draft{KindRestore, "restore: " + strings.Join(list, ","), restoreParams{list}}
}

// DraftCredit: credit a claim by id, by hand (§5.3): refused for an id already done unless its claim stands
// voided, or the id is a sweep entry's (R11) — the credit then replaces the entry with the claim it names, the
// cure for a burn to a realm or non-gno recipient, or a diverted credit. The amount is at most the lock (R26,
// R7's rule for the verifier's credits: a credit above the lock cannot be honest, and a claim above it would ask
// Claim for coins the lock does not hold); the closure asks again.
func (s *State) DraftCredit(id string, to address, amount int64, delivered bool) Draft {
	s.mustNotBeMigrated()
	id = mustID(id)
	if amount <= 0 {
		panic("hlroute: the amount must be positive")
	}
	if amount > s.Lock {
		panic("hlroute: the amount " + s.Amount(amount) + " is above the lock of " + s.Amount(s.Lock) + " (a credit above the lock cannot be honest)")
	}
	text := "credit " + id + " to " + string(to) + " for " + s.Amount(amount)
	if c := s.ClaimOf(id); c != nil {
		if c.State != Withheld && c.State != Forged {
			panic("hlroute: " + id + " is credited already and not voided")
		}
	} else if e := s.SweepOf(id); e != nil {
		text += " (replacing the sweep entry of " + s.Amount(e.Amount) + ")"
	} else if delivered {
		panic("hlroute: " + id + " is done already")
	}
	return Draft{KindCredit, text, creditParams{id, to, amount}}
}

// DraftSweep: pay sweep entries, named by id (comma separated, up to MaxIDs), to an address — their sum, at most
// the lock (R11: a forged entry above the lock is voided, never paid out of coins the lock does not hold). The
// queue is settled by id (R19): a paid entry is dropped with its index, so it never stands to be credited by id or
// voided a second time, and the counters never go negative. A voided entry is restored first; a claim's id is no
// entry's; an entry voided or gone by the time the payment applies is skipped and the note says so.
func (s *State) DraftSweep(ids string, to address) Draft {
	s.mustNotBeMigrated()
	list := ParseIDs(ids)
	sum := int64(0)
	for _, id := range list {
		e := s.SweepOf(id)
		switch {
		case e == nil && s.ClaimOf(id) != nil:
			panic("hlroute: " + id + " is a claim, not a sweep entry")
		case e == nil:
			panic("hlroute: no sweep entry " + id)
		case e.Voided:
			panic("hlroute: " + id + " is voided; restore it first")
		}
		sum += e.Amount
	}
	if sum > s.Lock {
		panic("hlroute: the entries sum to " + s.Amount(sum) + ", above the lock's " + s.Amount(s.Lock))
	}
	return Draft{KindSweep, "pay " + s.Amount(sum) + " of the sweep queue to " + string(to) + ": " + strings.Join(list, ","), sweepParams{list, to}}
}

// DraftRefund: refund sends by id to their senders — a successor's duty, over the sends it imported from its
// predecessor (AQ2, §5.3): a refunded send stays deliverable on Solana, so only a send addressed to a router the
// token no longer enrolls is ever refunded, after kind 6 enrolled this realm — which the realm cannot see, so it
// reads the note r/hlgov leaves with the mailbox when it dispatches a kind 6 for this route (Env.Enrolled) and
// refuses until the note is 14 days old (AR1, R37, mustBeEnrolled; asked again when the refund applies): a refund
// that lands before kind 6 lets one stranger's Reemit and delivery of the refunded send mint it twice, with no
// realm able to refuse the message. Necessary, not sufficient: the member checks hlwatch first, which reads the
// token's enrolled router on Solana and the kind 6's state there, alarms a refund proposal whose successor the
// token has not enrolled and prints DELIVERED beside any id Solana processed — and the apply, after the 7 days,
// is GovDAO's own at-once decision (DraftApplyRefund, AT2), never anyone's Execute, so that check stands between
// the delay and the coins. A live route's own send, stranded or not, is never refunded: it waits for a kind 12
// (§5.4). The sum is at most the lock (R30, the sweep payment's bound: a forgery paid before its void can leave
// the lock short of the sends it imported), checked again when it applies.
func (s *State) DraftRefund(ids string, now int64, env Env) Draft {
	s.mustNotBeMigrated()
	s.mustBeEnrolled(now, env)
	list := ParseIDs(ids)
	sum := int64(0)
	for _, id := range list {
		sd := s.SendOf(id)
		switch {
		case sd == nil || sd.Refunded != 0:
			panic("hlroute: " + id + " is not a send to refund")
		case !sd.Imported:
			panic("hlroute: " + id + " is this route's own send: a stranded send waits for a kind 12 on Solana, never a refund (a refund is a successor's, over the sends it imported)")
		}
		sum += sd.Amount
	}
	if sum > s.Lock {
		panic("hlroute: the sends sum to " + s.Amount(sum) + ", above the lock's " + s.Amount(s.Lock))
	}
	return Draft{KindRefund, "refund " + s.Amount(sum) + " of sends imported from the predecessor (14 days after kind 6's dispatch enrolled this realm) to their senders: " + strings.Join(list, ","), refundParams{list}}
}

// EnrolmentWait is how long a refund waits after r/hlgov's dispatch of the kind 6 enrolling this route (R37, F27):
// two of the 7-day delays — a week for the delivery to Solana and a week for Solana's own clock, since the admin
// program executes a kind 6 7 days after it is recorded there, so a week from the dispatch always ended before
// the enrolment could take effect. A hold defers Solana further, which the realm cannot see: hlwatch and the
// relayer read the token's enrolled router there.
const EnrolmentWait = 2 * decisions.Delay

// mustBeEnrolled refuses a refund until kind 6 has enrolled this route on Solana for 14 days (EnrolmentWait), by
// the note r/hlgov leaves with the mailbox when it dispatches one (AR1, R37) — a cancelled kind 6 clears the note
// (hlmailbox.ClearEnrolled, from r/hlgov's cancel), so the wait restarts with a re-proposal. The latest note
// counts — a later kind 6 for the route restarts the wait; a refund is irreversible and two weeks are cheap.
func (s *State) mustBeEnrolled(now int64, env Env) {
	h, at := env.Enrolled()
	if h == 0 {
		panic("hlroute: no kind 6 has enrolled this route on Solana yet (none dispatched from r/hlgov): a refund waits 14 days after the enrolment, since a refunded send stays deliverable there until the predecessor's router is replaced")
	}
	if now < at+EnrolmentWait {
		panic("hlroute: kind 6 enrolling this route was dispatched at height " + itoa(h) + ", " + itoa(now-at) + " s ago: a refund waits 14 days after it (until " + itoa(at+EnrolmentWait) + "): a week for the delivery and a week for Solana's own clock, which executes a kind 6 7 days after recording it; a hold defers it further, which hlwatch reads there")
	}
}

// DraftApplyRefund: GovDAO's own at-once apply of a queued refund decision whose 7 days have passed (AT2). A refund
// is the one decision whose gate the realm cannot read — Solana's: the token's router there must be this realm and
// the kind 6 executed, which hlwatch reads and alarms NOT ENROLLED ON SOLANA while it is not — and anyone's
// Execute on the note alone let a refunded sender, his id in the proposal's description, apply his refund the day
// it matured while a kind 6 deferred by one flag left the predecessor the router, then deliver his send there
// with the published tool: minted twice, the lock short for good. So Execute refuses the kind, and a refund is
// applied by this builder alone — at once, like an unpause — the member having read hlwatch's gate before the
// vote. The apply is the delay's own (apply's refund branch: mustBeEnrolled's 14-day note asked again, the sum at
// most the lock, a send refunded since skipped), and the realm asks its payouts flag of it as of a sweep payment.
// Refused — when the proposal is made and again when it executes, the proposal surviving for a retry — for a
// decision that is no refund, one not pending (applied, cancelled), one whose delay has not passed, and until the
// note is 14 days old. The description names the refund decision and carries its text, the ids included.
func (s *State) DraftApplyRefund(id, now int64, env Env) Draft {
	s.mustNotBeMigrated()
	d := s.refundToApply(id, now, env)
	return Draft{KindApplyRefund, "apply refund decision " + itoa(id) + " at once (" + d.Text + "), after hlwatch's check that the token's router on Solana is this realm", applyRefundParams{id}}
}

// refundToApply is the queued refund decision an apply names, as it stands now: a refund, pending, its delay
// passed, the enrolment note 14 days old (mustBeEnrolled; asked once more by the refund's own apply).
func (s *State) refundToApply(id, now int64, env Env) *decisions.Decision {
	d := s.Ledger.Get(id)
	if d == nil {
		panic("hlroute: no decision " + itoa(id))
	}
	if d.Kind != KindRefund {
		panic("hlroute: decision " + itoa(id) + " is of kind " + d.Kind + ", not refund: an apply refund names a queued refund decision")
	}
	if !d.Pending() {
		panic("hlroute: refund decision " + itoa(id) + " is " + d.State() + ", not pending")
	}
	if now < d.Due {
		panic("hlroute: refund decision " + itoa(id) + " is queued until " + itoa(d.Due) + " (" + itoa(d.Due-now) + " s more): its 7 days have not passed")
	}
	s.mustBeEnrolled(now, env)
	return d
}

// DraftWriteOff: book refunded sends, by id (comma separated, up to MaxIDs), as lost (AR1) — a refunded send
// delivered on Solana after all, by a stranger's Reemit before kind 6 replaced the predecessor's router or in the
// day a hold's lift leaves, minted a second time against nothing, and no builder but this one closes the
// identity: lock = sentTotal − paidTotal = supply + owed + voided − lost, the amount lost. Only a refunded send,
// once; the realm cannot see Solana, so the member reads hlwatch's DELIVERED line for each id first and the
// description says so. After 7 days; an id written off by another decision since is skipped and counted.
func (s *State) DraftWriteOff(ids string) Draft {
	s.mustNotBeMigrated()
	list := ParseIDs(ids)
	sum := int64(0)
	for _, id := range list {
		sd := s.SendOf(id)
		switch {
		case sd == nil || sd.Refunded == 0:
			panic("hlroute: " + id + " is not a refunded send: only a send delivered on Solana after its refund is written off")
		case sd.WrittenOff != 0:
			panic("hlroute: " + id + " is written off already")
		}
		sum += sd.Amount
	}
	return Draft{KindWriteOff, "write off " + s.Amount(sum) + " of refunded sends delivered on Solana after their refund (hlwatch's DELIVERED line names the id): " + strings.Join(list, ","), writeOffParams{list}}
}

// DraftMigrate: the lock, the claims and the send records go to a successor realm at pkgpath — a deployed
// realm's, never a sub-identity's (`host#subpath`; the mailbox refuses such a route too), never a route the
// mailbox registers already (R31: the mailbox would refuse it when the migration applies, a week on, the vote
// wasted), and one that announced itself to the mailbox from its own code for this route (Env.AnnouncedFor: the
// symbol it named, "" if it never announced itself, R25 and AQ5), so the lock never goes to a path with no realm
// behind it — a typo, or an undeployed path whose namespace owner could deploy anything there and pull it — nor
// to the other token's successor by a slip. A route that succeeds another migrates on only once its own import
// has ended (R28, R31): before page 0 nothing has moved, and its MigratedTo would make its Import refuse, the
// predecessor's Pull revert for ever and the lock sit on the first predecessor, which refuses everything, with no
// decision that reaches it. The same checks are made again when the migration applies (mustMigrate).
func (s *State) DraftMigrate(to, self string, env Env) Draft {
	s.mustAllowMigrate(to)
	if !strings.HasPrefix(to, "gno.land/r/") || strings.Contains(to, "#") || to == self {
		panic("hlroute: the successor is another realm under gno.land/r/")
	}
	s.mustMigrate(to, env)
	return Draft{KindMigrate, "migrate to " + to + " (announced as the " + s.Symbol + " route's successor)", migrateParams{to}}
}

// mustAllowMigrate is a migrated route's one exception to "every function refuses" (AR2): before page 0 nothing has
// moved — the lock and the counters go with the first page — so while the successor named has pulled nothing a
// second migrate re-points the migration to another successor (7 days, like the first; the mailbox replaces the
// registration), the cure for a successor that never pulls or whose driver refuses every caller, which would
// otherwise hold the lock on a predecessor that refuses everything, with no decision that reaches it. The same
// successor is refused (nothing to re-point); once page 0 is pulled the migration is under way and no decision
// re-points it. Asked when the proposal is made, when it executes and when the migration would apply.
func (s *State) mustAllowMigrate(to string) {
	if !s.Migrated() {
		return
	}
	if s.exported > 0 {
		panic("hlroute: migrated to " + s.MigratedTo + ": the successor pulled " + strconv.Itoa(s.exported) + " pages already (the lock moved with page 0); a migration under way is never re-pointed")
	}
	if to == s.MigratedTo {
		panic("hlroute: migrated to " + to + " already (nothing pulled yet): a re-point names another successor")
	}
}

// mustMigrate is every check a migrate to `to` must pass against the live state, when the proposal is made and
// again when the migration would apply (R31): this route's own import, if it succeeds another, ended — page 0 in
// (nothing pulled is "page 0 is not in yet") and the last page too (R28) — the path no route the mailbox registers
// already, and announced for this route (R25, AQ5). A failure when the migration would apply leaves the decision
// pending for a retry or a cancel, never spent.
func (s *State) mustMigrate(to string, env Env) {
	s.mustNotBeImporting("a migrate")
	if pred := env.Predecessor(); pred != "" && s.imported == 0 {
		panic("hlroute: page 0 is not in yet: this route succeeds " + pred + " and has pulled nothing; a migrate waits for the last page of its own import")
	}
	if env.IsRoute(to) {
		panic("hlroute: the successor " + to + " is a route already")
	}
	s.mustBeAnnouncedFor(to, env.AnnouncedFor(to))
}

// mustBeAnnouncedFor refuses a successor that never announced itself, or announced itself for the other route.
func (s *State) mustBeAnnouncedFor(to, announcedFor string) {
	switch announcedFor {
	case "":
		panic("hlroute: the successor " + to + " has not announced itself to the mailbox (hlmailbox.AnnounceSuccessor, from its own code)")
	case s.Symbol:
	default:
		panic("hlroute: the successor " + to + " announced itself as the " + announcedFor + " route's successor, not this " + s.Symbol + " route's")
	}
}

// DraftCancel: cancel a pending decision of this route.
func (s *State) DraftCancel(id int64) Draft {
	d := s.Ledger.Get(id)
	if d == nil || !d.Pending() {
		panic("hlroute: decision " + itoa(id) + " is not pending")
	}
	return Draft{KindCancel, "cancel decision " + itoa(id) + " (" + d.Text + ")", cancelParams{id}}
}

// ------------------------------------------------------------ deciding --

// Decide is what a builder's closure does when its proposal executes: it records the decision and settles the
// at-once test against the live state — a lowering, a cancel, a restore of a withheld claim and the void of ids a
// guardian's standing payouts flag names apply now; everything else waits 7 days for Execute. A migrate is
// checked again here (R31, AR2: the state may have moved since the proposal was made) and a cancel, or a migrate
// that re-points a migration nothing was pulled from, is taken on a migrated route.
func (s *State) Decide(made, now int64, d Draft, env Env) *decisions.Decision {
	if d.Kind != KindCancel && d.Kind != KindMigrate {
		s.mustNotBeMigrated()
	}
	record := func(due int64, params any) *decisions.Decision {
		return s.Ledger.Record(d.Kind, d.Text, params, made, now, due)
	}
	switch p := d.Params.(type) {
	case capFloorParams:
		if p.n <= s.CapFloor {
			dec := record(now, p)
			s.apply(dec, now, env)
			s.Ledger.Apply(dec, now, "at once: a lowering")
			return dec
		}
		return s.queued(record(now+decisions.Delay, p))
	case maximumParams:
		if p.n <= s.Maximum {
			dec := record(now, p)
			s.apply(dec, now, env)
			s.Ledger.Apply(dec, now, "at once: a lowering")
			return dec
		}
		return s.queued(record(now+decisions.Delay, p))
	case feeParams:
		if p.fee <= s.Fee && p.minimum <= s.Minimum {
			dec := record(now, p)
			s.apply(dec, now, env)
			s.Ledger.Apply(dec, now, "at once: a lowering")
			return dec
		}
		return s.queued(record(now+decisions.Delay, p))
	case feeFloorParams:
		if p.n <= s.FeeFloor {
			dec := record(now, p)
			s.apply(dec, now, env)
			s.Ledger.Apply(dec, now, "at once: a lowering")
			return dec
		}
		return s.queued(record(now+decisions.Delay, p))
	case VoidParams:
		// per credit, once, now: a claim or sweep entry some guardian's standing payouts flag names — by id, or by
		// a range covering its credit — is voided at once, the rest wait in the same decision (the list of those
		// left, or the range, closed when the proposal was made); a range skips a credit the void cannot take as
		// it stands
		var later []string
		n, skipped, queued := 0, 0, 0
		last := int64(0) // the last height voided at once (the walk is by height), named in the note (R23)
		rest := VoidParams{Forged: p.Forged}
		if p.Ranged {
			r := p.Range // closed at the height the proposal was made (R14)
			s.mustFitRange(r)
			s.eachInRange(r, func(c *Claim) bool {
				switch {
				case !voidable(c, p.Forged):
					skipped++
				case env.Flagged(c.ID, c.Height, c.By == BySigners):
					s.void(c, p.Forged)
					n++
					last = c.Height
				default:
					queued++
				}
				return false
			}, func(e *SweepEntry) bool {
				switch {
				case !sweepVoidable(e, p.Forged):
					skipped++
				case env.Flagged(e.ID, e.Height, e.By == BySigners):
					s.voidSweep(e)
					n++
					last = e.Height
				default:
					queued++
				}
				return false
			})
			rest.Ranged, rest.Range = true, r
		} else {
			// an id the void cannot take as it stands — voided by another decision since the proposal was made,
			// paid in full under a void as withheld, or gone — is skipped and counted, the range form's rule, never
			// a panic that blocks the whole proposal with its unpause option and seat removals (R22)
			for _, id := range p.IDs {
				if e := s.SweepOf(id); e != nil {
					switch {
					case !sweepVoidable(e, p.Forged):
						skipped++
					case env.Flagged(id, e.Height, e.By == BySigners):
						s.voidSweep(e)
						n++
					default:
						later = append(later, id)
					}
					continue
				}
				c := s.ClaimOf(id)
				switch {
				case c == nil || !voidable(c, p.Forged):
					skipped++
				case env.Flagged(id, c.Height, c.By == BySigners):
					s.void(c, p.Forged)
					n++
				default:
					later = append(later, id)
				}
			}
			rest.IDs, queued = later, len(later)
		}
		for _, fn := range p.UnpauseFns {
			env.ClearFlags(fn)
		}
		// a seat is vacated only while the key the proposal named still holds it (R17): a replacement that landed
		// in between stays, and the note says so
		var vacated, kept []string
		for i, seat := range p.RemoveSeats {
			if env.RemoveSeat(seat, p.RemoveAddrs[i]) {
				vacated = append(vacated, strconv.Itoa(seat))
			} else {
				kept = append(kept, strconv.Itoa(seat))
			}
		}
		note := itoa(int64(n)) + " voided at once (named by a guardian's payouts flag)"
		if p.Ranged {
			note += " of " + rest.Range.String()
		}
		if skipped > 0 {
			note += ", " + itoa(int64(skipped)) + " skipped (not voidable as it stands)"
		}
		if len(p.UnpauseFns) > 0 {
			note += ", unpaused " + strings.Join(p.UnpauseFns, ",")
		}
		if len(vacated) > 0 {
			note += ", seats " + strings.Join(vacated, ",") + " vacated"
		}
		if len(kept) > 0 {
			note += ", seats " + strings.Join(kept, ",") + " skipped (the occupant changed since the proposal was made)"
		}
		lastNote := ""
		if p.Ranged && n > 0 {
			lastNote = ", last voided at height " + itoa(last)
		}
		if queued == 0 {
			dec := record(now, VoidParams{Forged: p.Forged, UnpauseFns: p.UnpauseFns, RemoveSeats: p.RemoveSeats, RemoveAddrs: p.RemoveAddrs})
			s.Ledger.Apply(dec, now, "at once: "+note+lastNote)
			return dec
		}
		dec := record(now+decisions.Delay, rest)
		dec.Note = note + ", " + itoa(int64(queued)) + " queued 7 days" + lastNote
		return dec
	case restoreParams:
		// a withheld claim at once; a forged claim, a voided sweep entry and a written-off send (R38), after 7 days;
		// an id no longer voided (restored by another decision since the proposal was made) or gone is skipped and
		// counted (R22)
		var later []string
		n, skipped := 0, 0
		for _, id := range p.ids {
			if e := s.SweepOf(id); e != nil {
				if !e.Voided {
					skipped++
					continue
				}
				later = append(later, id)
				continue
			}
			if sd := s.SendOf(id); sd != nil {
				if sd.WrittenOff == 0 {
					skipped++
					continue
				}
				later = append(later, id)
				continue
			}
			c := s.ClaimOf(id)
			switch {
			case c == nil:
				skipped++
			case c.State == Withheld:
				s.restore(c, now, env.Epoch())
				n++
			case c.State == Forged:
				later = append(later, id)
			default:
				skipped++
			}
		}
		note := itoa(int64(n)) + " withheld restored at once"
		if skipped > 0 {
			note += ", " + itoa(int64(skipped)) + " skipped (not voided as it stands)"
		}
		if len(later) == 0 {
			dec := record(now, restoreParams{})
			s.Ledger.Apply(dec, now, "at once: "+note)
			return dec
		}
		dec := record(now+decisions.Delay, restoreParams{later})
		dec.Note = note + ", " + itoa(int64(len(later))) + " forged, or written off, queued 7 days"
		return dec
	case cancelParams:
		if _, err := s.Ledger.Cancel(p.id, now); err != nil {
			panic("hlroute: " + err.Error())
		}
		dec := record(now, p)
		s.Ledger.Apply(dec, now, "at once: cancelled")
		return dec
	case migrateParams:
		s.mustAllowMigrate(p.to)
		s.mustMigrate(p.to, env)
		return s.queued(record(now+decisions.Delay, p))
	case refundParams:
		// queued 7 days like a sweep payment, but applied by GovDAO's own at-once decision after (AT2:
		// DraftApplyRefund), never by anyone's Execute — the note says so
		dec := s.queued(record(now+decisions.Delay, p))
		dec.Note += ": applied by GovDAO's own apply refund decision after, never by Execute"
		return dec
	case applyRefundParams:
		// GovDAO's own at-once apply of a queued refund (AT2): the refund decision is asked again as it stands — a
		// refund, pending, its delay passed, the note 14 days old — and applied as the delay would have applied it,
		// before anything is recorded (a refusal is a panic that leaves no record, so the proposal survives a retry
		// until its deadline); then both decisions are noted, each naming the other
		rd := s.refundToApply(p.id, now, env)
		note := s.apply(rd, now, env)
		dec := record(now, p)
		s.Ledger.Apply(rd, now, "applied by GovDAO's apply refund decision "+itoa(dec.ID)+note)
		s.Ledger.Apply(dec, now, "at once: refund decision "+itoa(p.id)+" applied"+note)
		return dec
	case routerParams, creditParams, sweepParams, writeOffParams:
		return s.queued(record(now+decisions.Delay, d.Params))
	}
	panic("hlroute: unknown draft " + d.Kind)
}

func (s *State) queued(dec *decisions.Decision) *decisions.Decision {
	dec.Note = "queued 7 days"
	return dec
}

// Execute applies a queued decision whose delay has passed; on a migrated route only a migrate that re-points a
// migration nothing was pulled from (AR2: apply asks). Never a refund (AT2): its apply is GovDAO's own at-once
// decision (DraftApplyRefund), made after hlwatch's check that the token's router on Solana is this realm — a check
// the realm cannot make and anyone's Execute would skip.
func (s *State) Execute(now, id int64, env Env) *decisions.Decision {
	if d := s.Ledger.Get(id); d != nil && d.Kind == KindRefund {
		panic("hlroute: decision " + itoa(id) + " is a refund: a refund is applied by GovDAO's own at-once decision (apply refund) after hlwatch's Solana check, never by Execute")
	}
	dec, err := s.Ledger.Due(id, now)
	if err != nil {
		panic("hlroute: " + err.Error())
	}
	if dec.Kind != KindMigrate {
		s.mustNotBeMigrated()
	}
	note := s.apply(dec, now, env)
	s.Ledger.Apply(dec, now, "applied after the delay"+note)
	return dec
}

// apply is a decision's effect, the same at once and after the delay; the checks a builder made are made again
// against the live state. It returns what the note should add ("" for nothing): what a list or a range skipped,
// what a sweep payment paid.
func (s *State) apply(dec *decisions.Decision, now int64, env Env) (note string) {
	switch p := dec.Params.(type) {
	case capFloorParams:
		if p.n < s.LaunchCapFloor || p.n/4 < s.Fee {
			panic("hlroute: below the launch floor, or a quarter below the fee, now")
		}
		s.CapFloor = p.n
	case maximumParams:
		if p.n < s.Minimum {
			panic("hlroute: the maximum never goes below the minimum")
		}
		s.Maximum = p.n
	case feeParams:
		if p.fee < s.FeeFloor || p.fee > s.CapFloor/4 || p.minimum <= 0 || p.minimum > s.Maximum {
			panic("hlroute: the fee is under the fee floor or above a quarter of the cap floor, or the minimum is out of range, now")
		}
		s.Fee, s.Minimum = p.fee, p.minimum
	case feeFloorParams:
		if p.n > s.Fee {
			panic("hlroute: the fee floor is above the fee now")
		}
		s.FeeFloor = p.n
	case routerParams:
		s.OldRouter, s.OldUntil = s.Router, now+decisions.Delay
		s.Router = p.router
	case VoidParams:
		// every credit the void can still take as it stands is voided; one it cannot — voided at once when the
		// proposal executed, or by another decision since, paid in full under a void as withheld, or gone — is
		// skipped and counted, the list form like the range form (R22)
		n, skipped := 0, 0
		last := int64(0)
		if p.Ranged {
			// the range as closed when the proposal was made, counted again against the cap (R28); the last height
			// voided goes into the note (R23)
			s.mustFitRange(p.Range)
			s.eachInRange(p.Range, func(c *Claim) bool {
				if voidable(c, p.Forged) {
					s.void(c, p.Forged)
					n++
					last = c.Height
				} else {
					skipped++
				}
				return false
			}, func(e *SweepEntry) bool {
				if sweepVoidable(e, p.Forged) {
					s.voidSweep(e)
					n++
					last = e.Height
				} else {
					skipped++
				}
				return false
			})
		} else {
			for _, id := range p.IDs {
				if e := s.SweepOf(id); e != nil {
					if sweepVoidable(e, p.Forged) {
						s.voidSweep(e)
						n++
					} else {
						skipped++
					}
					continue
				}
				if c := s.ClaimOf(id); c != nil && voidable(c, p.Forged) {
					s.void(c, p.Forged)
					n++
				} else {
					skipped++
				}
			}
		}
		note = "; " + strconv.Itoa(n) + " voided"
		if skipped > 0 {
			note += ", " + strconv.Itoa(skipped) + " skipped (not voidable as it stands)"
		}
		if p.Ranged && n > 0 {
			note += ", last voided at height " + itoa(last)
		}
	case restoreParams:
		// an id no longer voided (restored by another decision since) or gone is skipped and counted (R22); a
		// written-off send is lost no more (R38)
		n, skipped, undone := 0, 0, 0
		for _, id := range p.ids {
			if e := s.SweepOf(id); e != nil {
				if e.Voided {
					s.restoreSweep(e)
					n++
				} else {
					skipped++
				}
				continue
			}
			if sd := s.SendOf(id); sd != nil {
				if sd.WrittenOff != 0 {
					s.restoreWriteOff(sd)
					n++
					undone++
				} else {
					skipped++
				}
				continue
			}
			if c := s.ClaimOf(id); c != nil && (c.State == Withheld || c.State == Forged) {
				s.restore(c, now, env.Epoch())
				n++
			} else {
				skipped++
			}
		}
		note = "; " + strconv.Itoa(n) + " restored"
		switch undone {
		case 0:
		case 1:
			note += " (1 write-off undone: the send is lost no more)"
		default:
			note += " (" + strconv.Itoa(undone) + " write-offs undone: the sends are lost no more)"
		}
		if skipped > 0 {
			note += ", " + strconv.Itoa(skipped) + " skipped (not voided as it stands)"
		}
	case creditParams:
		s.creditByVote(now, p, env)
	case sweepParams:
		// the entries still live are paid as one sum and dropped (R19); one voided or gone since the proposal was
		// made is skipped; a sum the lock no longer covers waits
		sum, paid, skipped := int64(0), 0, 0
		for _, id := range p.ids {
			if e := s.SweepOf(id); e != nil && !e.Voided {
				sum += e.Amount
				paid++
			} else {
				skipped++
			}
		}
		if sum > s.Sweep {
			panic("hlroute: the entries sum to " + s.Amount(sum) + ", more than the sweep queue's balance of " + s.Amount(s.Sweep))
		}
		if sum > s.Lock {
			panic("hlroute: the lock (" + s.Amount(s.Lock) + ") holds less than the entries' " + s.Amount(sum) + " now")
		}
		for _, id := range p.ids {
			if e := s.SweepOf(id); e != nil && !e.Voided {
				s.sweeps.Remove(id)
				s.credits.Remove(heightKey(e.Height, e.ID))
			}
		}
		s.Sweep -= sum
		s.Owed -= sum
		s.PaidTotal += sum
		s.Lock -= sum
		if sum > 0 {
			env.Pay(p.to, sum)
		}
		note = "; " + strconv.Itoa(paid) + " entries paid (" + s.Amount(sum) + ")"
		if skipped > 0 {
			note += ", " + strconv.Itoa(skipped) + " skipped (voided or gone since the proposal was made)"
		}
	case refundParams:
		// kind 6's enrolment of this route is asked again (AR1: a later kind 6 restarts the wait); then the sends a
		// predecessor's page brought (AQ2) and still unrefunded are summed first: a sum the lock no longer covers
		// waits (R30), as a sweep payment's does; one refunded by another decision since the proposal was made, or
		// gone, is skipped and counted (R22)
		s.mustBeEnrolled(now, env)
		sum, n, skipped := int64(0), 0, 0
		for _, id := range p.ids {
			if sd := s.SendOf(id); sd != nil && sd.Imported && sd.Refunded == 0 {
				sum += sd.Amount
				n++
			} else {
				skipped++
			}
		}
		if sum > s.Lock {
			panic("hlroute: the lock (" + s.Amount(s.Lock) + ") holds less than the sends' " + s.Amount(sum) + " now")
		}
		for _, id := range p.ids {
			sd := s.SendOf(id)
			if sd == nil || !sd.Imported || sd.Refunded != 0 {
				continue
			}
			s.refund(id, sd, now)
			env.Pay(sd.From, sd.Amount)
		}
		note = "; " + strconv.Itoa(n) + " refunded"
		if skipped > 0 {
			note += ", " + strconv.Itoa(skipped) + " skipped (refunded already, or gone)"
		}
	case writeOffParams:
		// a refunded send still unmarked is written off, its amount lost and the identity closed by that much (AR1);
		// one written off by another decision since the proposal was made, never refunded, or gone is skipped (R22)
		sum, n, skipped := int64(0), 0, 0
		for _, id := range p.ids {
			if sd := s.SendOf(id); sd != nil && sd.Refunded != 0 && sd.WrittenOff == 0 {
				s.writeOff(sd, now)
				sum += sd.Amount
				n++
			} else {
				skipped++
			}
		}
		note = "; " + strconv.Itoa(n) + " written off (" + s.Amount(sum) + ")"
		if skipped > 0 {
			note += ", " + strconv.Itoa(skipped) + " skipped (written off already, never refunded, or gone)"
		}
	case migrateParams:
		// a re-point (AR2) passes the same checks as a first migrate; the mailbox replaces the registration
		s.mustAllowMigrate(p.to)
		s.mustMigrate(p.to, env)
		s.MigratedTo, s.MigratedAt = p.to, now
		env.AddRoute(p.to)
	default:
		panic("hlroute: decision " + itoa(dec.ID) + " has nothing to apply")
	}
	return note
}

// refund marks a send refunded now and takes its amount out of sentTotal and the lock (the realm pays it back): the
// mark is what send/<id>, refunds/<from> and the json's refunded count show, so the monitors drop the send from what
// is in flight (AQ2).
func (s *State) refund(id string, sd *Send, now int64) {
	sd.Refunded = now
	s.SentTotal -= sd.Amount
	s.Lock -= sd.Amount
	s.refunds.Set(id, true)
	s.nRefunded++
	s.refundedTotal += sd.Amount
}

// writeOff marks a refunded send delivered on Solana after its refund and books its amount as lost (AR1): the
// mark is what send/<id> and the json's writtenOff count show.
func (s *State) writeOff(sd *Send, now int64) {
	sd.WrittenOff = now
	s.Lost += sd.Amount
	s.nWrittenOff++
	s.writtenOffTotal += sd.Amount
}

// restoreWriteOff is writeOff's inverse (R38): the mark cleared, the amount back out of lost and the counters down,
// so the identity closes on the supply as it was before the mistaken write-off; the refund mark stays, and the
// send may be written off again.
func (s *State) restoreWriteOff(sd *Send) {
	sd.WrittenOff = 0
	s.Lost -= sd.Amount
	s.nWrittenOff--
	s.writtenOffTotal -= sd.Amount
}

// creditByVote credits an id by hand: a new claim for an id never done (marked done now); for an id whose claim
// stands voided, the voided record replaced by the recipient and amount GovDAO names at the back of that
// recipient's queue (what stood voided or lost for it is undone; what is owed moves by the new amount); for a
// sweep entry's id (R11), the entry dropped — its amount out of the sweep queue and of what is owed, unless a
// void took it already — and the claim queued in its place. The amount is at most the lock as it stands (R26).
func (s *State) creditByVote(now int64, p creditParams, env Env) {
	if p.amount > s.Lock {
		panic("hlroute: the amount " + s.Amount(p.amount) + " is above the lock of " + s.Amount(s.Lock) + " now")
	}
	if c := s.ClaimOf(p.id); c != nil {
		switch c.State {
		case Withheld:
			s.Voided -= c.Remaining()
		case Forged:
			s.Lost -= c.Paid
		default:
			panic("hlroute: " + p.id + " is credited already and not voided")
		}
		s.claims.Remove(p.id)
		s.credits.Remove(heightKey(c.Height, c.ID))
		s.nClaims--
		s.enqueue(now, env.Height(), env.Epoch(), p.id, p.to, p.amount, ByVote)
		return
	}
	if e := s.SweepOf(p.id); e != nil {
		if !e.Voided {
			if e.Amount > s.Sweep {
				panic("hlroute: " + e.ID + "'s " + s.Amount(e.Amount) + " exceeds the sweep queue's balance of " + s.Amount(s.Sweep))
			}
			s.Sweep -= e.Amount
			s.Owed -= e.Amount
		}
		s.sweeps.Remove(p.id)
		s.credits.Remove(heightKey(e.Height, e.ID))
		s.enqueue(now, env.Height(), env.Epoch(), p.id, p.to, p.amount, ByVote)
		return
	}
	if env.Delivered(p.id) {
		panic("hlroute: " + p.id + " is done already")
	}
	env.MarkDone(p.id)
	s.enqueue(now, env.Height(), env.Epoch(), p.id, p.to, p.amount, ByVote)
}

// -------------------------------------------------------------- migrate --

// Snapshot is one page of what a successor takes over: plain values it copies into its own state. Page 0 carries
// the counters; every page up to the page size of records.
type Snapshot struct {
	Page                                                int
	More                                                bool // records remain for the next page
	Lock, SentTotal, PaidTotal, Owed, Voided, Lost, Sweep int64
	Claims                                              []Claim
	Sweeps                                              []SweepItem
	Sends                                               []SendItem
}

type SweepItem struct {
	ID     string
	Amount int64
	Height int64
	By     string
	Voided bool
}

type SendItem struct {
	ID       string
	From     address
	Amount   int64
	At       int64
	Refunded   int64 // when it was refunded, 0 if not (R33): the mark goes with the record, so some realm always answers it
	WrittenOff int64 // when it was written off (AR1), 0 if not: the same
}

// Exported is how many pages went to the successor so far: the next Pull takes that page number.
func (s *State) Exported() int { return s.exported }

// Imported is how many of a predecessor's pages this route took in: 0 for a route that succeeded none.
func (s *State) Imported() int { return s.imported }

// MustHaveImported is the gate on a message the router addressed to this route's predecessor (AQ1): hlmailbox lets
// a successor take such a message — the burns name the predecessor until kind 6 enrolls the successor — and this
// route credits it only once the predecessor's last page is in: before page 0 the lock is not here (the credit
// would be swept as one above the lock), and between pages Credit refuses anyway. The message waits undelivered
// meanwhile and the relayer brings it again; after the last page it is an ordinary credit, done once in the shared
// mailbox. A route that succeeded none refuses such a message for good.
func (s *State) MustHaveImported() {
	if s.imported == 0 || s.importing {
		panic("hlroute: addressed to another realm: a successor takes its predecessor's messages once the last page of the migration is in (" + strconv.Itoa(s.imported) + " pages so far)")
	}
}

// MustTake is the gate on every incoming message, asked by the realm's Process before the mailbox is: toSelf is
// whether the message names this realm as its recipient, predecessor the route whose migrate registered this one
// (hlmailbox.Predecessor of the realm's own path, "" for a launch route). A route that succeeds another credits
// nothing before its predecessor's last page is in — a message addressed to itself included (R32, AR3): before
// page 0 the lock is not here, so an honest burn to the successor, which kind 6 may enroll the day the migrate
// applies, would be swept as one above the lock, owed and paying nobody until a sweep payment by vote — so every
// message waits undelivered meanwhile and the relayer brings it again. A message addressed to another realm is a
// predecessor's (MustHaveImported): taken once the last page is in, refused for good by a route that succeeded
// none. A launch route takes its own as it always did.
func (s *State) MustTake(toSelf bool, predecessor string) {
	if !toSelf {
		s.MustHaveImported()
		return
	}
	if predecessor != "" && (s.imported == 0 || s.importing) {
		panic("hlroute: this route succeeds " + predecessor + ": nothing is credited before the last page of the migration is in (" + strconv.Itoa(s.imported) + " pages so far)")
	}
}

// MustSend is the gate on a send, asked by the realm's TransferRemote before anything moves (R35, F28; AT7): a route
// that succeeds another takes no send before its predecessor's last page is in — the mirror of MustTake — nor
// before r/hlgov has dispatched the kind 6 enrolling it as the token's router on Solana (Env.Enrolled: the note
// the kind-6 closure leaves with the mailbox, cleared by a cancel). Before page 0 nothing has moved, so the
// migration may still be re-pointed (AR2) and this realm dropped: a send through it would lock the sender's coins
// in a realm Solana never enrols (kind 6 waits for page 0), which cannot refund them (its own send, never a
// refund's) and cannot migrate (a route no more) — stranded for good. Between pages the lock is only partly here
// and Credit refuses anyway; a send waits for the last page as a credit does. After the last page and before the
// kind 6, the token program refuses a sender that is not its enrolled router, so every send would park on Solana
// until a kind 6 lands — weeks under a hold, never if GovDAO cancels it — unrefundable as the route's own (§5.3:
// a live route's stranded send waits for a kind 12, since a refund voids nothing on Solana); with the note in, a
// send parks a week at most (the kind 6's own clock there; a hold defers it, the guardians' sends flag the brake).
// A launch route sends as it always did: the setup step enrolled it, and no kind 6 ever notes it.
func (s *State) MustSend(predecessor string, env Env) {
	if predecessor == "" {
		return
	}
	if s.imported == 0 || s.importing {
		panic("hlroute: this route succeeds " + predecessor + ": nothing is sent before the last page of the migration is in (" + strconv.Itoa(s.imported) + " pages so far)")
	}
	if h, _ := env.Enrolled(); h == 0 {
		panic("hlroute: this route succeeds " + predecessor + ": nothing is sent before r/hlgov has dispatched the kind 6 enrolling this realm as the token's router on Solana (no enrolment note yet): a send before it would park there until a kind 6 lands, unrefundable as the route's own")
	}
}

// Importing is whether a predecessor's pages are still arriving: from page 0's import until the page that says no
// more follows (AP4). A successor's adopt loop reads it to know when it is done.
func (s *State) Importing() bool { return s.importing }

// Export hands the state to the successor a page at a time (R13): page 0 carries the counters (the realm pays the
// lock with it) and every page up to size records — the claims first, every claim ever credited (open, voided and
// paid, so a void or a restore reaches them on the successor, R12), then the sweep entries, then the sends, a
// refunded one with its mark (R33: the monitors drop a refunded send from what is in flight by the realm that
// answers send/<id> for it, so the record is never dropped; the refund counters follow it) — each leaving this
// state as it goes, so a page outgrows no block however long the route ran. The pages go in order; a page handed
// over already exports nothing (and the realm pays nothing). Only after a migrate decision applied.
func (s *State) Export(page, size int) *Snapshot {
	if !s.Migrated() {
		panic("hlroute: no migrate decision applied")
	}
	if page < 0 || page > s.exported {
		panic("hlroute: page " + strconv.Itoa(s.exported) + " is the next to pull, not " + strconv.Itoa(page))
	}
	snap := &Snapshot{Page: page}
	if page < s.exported {
		return snap
	}
	if size < 1 {
		panic("hlroute: a page holds at least one record")
	}
	if page == 0 {
		snap.Lock, snap.SentTotal, snap.PaidTotal, snap.Owed, snap.Voided, snap.Lost, snap.Sweep = s.Lock, s.SentTotal, s.PaidTotal, s.Owed, s.Voided, s.Lost, s.Sweep
		s.Lock, s.SentTotal, s.PaidTotal, s.Owed, s.Voided, s.Lost, s.Sweep = 0, 0, 0, 0, 0, 0, 0
	}
	n := 0
	var keys []string
	s.claims.Iterate("", "", func(k string, v any) bool {
		c := *v.(*Claim)
		// the recipient's counter is final (nothing credits here after the migrate decision): the successor raises
		// its own to it on first seeing the recipient (R20)
		c.QueueNext = s.queues.Get(string(c.To)).(*Queue).next
		snap.Claims = append(snap.Claims, c)
		keys = append(keys, k)
		n++
		return n >= size
	})
	for _, k := range keys {
		c := s.claims.Get(k).(*Claim)
		if c.State == Open {
			s.dequeue(c, s.queues.Get(string(c.To)).(*Queue))
			s.nOpen--
		}
		s.claims.Remove(k)
		s.credits.Remove(heightKey(c.Height, c.ID))
		s.nClaims--
	}
	keys = nil
	if n < size {
		s.sweeps.Iterate("", "", func(k string, v any) bool {
			e := v.(*SweepEntry)
			snap.Sweeps = append(snap.Sweeps, SweepItem{e.ID, e.Amount, e.Height, e.By, e.Voided})
			keys = append(keys, k)
			n++
			return n >= size
		})
		for _, k := range keys {
			e := s.sweeps.Get(k).(*SweepEntry)
			s.sweeps.Remove(k)
			s.credits.Remove(heightKey(e.Height, e.ID))
		}
		keys = nil
	}
	if n < size {
		s.sends.Iterate("", "", func(k string, v any) bool {
			sd := v.(*Send)
			snap.Sends = append(snap.Sends, SendItem{ID: k, From: sd.From, Amount: sd.Amount, At: sd.At, Refunded: sd.Refunded, WrittenOff: sd.WrittenOff})
			keys = append(keys, k)
			n++
			return n >= size
		})
		for _, k := range keys {
			sd := s.sends.Get(k).(*Send)
			if sd.Refunded != 0 {
				s.nRefunded--
				s.refundedTotal -= sd.Amount
			}
			if sd.WrittenOff != 0 {
				s.nWrittenOff--
				s.writtenOffTotal -= sd.Amount
			}
			s.sends.Remove(k)
			s.refunds.Remove(k)
		}
	}
	snap.More = s.claims.Size() > 0 || s.sweeps.Size() > 0 || s.sends.Size() > 0
	if n > 0 || page == 0 {
		s.exported++
	}
	return snap
}

// Import takes a page of a predecessor's snapshot into this state: the counters add (page 0 carries them), the
// claims keep their ids, states and order — a recipient's queue places every imported claim at a base plus its
// old seq, and its counter is raised to the predecessor's final one on first seeing the recipient (R20), so this
// route's own credits land above every place a later page can claim — the open ones queued, the voided and paid
// ones kept as records, the sweep entries and the sends as they were, a refunded send with its mark, in the
// refunds index and counted (R33). The pages go in order, each once; from the first to the one that says no
// more follows, Credit refuses (AP4). epoch is this route's payouts epoch now: the queues it makes start there.
// Page 0 empties the bridge meter and every quarter as of now and takes launchedAt — hlmailbox's launch time —
// as the launch the meters were last emptied for (R34): a successor starts with empty meters, as a launch route
// does at Launch and every route after an unpause, and its first Claim applies no launch reset, which rewound
// every meter to the launch, months back, and filled them all at once — a third cap in the 24 hours the
// predecessor closed. The queues a later page makes start empty at their first claim, as every queue does.
func (s *State) Import(now, epoch, launchedAt int64, snap *Snapshot) {
	s.mustNotBeMigrated()
	if snap.Page != s.imported {
		panic("hlroute: page " + strconv.Itoa(s.imported) + " is the next to import, not " + strconv.Itoa(snap.Page))
	}
	if snap.Page == 0 {
		s.ResetMeters(now)
		s.LaunchSeen = launchedAt
	}
	s.imported++
	s.importing = snap.More
	s.Lock += snap.Lock
	s.SentTotal += snap.SentTotal
	s.PaidTotal += snap.PaidTotal
	s.Owed += snap.Owed
	s.Voided += snap.Voided
	s.Lost += snap.Lost
	s.Sweep += snap.Sweep
	for _, c := range snap.Claims {
		if s.claims.Has(c.ID) {
			panic("hlroute: a claim with id " + c.ID + " exists")
		}
		q := s.queue(c.To, now, epoch)
		if !q.imported {
			q.imported, q.base = true, q.next
			if top := q.base + c.QueueNext; top > q.next {
				q.next = top
			}
		}
		nc := &Claim{ID: c.ID, To: c.To, Amount: c.Amount, Paid: c.Paid, At: c.At, Height: c.Height, By: c.By, State: c.State, Seq: q.base + c.Seq}
		if nc.Seq > q.next {
			q.next = nc.Seq
		}
		s.claims.Set(c.ID, nc)
		s.credits.Set(heightKey(c.Height, c.ID), c.ID)
		s.nClaims++
		if c.State == Open {
			if q.items.Has(seqKey(nc.Seq)) {
				panic("hlroute: a claim at place " + itoa(nc.Seq) + " of " + string(c.To) + "'s queue exists")
			}
			q.items.Set(seqKey(nc.Seq), c.ID)
			s.nOpen++
			s.waiting.Set(string(c.To), true)
		}
	}
	for _, it := range snap.Sweeps {
		if s.sweeps.Has(it.ID) {
			panic("hlroute: a sweep entry with id " + it.ID + " exists")
		}
		s.sweeps.Set(it.ID, &SweepEntry{ID: it.ID, Amount: it.Amount, Height: it.Height, By: it.By, Voided: it.Voided})
		s.credits.Set(heightKey(it.Height, it.ID), it.ID)
	}
	for _, it := range snap.Sends {
		if s.sends.Has(it.ID) {
			panic("hlroute: a send with id " + it.ID + " exists")
		}
		s.sends.Set(it.ID, &Send{From: it.From, Amount: it.Amount, At: it.At, Refunded: it.Refunded, WrittenOff: it.WrittenOff, Imported: true})
		if it.Refunded != 0 {
			s.refunds.Set(it.ID, true)
			s.nRefunded++
			s.refundedTotal += it.Amount
		}
		if it.WrittenOff != 0 {
			s.nWrittenOff++
			s.writtenOffTotal += it.Amount
		}
	}
}

// ---------------------------------------------------------------- pages --

// meterView is the bridge meter as a reader sees it now: a copy, refilled, with the launch reset the next Claim
// will apply (§5.4: the meters start empty at Launch; launchedAt is hlmailbox's, 0 before the launch) applied
// first, so the page and hlwatch never show a full meter that Claim would then empty (K22).
func (s *State) meterView(now, epoch, epochAt, launchedAt int64) Meter {
	m := s.meter
	if launchedAt != 0 && launchedAt != s.LaunchSeen {
		m.Level, m.At, m.Frac = 0, launchedAt, 0
	}
	dayCap := s.Cap()
	m.refill(now, dayCap, dayCap, epoch, epochAt)
	return m
}

// Figures is the realm's page body: the settings, the identity and the queues. launchedAt is hlmailbox's launch
// time (the meter is shown as the launch reset leaves it until the first Claim applies the reset).
func (s *State) Figures(now int64, epoch, epochAt, launchedAt int64, paused string) string {
	var b strings.Builder
	dayCap := s.Cap()
	m := s.meterView(now, epoch, epochAt, launchedAt)
	b.WriteString("- lock: " + s.Amount(s.Lock) + " (sent " + s.Amount(s.SentTotal) + ", paid " + s.Amount(s.PaidTotal) + ")\n")
	b.WriteString("- owed: " + s.Amount(s.Owed) + " in " + itoa(s.nOpen) + " open claims (the sweep queue " + s.Amount(s.Sweep) + " included); voided " + s.Amount(s.Voided) + "; lost " + s.Amount(s.Lost) + "\n")
	b.WriteString("- identity: lock = sentTotal − paidTotal = supply + owed + voided − lost, so the supply on Solana should be " + s.Amount(s.Lock-s.Owed-s.Voided+s.Lost) + " up to messages in flight\n")
	b.WriteString("- day cap: " + s.Amount(dayCap) + " (floor " + s.Amount(s.CapFloor) + ", a tenth of the lock otherwise); the bridge meter holds " + s.Amount(m.Level) + " now; a recipient's meter holds a quarter at most\n")
	b.WriteString("- fee " + s.Amount(s.Fee) + " (floor " + s.Amount(s.FeeFloor) + "); minimum " + s.Amount(s.Minimum) + "; per-message maximum " + s.Amount(s.Maximum) + "\n")
	b.WriteString("- " + decisions.Clocks() + "; the old router's window after a swap is the 7-day delay\n")
	b.WriteString("- router on domain " + strconv.FormatUint(uint64(s.Domain), 10) + ": `" + hex.EncodeToString(s.Router[:]) + "`")
	if s.OldUntil > now {
		b.WriteString(" (the old router `" + hex.EncodeToString(s.OldRouter[:]) + "` accepted until " + itoa(s.OldUntil) + ")")
	}
	b.WriteString("\n")
	if paused != "" {
		b.WriteString("- **paused**: " + paused + "\n")
	}
	if s.Migrated() {
		b.WriteString("- **migrated** to `" + s.MigratedTo + "` at " + itoa(s.MigratedAt) + ": every function refuses\n")
	}
	if s.importing {
		b.WriteString("- **importing**: a predecessor's pages are arriving (" + strconv.Itoa(s.imported) + " so far); credits are refused until the last page is in\n")
	}
	writtenOff := ""
	if s.nWrittenOff > 0 {
		writtenOff = ", written off " + itoa(s.nWrittenOff) + " (" + s.Amount(s.writtenOffTotal) + ")"
	}
	b.WriteString("- claims ever: " + itoa(s.nClaims) + "; sends recorded: " + itoa(int64(s.sends.Size())) + ", refunded " + itoa(s.nRefunded) + " (" + s.Amount(s.refundedTotal) + ")" + writtenOff + "; decisions: " + itoa(s.Ledger.Last()) + "\n")
	// the count is the counter, never a walk of every waiting recipient (R24): the page stays within a query's gas
	// under a flood of claims to fresh addresses; nOpen and the walk agree (R12)
	if total := int(s.nOpen); total > 0 {
		b.WriteString("\n## Waiting claims\n\n")
		listed := 0
		s.eachWaiting(func(to string, pos int, c *Claim) bool {
			b.WriteString("- " + to + " #" + strconv.Itoa(pos) + ": " + s.Amount(c.Remaining()) + " of " + s.Amount(c.Amount) + " " + c.State + " (" + c.By + ") at height " + itoa(c.Height) + " `" + c.ID + "`\n")
			listed++
			return listed >= PageLines
		})
		if rest := total - listed; rest > 0 {
			b.WriteString("- … and " + strconv.Itoa(rest) + " more (" + strconv.Itoa(total) + " waiting): the whole list, by hundreds, at claims/0, claims/" + strconv.Itoa(PageLines) + ", …\n")
		}
	}
	if total := s.sweeps.Size(); total > 0 {
		b.WriteString("\n## Sweep queue\n\n")
		s.sweeps.IterateByOffset(0, PageLines, func(_ string, v any) bool {
			b.WriteString("- " + s.sweepLine(v.(*SweepEntry)) + "\n")
			return false
		})
		if rest := total - PageLines; rest > 0 {
			b.WriteString("- … and " + strconv.Itoa(rest) + " more (" + strconv.Itoa(total) + " entries): the whole queue, by hundreds, at sweeps/0, sweeps/" + strconv.Itoa(PageLines) + ", …\n")
		}
	}
	return b.String()
}

// sweepLine is one sweep entry on the page.
func (s *State) sweepLine(e *SweepEntry) string {
	line := s.Amount(e.Amount) + " `" + e.ID + "` (" + e.By + ") at height " + itoa(e.Height)
	if e.Voided {
		line += ", voided as forged"
	}
	return line
}

// eachWaiting walks every open claim in the queues in the page's order (recipients by address, each queue oldest
// first) until fn returns true; pos is the claim's place in its recipient's queue, from 1. It walks the ring of
// recipients with an open claim, never a queue emptied by payouts or voids (R13).
func (s *State) eachWaiting(fn func(to string, pos int, c *Claim) bool) {
	s.waiting.Iterate("", "", func(k string, _ any) bool {
		q := s.queues.Get(k).(*Queue)
		pos, stop := 0, false
		q.items.Iterate("", "", func(_ string, idv any) bool {
			c := s.claims.Get(idv.(string)).(*Claim)
			pos++
			stop = fn(k, pos, c)
			return stop
		})
		return stop
	})
}

// waitingCount is how many open claims sit in the queues, by a walk of every waiting recipient: the tests' check
// of nOpen (R12's invariant); no page uses it (R24).
func (s *State) waitingCount() int {
	n := 0
	s.waiting.Iterate("", "", func(k string, _ any) bool {
		n += s.queues.Get(k).(*Queue).items.Size()
		return false
	})
	return n
}

// ClaimsPage is up to PageLines waiting claims from the from-th on (from 0), in the page's order, as a JSON array
// of ClaimJSON's objects; "[]" past the end.
func (s *State) ClaimsPage(from int) string {
	var b strings.Builder
	b.WriteString("[")
	i, n := 0, 0
	if from >= 0 {
		s.eachWaiting(func(_ string, _ int, c *Claim) bool {
			if i >= from {
				if n > 0 {
					b.WriteString(",")
				}
				b.WriteString(claimJSON(c))
				n++
			}
			i++
			return n >= PageLines
		})
	}
	b.WriteString("]")
	return b.String()
}

// SweepsPage is up to PageLines sweep entries from the from-th on (from 0), by id, as a JSON array of
// {"id","swept"}; "[]" past the end.
func (s *State) SweepsPage(from int) string {
	var b strings.Builder
	b.WriteString("[")
	n := 0
	if from >= 0 {
		s.sweeps.IterateByOffset(from, PageLines, func(_ string, v any) bool {
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(sweptJSON(v.(*SweepEntry)))
			n++
			return false
		})
	}
	b.WriteString("]")
	return b.String()
}

// JSON is the figures for the agents; launchedAt as Figures takes it.
func (s *State) JSON(now int64, epoch, epochAt, launchedAt int64) string {
	dayCap := s.Cap()
	m := s.meterView(now, epoch, epochAt, launchedAt)
	return "\"symbol\":" + strconv.Quote(s.Symbol) + ",\"domain\":" + strconv.FormatUint(uint64(s.Domain), 10) +
		",\"router\":" + strconv.Quote(hex.EncodeToString(s.Router[:])) + ",\"oldRouter\":" + strconv.Quote(hex.EncodeToString(s.OldRouter[:])) + ",\"oldUntil\":" + itoa(s.OldUntil) +
		",\"lock\":" + itoa(s.Lock) + ",\"sentTotal\":" + itoa(s.SentTotal) + ",\"paidTotal\":" + itoa(s.PaidTotal) +
		",\"owed\":" + itoa(s.Owed) + ",\"voided\":" + itoa(s.Voided) + ",\"lost\":" + itoa(s.Lost) + ",\"sweep\":" + itoa(s.Sweep) +
		",\"cap\":" + itoa(dayCap) + ",\"meter\":" + itoa(m.Level) + ",\"capFloor\":" + itoa(s.CapFloor) +
		",\"fee\":" + itoa(s.Fee) + ",\"feeFloor\":" + itoa(s.FeeFloor) + ",\"minimum\":" + itoa(s.Minimum) + ",\"maximum\":" + itoa(s.Maximum) +
		",\"openClaims\":" + itoa(s.nOpen) + ",\"claims\":" + itoa(s.nClaims) + ",\"sends\":" + itoa(int64(s.sends.Size())) +
		",\"refunded\":" + itoa(s.nRefunded) + ",\"refundedTotal\":" + itoa(s.refundedTotal) +
		",\"writtenOff\":" + itoa(s.nWrittenOff) + ",\"writtenOffTotal\":" + itoa(s.writtenOffTotal) +
		",\"migratedTo\":" + strconv.Quote(s.MigratedTo) + ",\"importing\":" + strconv.FormatBool(s.importing) + ",\"imported\":" + strconv.Itoa(s.imported) +
		",\"clocks\":" + decisions.ClocksJSON() + ",\"decisions\":" + itoa(s.Ledger.Last())
}

// SendJSON is one send by id — {"id","from","amount","at","imported","refunded","writtenOff"}: "refunded" the unix
// time it was, 0 if not, "writtenOff" the unix time it was written off as delivered on Solana after its refund
// (AR1), 0 if not, and "imported" whether a predecessor's page brought it (the only sends a refund may name, AQ2)
// — or "null".
func (s *State) SendJSON(id string) string {
	cid, err := CleanID(id)
	if err != nil {
		return "null"
	}
	sd := s.SendOf(cid)
	if sd == nil {
		return "null"
	}
	return sendJSON(cid, sd)
}

func sendJSON(id string, sd *Send) string {
	return "{\"id\":" + strconv.Quote(id) + ",\"from\":" + strconv.Quote(string(sd.From)) + ",\"amount\":" + itoa(sd.Amount) + ",\"at\":" + itoa(sd.At) +
		",\"imported\":" + strconv.FormatBool(sd.Imported) + ",\"refunded\":" + itoa(sd.Refunded) + ",\"writtenOff\":" + itoa(sd.WrittenOff) + "}"
}

// RefundsPage is up to PageLines sends refunded here from the from-th on (from 0), by id, as a JSON array of
// SendJSON's objects: what the monitors read to drop a refunded send from what is in flight (AQ2); "[]" past the
// end.
func (s *State) RefundsPage(from int) string {
	var b strings.Builder
	b.WriteString("[")
	n := 0
	if from >= 0 {
		s.refunds.IterateByOffset(from, PageLines, func(k string, _ any) bool {
			if n > 0 {
				b.WriteString(",")
			}
			b.WriteString(sendJSON(k, s.sends.Get(k).(*Send)))
			n++
			return false
		})
	}
	b.WriteString("]")
	return b.String()
}

// ClaimJSON is one claim by id, or the sweep entry under that id, or "null".
func (s *State) ClaimJSON(id string) string {
	cid, err := CleanID(id)
	if err != nil {
		return "null"
	}
	c := s.ClaimOf(cid)
	if c == nil {
		if e := s.SweepOf(cid); e != nil {
			return sweptJSON(e)
		}
		return "null"
	}
	return claimJSON(c)
}

func claimJSON(c *Claim) string {
	return "{\"id\":" + strconv.Quote(c.ID) + ",\"to\":" + strconv.Quote(string(c.To)) + ",\"amount\":" + itoa(c.Amount) + ",\"paid\":" + itoa(c.Paid) +
		",\"state\":" + strconv.Quote(c.State) + ",\"by\":" + strconv.Quote(c.By) + ",\"at\":" + itoa(c.At) + ",\"height\":" + itoa(c.Height) + ",\"seq\":" + itoa(c.Seq) + "}"
}

// sweptJSON is a sweep entry: {"id","swept","height","by","voided"} ("swept" is the amount, as the agents read it).
func sweptJSON(e *SweepEntry) string {
	return "{\"id\":" + strconv.Quote(e.ID) + ",\"swept\":" + itoa(e.Amount) + ",\"height\":" + itoa(e.Height) + ",\"by\":" + strconv.Quote(e.By) + ",\"voided\":" + strconv.FormatBool(e.Voided) + "}"
}

// Package hyperlane is Hyperlane's wire format, byte for byte, for a mailbox on gno.land: the message and its id,
// the incremental merkle tree the validators checkpoint, the checkpoint digest they sign, a warp route's token
// message, and the multisig check a destination runs over the signatures. It keeps no state and reads no chain.
//
// Sources (hyperlane-monorepo 3cd9308, 2026-10-10): solidity/contracts/libs/Message.sol, Merkle.sol,
// CheckpointLib.sol, TypeCasts.sol, token/libs/TokenMessage.sol, isms/libs/MessageIdMultisigIsmMetadata.sol; the
// vectors in vectors/ are this package's tests.
//
// One departure, and only on the gno side: gno.land has no secp256k1, so the multisig a gno mailbox runs
// (VerifyMultisig) takes ed25519 signatures over the same checkpoint digest Hyperlane's validators sign with
// secp256k1, and each signature names its validator in one leading byte (65 bytes a signature, as in Hyperlane's
// metadata). Messages, ids, the tree and the digest are Hyperlane's exactly, so the other chain's ISM checks a gno
// checkpoint with its stock code.
package hyperlane

import (
	"crypto/bech32"
	"crypto/ed25519"
	"crypto/keccak256"
	"encoding/binary"
	"errors"
)

const (
	// Version is the message version every Hyperlane mailbox speaks (Versioned.VERSION).
	Version = 3
	// HeaderLen is the message header: version 1, nonce 4, origin 4, sender 32, destination 4, recipient 32.
	HeaderLen = 77
	// TreeDepth is the merkle tree's depth (Merkle.sol TREE_DEPTH).
	TreeDepth = 32
	// MaxLeaves is how many leaves the tree takes (Merkle.sol MAX_LEAVES, 2^32 - 1).
	MaxLeaves = 1<<TreeDepth - 1

	sigLen  = 65 // a signature's slot in multisig metadata: Hyperlane's r‖s‖v, here validator byte ‖ ed25519
	metaLen = 68 // the metadata's fixed head: merkle tree hook 32, root 32, index 4
)

// ------------------------------------------------------------- message --

// Message is a Hyperlane message (Message.sol). Sender and recipient are 32 bytes: a 20-byte address is padded on
// the left with twelve zero bytes (AddressToBytes32); a Solana pubkey is its 32 bytes as they are.
type Message struct {
	Version     uint8
	Nonce       uint32
	Origin      uint32
	Sender      [32]byte
	Destination uint32
	Recipient   [32]byte
	Body        []byte
}

// Bytes is the message on the wire: abi.encodePacked of the fields, big-endian, no length prefixes.
func (m Message) Bytes() []byte {
	b := make([]byte, 0, HeaderLen+len(m.Body))
	b = append(b, m.Version)
	b = binary.BigEndian.AppendUint32(b, m.Nonce)
	b = binary.BigEndian.AppendUint32(b, m.Origin)
	b = append(b, m.Sender[:]...)
	b = binary.BigEndian.AppendUint32(b, m.Destination)
	b = append(b, m.Recipient[:]...)
	return append(b, m.Body...)
}

// ID is the message's id: keccak256 of the whole message, body included.
func (m Message) ID() [32]byte { return ID(m.Bytes()) }

// ID is the id of a message as it came off the wire.
func ID(raw []byte) [32]byte { return keccak256.Sum256(raw) }

// ParseMessage reads a message off the wire. The body is a copy.
func ParseMessage(b []byte) (Message, error) {
	if len(b) < HeaderLen {
		return Message{}, errors.New("hyperlane: message shorter than its header")
	}
	var m Message
	m.Version = b[0]
	m.Nonce = binary.BigEndian.Uint32(b[1:5])
	m.Origin = binary.BigEndian.Uint32(b[5:9])
	copy(m.Sender[:], b[9:41])
	m.Destination = binary.BigEndian.Uint32(b[41:45])
	copy(m.Recipient[:], b[45:77])
	m.Body = append([]byte(nil), b[HeaderLen:]...)
	return m, nil
}

// ---------------------------------------------------------- addresses --

// AddressToBytes32 is a gno address as Hyperlane carries one: twelve zero bytes, then the address's twenty
// (TypeCasts.addressToBytes32).
func AddressToBytes32(a address) ([32]byte, error) {
	var out [32]byte
	hrp, bz, err := bech32.DecodeToBase256(string(a))
	if err != nil {
		return out, err
	}
	if hrp != "g" || len(bz) != 20 {
		return out, errors.New("hyperlane: not a gno address: " + string(a))
	}
	copy(out[12:], bz)
	return out, nil
}

// Bytes32ToAddress is the gno address a bytes32 names: twelve zero bytes, then the address's twenty (§13: the top
// 12 bytes must be zero). A bytes32 whose top twelve bytes are not zero — a raw Solana pubkey, say — is no gno
// address and errors, rather than landing on the address its last twenty bytes happen to spell, which nobody
// holds (the EVM's TypeCasts.bytes32ToAddress truncates; a gno route sweeps such a recipient instead, §5.4).
func Bytes32ToAddress(b [32]byte) (address, error) {
	for _, c := range b[:12] {
		if c != 0 {
			return "", errors.New("hyperlane: not a gno address: the top twelve bytes are not zero")
		}
	}
	s, err := bech32.EncodeFromBase256("g", b[12:])
	if err != nil {
		panic(err) // twenty bytes always encode
	}
	return address(s), nil
}

// -------------------------------------------------------- merkle tree --

// Tree is Hyperlane's incremental merkle tree (Merkle.sol, the eth2 deposit contract's): depth 32, nodes
// keccak256(left ‖ right), leaves the message ids themselves. The zero value is the empty tree.
type Tree struct {
	Branch [TreeDepth][32]byte
	Count  uint32
}

// zeroes[i] is the root of an empty subtree of height i: Z0 = 0, Zi+1 = keccak256(Zi ‖ Zi).
var zeroes = func() [TreeDepth][32]byte {
	var z [TreeDepth][32]byte
	for i := 1; i < TreeDepth; i++ {
		z[i] = hash2(z[i-1], z[i-1])
	}
	return z
}()

func hash2(a, b [32]byte) [32]byte {
	buf := make([]byte, 64)
	copy(buf, a[:])
	copy(buf[32:], b[:])
	return keccak256.Sum256(buf)
}

// Insert adds a leaf at index Count.
func (t *Tree) Insert(leaf [32]byte) {
	if t.Count >= MaxLeaves {
		panic("hyperlane: merkle tree full")
	}
	t.Count++
	size := t.Count
	node := leaf
	for i := 0; i < TreeDepth; i++ {
		if size&1 == 1 {
			t.Branch[i] = node
			return
		}
		node = hash2(t.Branch[i], node)
		size >>= 1
	}
	panic("hyperlane: merkle insert fell through") // unreachable: Count < 2^32 has a bit set below 32
}

// Root is the tree's root now (Merkle.sol root(), with the zero hashes).
func (t *Tree) Root() [32]byte {
	var cur [32]byte
	for i := 0; i < TreeDepth; i++ {
		if (t.Count>>uint(i))&1 == 1 {
			cur = hash2(t.Branch[i], cur)
		} else {
			cur = hash2(cur, zeroes[i])
		}
	}
	return cur
}

// ---------------------------------------------------------- checkpoint --

// DomainHash binds a checkpoint to its origin chain and that chain's merkle tree hook: keccak256(origin ‖ hook ‖
// "HYPERLANE"), 45 bytes hashed (CheckpointLib.domainHash). On Solana the hook is the mailbox program's id.
func DomainHash(origin uint32, hook [32]byte) [32]byte {
	b := make([]byte, 0, 45)
	b = binary.BigEndian.AppendUint32(b, origin)
	b = append(b, hook[:]...)
	b = append(b, "HYPERLANE"...)
	return keccak256.Sum256(b)
}

// CheckpointDigest is what a validator signs for one message: the EIP-191 personal-message hash of
// keccak256(domainHash ‖ root ‖ index ‖ messageID) (CheckpointLib.digest). root and index are the origin tree's
// right after messageID went in at index; a message-id ISM does not check them, only the signatures over them.
func CheckpointDigest(origin uint32, hook, root [32]byte, index uint32, messageID [32]byte) [32]byte {
	d := DomainHash(origin, hook)
	b := make([]byte, 0, 100)
	b = append(b, d[:]...)
	b = append(b, root[:]...)
	b = binary.BigEndian.AppendUint32(b, index)
	b = append(b, messageID[:]...)
	return EthSignedMessageHash(keccak256.Sum256(b))
}

// EthSignedMessageHash is EIP-191's hash of a 32-byte message: keccak256("\x19Ethereum Signed Message:\n32" ‖ h).
func EthSignedMessageHash(h [32]byte) [32]byte {
	b := append([]byte("\x19Ethereum Signed Message:\n32"), h[:]...)
	return keccak256.Sum256(b)
}

// -------------------------------------------------------- token message --

// TokenMessage is a warp route's body (TokenMessage.sol): the recipient on the destination, the amount as a
// big-endian uint256, then metadata (usually none).
func TokenMessage(recipient [32]byte, amount uint64, metadata []byte) []byte {
	b := make([]byte, 0, 64+len(metadata))
	b = append(b, recipient[:]...)
	b = append(b, make([]byte, 24)...)
	b = binary.BigEndian.AppendUint64(b, amount)
	return append(b, metadata...)
}

// ParseTokenMessage reads a warp route's body. An amount past 2^64 - 1 is refused; trailing metadata (Solana's
// TransferRemoteWithMemo writes a memo there) is returned, not refused.
func ParseTokenMessage(b []byte) (recipient [32]byte, amount uint64, metadata []byte, err error) {
	if len(b) < 64 {
		return recipient, 0, nil, errors.New("hyperlane: token message shorter than 64 bytes")
	}
	for _, c := range b[32:56] {
		if c != 0 {
			return recipient, 0, nil, errors.New("hyperlane: token amount past 64 bits")
		}
	}
	copy(recipient[:], b[:32])
	return recipient, binary.BigEndian.Uint64(b[56:64]), append([]byte(nil), b[64:]...), nil
}

// ------------------------------------------------------------ multisig --

// Checkpoint is the head of multisig metadata: the origin's merkle tree hook, and the root and index the
// validators signed (MessageIdMultisigIsmMetadata).
type Checkpoint struct {
	Hook  [32]byte
	Root  [32]byte
	Index uint32
}

// Signature is one validator's ed25519 signature and its place in the validator set.
type Signature struct {
	Validator uint8
	Sig       [64]byte
}

// MultisigMetadata lays out what a relayer hands a gno mailbox: hook 32 ‖ root 32 ‖ index 4, then 65 bytes a
// signature: the validator's index in the set, then its ed25519 signature over CheckpointDigest. Validator
// indexes strictly increase, so no validator counts twice.
func MultisigMetadata(c Checkpoint, sigs []Signature) []byte {
	b := make([]byte, 0, metaLen+sigLen*len(sigs))
	b = append(b, c.Hook[:]...)
	b = append(b, c.Root[:]...)
	b = binary.BigEndian.AppendUint32(b, c.Index)
	for _, s := range sigs {
		b = append(b, s.Validator)
		b = append(b, s.Sig[:]...)
	}
	return b
}

// ParseMultisigMetadata reads metadata laid out by MultisigMetadata.
func ParseMultisigMetadata(b []byte) (Checkpoint, []Signature, error) {
	var c Checkpoint
	if len(b) < metaLen || (len(b)-metaLen)%sigLen != 0 {
		return c, nil, errors.New("hyperlane: metadata is not 68 bytes and whole 65-byte signatures")
	}
	copy(c.Hook[:], b[0:32])
	copy(c.Root[:], b[32:64])
	c.Index = binary.BigEndian.Uint32(b[64:68])
	n := (len(b) - metaLen) / sigLen
	sigs := make([]Signature, n)
	for i := 0; i < n; i++ {
		o := metaLen + sigLen*i
		sigs[i].Validator = b[o]
		copy(sigs[i].Sig[:], b[o+1:o+sigLen])
	}
	return c, sigs, nil
}

// VerifyMultisig is a message-id multisig ISM over ed25519: the first threshold signatures in metadata must be
// valid signatures, by distinct validators in increasing order, over the checkpoint digest of this message from
// its own origin. validators are ed25519 public keys of 32 bytes. Signatures past the threshold are not read.
func VerifyMultisig(validators [][]byte, threshold int, metadata, message []byte) error {
	if threshold < 1 || threshold > len(validators) {
		return errors.New("hyperlane: no usable validator set for this origin")
	}
	m, err := ParseMessage(message)
	if err != nil {
		return err
	}
	c, sigs, err := ParseMultisigMetadata(metadata)
	if err != nil {
		return err
	}
	if len(sigs) < threshold {
		return errors.New("hyperlane: fewer signatures than the threshold")
	}
	digest := CheckpointDigest(m.Origin, c.Hook, c.Root, c.Index, ID(message))
	last := -1
	for _, s := range sigs[:threshold] {
		v := int(s.Validator)
		if v <= last {
			return errors.New("hyperlane: signatures out of validator order")
		}
		if v >= len(validators) {
			return errors.New("hyperlane: signature names no validator")
		}
		if !ed25519.Verify(validators[v], digest[:], s.Sig[:]) {
			return errors.New("hyperlane: a signature does not verify")
		}
		last = v
	}
	return nil
}

package hyperlane

import (
	"encoding/hex"
	"errors"
	"strings"
)

// The Bitcoin base58 alphabet, which Solana writes its 32-byte keys in.
const b58 = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"

// ParseKey32 reads a 32-byte key the way a person types one: 64 hex digits (with or without 0x), or a Solana
// address in base58.
func ParseKey32(s string) ([32]byte, error) {
	var out [32]byte
	s = strings.TrimSpace(s)
	if h := strings.TrimPrefix(s, "0x"); len(h) == 64 {
		b, err := hex.DecodeString(h)
		if err != nil {
			return out, errors.New("hyperlane: not hex: " + s)
		}
		copy(out[:], b)
		return out, nil
	}
	if len(s) == 0 || len(s) > 44 {
		return out, errors.New("hyperlane: not a 32-byte key in hex or base58: " + s)
	}
	digits := make([]byte, 0, 32) // the number so far, base 256, least significant first
	for i := 0; i < len(s); i++ {
		c := strings.IndexByte(b58, s[i])
		if c < 0 {
			return out, errors.New("hyperlane: not base58: " + s)
		}
		carry := c
		for j := range digits {
			carry += int(digits[j]) * 58
			digits[j] = byte(carry)
			carry >>= 8
		}
		for carry > 0 {
			digits = append(digits, byte(carry))
			carry >>= 8
		}
	}
	zeros := len(s) - len(strings.TrimLeft(s, "1")) // each leading '1' is a leading zero byte
	if zeros+len(digits) != 32 {
		return out, errors.New("hyperlane: base58 key is not 32 bytes: " + s)
	}
	for i, d := range digits {
		out[31-i] = d
	}
	return out, nil
}

// Base58 writes bytes the way Solana writes a key.
func Base58(b []byte) string {
	zeros := 0
	for zeros < len(b) && b[zeros] == 0 {
		zeros++
	}
	digits := make([]byte, 0, len(b)*138/100+1) // base 58, least significant first
	for _, x := range b[zeros:] {
		carry := int(x)
		for j := range digits {
			carry += int(digits[j]) << 8
			digits[j] = byte(carry % 58)
			carry /= 58
		}
		for carry > 0 {
			digits = append(digits, byte(carry%58))
			carry /= 58
		}
	}
	out := make([]byte, zeros+len(digits))
	for i := 0; i < zeros; i++ {
		out[i] = '1'
	}
	for i, d := range digits {
		out[len(out)-1-i] = b58[d]
	}
	return string(out)
}

package hlmailbox

import (
	"chain"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlroute/v0"
)

// The guardians and the watch keys (bridge/PLAN.md §5.1, §5.3): six numbered seats — 1 to 4 the guardians (3 and 4
// the outsiders'), 5 and 6 the operator's two monitors' watch keys — each holding one gno address, and three pause
// flags per seat per route: sends (refuses the route's TransferRemote), credits (refuses its Process) and payouts
// (refuses its Claim). A function of a route is refused while any seat's flag for it stands. A seat sets and clears
// its own flags; GovDAO's unpause clears every seat's flag for the functions it names, and a seat removed or
// replaced loses its flags. A guardian's payouts flag may carry the message ids it suspects — a list, or a range of
// credits (hlroute.Range: "heights:<from>-<to>", or "since:<from>" for the verifier's credits from that height on,
// so one flag covers a flood larger than a list) — which is what unlocks GovDAO's at-once void of those claims; a
// watch key's never does.
//
// The meters (§5.4) start empty after every unpause, or removal, that clears a STANDING payouts flag: this realm
// counts those events per route (the payouts epoch) and the route realms read the count.

const (
	seatCount  = 6
	guardians  = 4
	FnSends    = "sends"
	FnCredits  = "credits"
	FnPayouts  = "payouts"
	maxFlagIDs = 256 // ids a payouts flag may name

	// The launch seats (§5.3, §11.9): PLACEHOLDERS until the four people and the two monitors have keys — seat 1
	// is Jae's cold key, the rest derived test addresses — replaced in the deployed source the launch vote reads.
	launchSeat1 = address("g1562mcsvwrd2hm3nj7and8ggexdqd3hnag20cmv")
	launchSeat2 = address("g16l5nrlrp9pd8rdld7vzylrthfusv30apeq0n6z")
	launchSeat3 = address("g1acuz6nhl9hyka2a4t9t965kmd8t355hy7ukur5")
	launchSeat4 = address("g1d6nckzj9n8udw8apwrxfg929p8zm330d664ucy")
	launchSeat5 = address("g1m8d47hlnmp77rpkamxphlx9q6jfvejt89j7hfj")
	launchSeat6 = address("g1gdudkuvqdxwfncvmualymvyufdj8u7m893czuv")
)

var (
	seats         [seatCount + 1]address // by seat number; 0 unused
	routes        avl.Tree               // pkgpath → *routeRec
	flags         avl.Tree               // flagKey(route, fn, seat) → *flag
	successors    avl.Tree               // pkgpath → the route it announced for (SymbolGNOT or SymbolBUBBLE): every realm that announced itself as a route's possible successor (R25, AQ5)
	droppedRoutes avl.Tree               // pkgpath → the predecessor whose re-point dropped it (R35): the tombstone of a successor that is a route no more, cleared if a later migrate registers it afresh
)

// The routes a successor announces for (AQ5): a migrate names only a successor announced for its own route, so a
// slip never sends the GNOT lock to a realm whose code moves BUBBLE, or the other way round.
const (
	SymbolGNOT   = "GNOT"
	SymbolBUBBLE = "BUBBLE"
)

// routeRec is one route realm's record here: its payouts epoch, its place in the chain of migrations (AQ1), the
// kind 6 that enrolled it on Solana (AR1), whether it pulled page 0 of its predecessor's migration, and the
// successors its own re-points dropped (R35).
type routeRec struct {
	epoch       int64    // bumps whenever an unpause or a removal clears a standing payouts flag
	epochAt     int64    // unix time of the last bump
	predecessor string   // the route whose migrate registered this one; "" for a launch route
	successor   string   // the route this one's migrate registered; "" until it migrated
	enrolled    int64    // the block height r/hlgov last dispatched a kind 6 enrolling this route as the token's router on Solana (NoteEnrolled); 0 if never
	enrolledAt  int64    // unix time of that dispatch
	pulled      bool     // this successor pulled page 0 of its predecessor's migration, as the predecessor's Pull noted it (NotePulled, R35): the lock moved, the migration is never re-pointed, kind 6 may enrol it
	dropped     []string // the successors this route's re-points dropped (R35): each a route no more, in nobody's chain; the line's live last realm takes a message addressed to one, once its import has ended
}

// maxChain bounds the walk along a route's predecessors (Process): a chain never cycles, since AddRoute refuses a
// path that is a route already, and a bridge sees a handful of migrations in its life.
const maxChain = 16

// flag is one seat's standing flag on one function of one route.
type flag struct {
	seat   int
	at     int64         // unix time it was set, or last re-asserted
	ids    []string      // a guardian's payouts flag: the message ids it suspects (none for the other flags) …
	ranged bool          // … or the range of credits it suspects
	rng    hlroute.Range //
}

func initSeats() {
	seats[1], seats[2], seats[3], seats[4], seats[5], seats[6] = launchSeat1, launchSeat2, launchSeat3, launchSeat4, launchSeat5, launchSeat6
}

func flagKey(route, fn string, seat int) string { return route + "|" + fn + "|" + strconv.Itoa(seat) }
func flagPrefix(route, fn string) string    { return route + "|" + fn + "|" }

func isFn(fn string) bool { return fn == FnSends || fn == FnCredits || fn == FnPayouts }

func now() int64 { return time.Now().Unix() }

// ------------------------------------------------------------- reading --

// Seat is the address in a seat (1–4 guardians, 5–6 watch keys); "" if the seat is empty.
func Seat(n int) address {
	if n < 1 || n > seatCount {
		return ""
	}
	return seats[n]
}

// SeatOf is the seat an address holds, 0 if none.
func SeatOf(a address) int {
	if a == "" {
		return 0
	}
	for i := 1; i <= seatCount; i++ {
		if seats[i] == a {
			return i
		}
	}
	return 0
}

// IsGuardianSeat is whether a seat number is a guardian's (1–4) rather than a watch key's (5–6).
func IsGuardianSeat(n int) bool { return n >= 1 && n <= guardians }

// IsRoute is whether a pkgpath is one of the route realms this mailbox keeps flags for.
func IsRoute(path string) bool { return routes.Has(path) }

// Routes lists the route realms' pkgpaths.
func Routes() []string {
	var out []string
	routes.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// DroppedRoutes lists the dropped successors' pkgpaths (R35's tombstones; Dropped names each one's predecessor):
// routes no more, whose addresses the routes still refuse as a send's recipient and sweep at a credit (AT6), as a
// registered route's — a holder may have pasted one as a deposit address while its page printed it as the lock's
// holder to be, and a claim credited to it would be paid into a realm no counter of the line holds. Bounded by the
// re-points a bridge sees in its life, as Routes is by its migrations.
func DroppedRoutes() []string {
	var out []string
	droppedRoutes.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

// Paused is what the routes ask: whether any seat's flag for fn stands on route.
func Paused(route, fn string) bool {
	found := false
	flags.Iterate(flagPrefix(route, fn), flagPrefix(route, fn)+"~", func(_ string, _ any) bool {
		found = true
		return true
	})
	return found
}

// Flagged is whether some guardian's standing payouts flag on route names this claim — by its message id, or by a
// range covering the height it was credited at (a "since" range only if the verifier credited it): the test that
// makes GovDAO's void of that claim at once (§5.3). A watch key's flag never counts.
func Flagged(route, id string, height int64, verifier bool) bool {
	id = cleanID(id)
	found := false
	flags.Iterate(flagPrefix(route, FnPayouts), flagPrefix(route, FnPayouts)+"~", func(_ string, v any) bool {
		f := v.(*flag)
		if !IsGuardianSeat(f.seat) {
			return false
		}
		if f.ranged && f.rng.Covers(height, verifier) {
			found = true
			return true
		}
		for _, x := range f.ids {
			if x == id {
				found = true
				return true
			}
		}
		return false
	})
	return found
}

// PayoutsEpoch is how many times an unpause or a removal cleared a standing payouts flag on route, and when the
// last one did: the routes empty their meters when it changes (§5.4).
func PayoutsEpoch(route string) (epoch, at int64) {
	v := routes.Get(route)
	if v == nil {
		return 0, 0
	}
	r := v.(*routeRec)
	return r.epoch, r.epochAt
}

// Flags lists the standing flags of a route as "fn seat@time[ids…]" lines.
func Flags(route string) []string {
	var out []string
	flags.Iterate(route+"|", route+"|~", func(k string, v any) bool {
		f := v.(*flag)
		fn := strings.Split(k, "|")[1]
		s := fn + " by seat " + strconv.Itoa(f.seat) + " (" + string(seats[f.seat]) + ") at " + strconv.FormatInt(f.at, 10)
		if f.ranged {
			s += " naming " + f.rng.String()
		} else if len(f.ids) > 0 {
			s += " naming " + strings.Join(f.ids, ",")
		}
		out = append(out, s)
		return false
	})
	return out
}

// ------------------------------------------------------------- flagging --

func mustBeRoute(cur realm) string {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	path := cur.Previous().PkgPath()
	if !routes.Has(path) {
		panic("hlmailbox: only a route realm, not " + path)
	}
	return path
}

// parseIDs reads what a payouts flag names: a range (hlroute.ParseRange's forms), or a comma-separated list of
// message ids, at most maxFlagIDs; "" names nothing.
func parseIDs(s string) (ids []string, rng hlroute.Range, ranged bool) {
	if strings.TrimSpace(s) == "" {
		return nil, rng, false
	}
	if r, ok := hlroute.ParseRange(s); ok {
		return nil, r, true
	}
	parts := strings.Split(s, ",")
	if len(parts) > maxFlagIDs {
		panic("hlmailbox: more than " + strconv.Itoa(maxFlagIDs) + " ids")
	}
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		id := cleanID(p)
		if b, err := hex.DecodeString(id); err != nil || len(b) != 32 {
			panic("hlmailbox: not a 32-byte message id in hex: " + id)
		}
		dup := false
		for _, x := range out {
			if x == id {
				dup = true
			}
		}
		if !dup {
			out = append(out, id)
		}
	}
	return out, rng, false
}

// SetFlag sets, or re-asserts, the caller's flag on one function of a route: fn is sends, credits or payouts. ids
// is what a guardian's payouts flag suspects — a comma-separated list of message ids, or a range of credits
// ("heights:<from>-<to>" inclusive, or "since:<from>" for every credit the verifier makes from that height on) —
// "" otherwise; a re-assertion replaces it. A watch key's flag never names ids or a range.
func SetFlag(cur realm, route, fn, ids string) {
	who := caller(cur)
	seat := SeatOf(who)
	if seat == 0 {
		panic("hlmailbox: not a guardian or a watch key: " + string(who))
	}
	if !routes.Has(route) {
		panic("hlmailbox: no route " + route)
	}
	if !isFn(fn) {
		panic("hlmailbox: the function must be sends, credits or payouts, not " + fn)
	}
	list, rng, ranged := parseIDs(ids)
	if (len(list) > 0 || ranged) && (fn != FnPayouts || !IsGuardianSeat(seat)) {
		panic("hlmailbox: only a guardian's payouts flag names ids, or a range")
	}
	flags.Set(flagKey(route, fn, seat), &flag{seat: seat, at: now(), ids: list, ranged: ranged, rng: rng})
	named := strconv.Itoa(len(list))
	if ranged {
		named = rng.String()
	}
	chain.Emit("Flag", "route", route, "fn", fn, "seat", strconv.Itoa(seat), "ids", named)
}

// ClearFlag clears the caller's own flag on one function of a route. It resets no meter.
func ClearFlag(cur realm, route, fn string) {
	who := caller(cur)
	seat := SeatOf(who)
	if seat == 0 {
		panic("hlmailbox: not a guardian or a watch key: " + string(who))
	}
	if _, ok := flags.Remove(flagKey(route, fn, seat)); !ok {
		panic("hlmailbox: no such flag of yours")
	}
	chain.Emit("Unflag", "route", route, "fn", fn, "seat", strconv.Itoa(seat))
}

// ClearFlags clears every seat's flag for fn on the calling route — the void builder's andUnpause option (§5.3),
// which reopens payouts in the same closure as the void. It reports whether any flag was cleared.
func ClearFlags(cur realm, fn string) bool {
	path := mustBeRoute(cur)
	if !isFn(fn) {
		panic("hlmailbox: the function must be sends, credits or payouts, not " + fn)
	}
	n, _ := clearFns(path, []string{fn}, now())
	return n > 0
}

// VacateSeat removes the key in a seat if holder still has it, its flags with it (a payouts flag among them
// restarting the route's meters): the void builder's unpause option retires keys in the same closure as the void
// (§5.3). Only a route realm may call it. It reports whether the seat was vacated: a seat whose occupant changed
// since the proposal named it, or one emptied since, is left as it is (R17), so a replacement that landed in
// between is never undone by a removal that meant the key before it.
func VacateSeat(cur realm, seat int, holder address) bool {
	mustBeRoute(cur)
	if seat < 1 || seat > seatCount {
		panic("hlmailbox: the seat must be 1 to 6")
	}
	if seats[seat] == "" || seats[seat] != holder {
		return false
	}
	clearSeat(seat, now())
	seats[seat] = ""
	chain.Emit("SeatSet", "seat", strconv.Itoa(seat), "address", "")
	return true
}

// AddRoute registers a successor route realm (a route's migrate names it), so flags can be set on it too, and
// records the succession both ways (AQ1): the caller's `successor`, the new route's `predecessor`, which is what
// lets the successor take a message addressed to the predecessor (Process) — the burns name the predecessor until
// kind 6 enrolls the successor. The path is a deployed realm's: a sub-identity's (`host#subpath`) is refused, since
// the route powers are keyed by exact pkgpath (mustBeRoute) and such a path would hand them to a token its host
// mints for free; a path that is a route already is refused (a chain never cycles). A route that migrated already
// re-points its migration (AR2): its migrate decision names another successor while the first pulled nothing —
// the route's own state refuses once page 0 moved, and a first successor that migrated on holds the lock, so it
// is refused here too — and the first's registration is dropped with the flags copied to it, the new path taking
// its place with the flags standing on the route now.
func AddRoute(cur realm, path string) {
	from := mustBeRoute(cur)
	if !strings.HasPrefix(path, "gno.land/r/") || strings.Contains(path, "#") {
		panic("hlmailbox: a route is a realm under gno.land/r/, not " + path)
	}
	if routes.Has(path) {
		panic("hlmailbox: " + path + " is a route already")
	}
	rec := routes.Get(from).(*routeRec)
	if old := rec.successor; old != "" {
		if s := Successor(old); s != "" {
			panic("hlmailbox: " + from + " migrated to " + old + ", which migrated on to " + s + " already: the migration is under way and cannot be re-pointed")
		}
		if Pulled(old) {
			panic("hlmailbox: " + from + " migrated to " + old + ", which pulled page 0 already: the migration is under way and cannot be re-pointed")
		}
		dropRoute(from, rec, old)
	}
	rec.successor = path
	undrop(path)
	routes.Set(path, &routeRec{predecessor: from})
	n := copyFlags(from, path)
	chain.Emit("RouteAdded", "pkgpath", path, "predecessor", from, "flags", strconv.Itoa(n))
}

// dropRoute forgets a successor's registration (AR2: its predecessor re-pointed the migration before it pulled
// anything): the record and every flag standing on its path. It is a route no more — nothing addressed to its
// predecessor is its to take, no route power is its — but it is remembered (R35): on its predecessor's record and
// as a tombstone, since Solana's token may still name it the router until the next kind 6 and a burn addressed to
// it must be the line's last realm's to take, never its own. A later migrate may register it afresh (undrop).
func dropRoute(from string, rec *routeRec, path string) {
	routes.Remove(path)
	var keys []string
	flags.Iterate(path+"|", path+"|~", func(k string, _ any) bool {
		keys = append(keys, k)
		return false
	})
	for _, k := range keys {
		flags.Remove(k)
	}
	rec.dropped = append(rec.dropped, path)
	droppedRoutes.Set(path, from)
	chain.Emit("RouteDropped", "pkgpath", path, "predecessor", from, "flags", strconv.Itoa(len(keys)))
}

// undrop clears a path's tombstone when a migrate registers it afresh (R35): the migration re-pointed back to it
// while the newer successor pulled nothing, or a later route of the line named it. It is then a route like any
// other, with nothing pulled.
func undrop(path string) {
	v := droppedRoutes.Get(path)
	if v == nil {
		return
	}
	by := v.(string)
	droppedRoutes.Remove(path)
	if r := routes.Get(by); r != nil {
		rec := r.(*routeRec)
		var kept []string
		for _, p := range rec.dropped {
			if p != path {
				kept = append(kept, p)
			}
		}
		rec.dropped = kept
	}
	chain.Emit("RouteUndropped", "pkgpath", path, "predecessor", by)
}

// Dropped is the predecessor whose re-point dropped the realm at path from the line (R35) — a route no more, in
// nobody's chain, that neither sends (Dispatch refuses it) nor takes (Process refuses it) — or "" for a route, a
// realm never registered, or one registered afresh since.
func Dropped(path string) string {
	v := droppedRoutes.Get(path)
	if v == nil {
		return ""
	}
	return v.(string)
}

// Pulled is whether the successor at path pulled page 0 of its predecessor's migration, as the predecessor's Pull
// noted it (NotePulled): the lock and the counters moved, so the migration is never re-pointed and a kind 6 may
// enrol it (R35). False for a launch route, a successor that pulled nothing, or no route.
func Pulled(path string) bool {
	v := routes.Get(path)
	if v == nil {
		return false
	}
	return v.(*routeRec).pulled
}

// NotePulled is the predecessor's note, from its Pull, that the successor its migrate registered has pulled page 0
// (R35): the lock and the counters moved with it, so the migration is under way — the route's own state refuses a
// re-point from here on, and AddRoute refuses one too — and r/hlgov's kind 6 may enrol the successor: before it a
// kind 6 could name a route a re-point then drops, leaving Solana's token minting for a realm in nobody's chain.
// Only the route whose successor it is notes it; a second note (a second Pull of page 0) changes nothing.
func NotePulled(cur realm, path string) {
	from := mustBeRoute(cur)
	rec := routes.Get(from).(*routeRec)
	if rec.successor != path {
		panic("hlmailbox: " + path + " is not " + from + "'s successor")
	}
	sv := routes.Get(path).(*routeRec)
	if !sv.pulled {
		sv.pulled = true
		chain.Emit("RoutePulled", "pkgpath", path, "predecessor", from)
	}
}

// copyFlags gives the route at `to` a copy of every flag standing on `from` — the seat, the time it was set, the
// ids or the range it names — keyed by the new path (R27): the pause follows the lock and the claims to the
// successor, whose Claim and Process ask their own path's flags, and clears there as any flag does — by the
// seat, by GovDAO's unpause, or with the seat's removal. It reports how many were copied.
func copyFlags(from, to string) (n int) {
	var keys []string
	var fs []*flag
	flags.Iterate(from+"|", from+"|~", func(k string, v any) bool {
		keys = append(keys, k)
		fs = append(fs, v.(*flag))
		return false
	})
	for i, k := range keys {
		f := fs[i]
		fn := strings.Split(k, "|")[1]
		flags.Set(flagKey(to, fn, f.seat), &flag{seat: f.seat, at: f.at, ids: append([]string(nil), f.ids...), ranged: f.ranged, rng: f.rng})
		n++
	}
	return n
}

// Predecessor is the route whose migrate registered path as its successor; "" for a launch route, or no route.
func Predecessor(path string) string {
	v := routes.Get(path)
	if v == nil {
		return ""
	}
	return v.(*routeRec).predecessor
}

// Successor is the route path's migrate registered; "" while it never migrated, or for no route.
func Successor(path string) string {
	v := routes.Get(path)
	if v == nil {
		return ""
	}
	return v.(*routeRec).successor
}

// Enrolled is the block height and unix time r/hlgov last dispatched a kind 6 enrolling the route at path as the
// token's router on Solana (NoteEnrolled); 0, 0 if never, or for no route. A route's refund builder waits 7 days
// after it (AR1).
func Enrolled(path string) (height, at int64) {
	v := routes.Get(path)
	if v == nil {
		return 0, 0
	}
	r := v.(*routeRec)
	return r.enrolled, r.enrolledAt
}

// mustBeHlgov is the caller check of what r/hlgov alone does here: its exact pkgpath, read from the live cur.
func mustBeHlgov(cur realm) {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	if p := cur.Previous().PkgPath(); p != hlgovPath {
		panic("hlmailbox: only " + hlgovPath + " notes an enrolment, not " + p)
	}
}

// NoteEnrolled is r/hlgov's note, from its kind-6 closure, that it dispatched a decision enrolling the route at
// path as the token's router on Solana at this block height (AR1): the route's refund builder and its apply read
// it (Enrolled) and refuse a refund until the note is 14 days old (R37: a week for the delivery, a week for
// Solana's own clock), since a refunded send stays deliverable on Solana until the predecessor's router is
// replaced and a refund that lands first lets one stranger's Reemit and delivery mint it twice. The latest note
// counts: a later kind 6 for the route restarts the wait; a cancelled one clears it (ClearEnrolled). Necessary,
// not sufficient — the realm cannot see Solana; hlwatch reads the token's enrolled router there and alarms a
// refund proposal whose successor the token has not enrolled.
func NoteEnrolled(cur realm, path string, height int64) {
	mustBeHlgov(cur)
	v := routes.Get(path)
	if v == nil {
		panic("hlmailbox: no route " + path)
	}
	if height < 1 {
		panic("hlmailbox: not a block height: " + strconv.FormatInt(height, 10))
	}
	r := v.(*routeRec)
	r.enrolled, r.enrolledAt = height, now()
	chain.Emit("RouteEnrolled", "pkgpath", path, "height", strconv.FormatInt(height, 10))
}

// ClearEnrolled is r/hlgov's word, from its cancel closure, that the kind 6 whose note stands on the route at path
// was cancelled (R37, AS2): the note goes, so the route's refund gate reads "no kind 6" again and its clock
// restarts with a re-proposal — before, a cancelled, lost or held kind 6 left the note standing and the gate
// opened on the realm's clock alone while the predecessor was still the enrolled router. r/hlgov's exact pkgpath
// alone, for a route; a route with no note is left as it is.
func ClearEnrolled(cur realm, path string) {
	mustBeHlgov(cur)
	v := routes.Get(path)
	if v == nil {
		panic("hlmailbox: no route " + path)
	}
	r := v.(*routeRec)
	if r.enrolled == 0 {
		return
	}
	r.enrolled, r.enrolledAt = 0, 0
	chain.Emit("RouteEnrolmentCleared", "pkgpath", path)
}

// successorOf is whether the route at path succeeds the route whose address, as 32 bytes, is recipient — along the
// chain of migrations, at any distance (AQ1): a burn addressed to a migrated route is taken by the successor that
// holds its lock. A successor a predecessor's re-point dropped counts as that predecessor's (R35): a burn made
// while Solana still named it the router is the line's live last realm's to take, never its own. A caller that is
// no route, or whose chain never reaches the recipient, is not.
func successorOf(path string, recipient [32]byte) bool {
	for i := 0; i < maxChain && path != ""; i++ {
		v := routes.Get(path)
		if v == nil {
			return false
		}
		path = v.(*routeRec).predecessor
		if path == "" {
			return false
		}
		if mustBytes32(chain.PackageAddress(path)) == recipient {
			return true
		}
		if pv := routes.Get(path); pv != nil {
			for _, d := range pv.(*routeRec).dropped {
				if mustBytes32(chain.PackageAddress(d)) == recipient {
					return true
				}
			}
		}
	}
	return false
}

// AnnounceSuccessor is how a realm offers itself as a route's successor (R25): called once from that realm's own
// code (its init, usually), naming the route it succeeds — GNOT or BUBBLE (AQ5: a migrate names only a successor
// announced for its own route) — it is kept under the caller's exact pkgpath, which a route's migrate builder and
// its closure require of the path they name — so the lock never goes to a path with no realm behind it (a typo,
// or an undeployed path whose namespace owner could deploy anything there and pull the lock). Only an /r/ realm,
// with its own cur: a sub-realm identity (host#subpath, a token a realm mints for free) is refused as in
// RegisterVerifier, so every entry costs a package deployment and the listing (render.gno) is bounded. Nothing is
// ever withdrawn; GovDAO reads the successor's source before it votes, as before.
func AnnounceSuccessor(cur realm, symbol string) {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	path := cur.Previous().PkgPath()
	if !strings.HasPrefix(path, "gno.land/r/") {
		panic("hlmailbox: only a realm under gno.land/r/ announces itself as a successor, not " + path)
	}
	if cur.Previous().Subpath() != "" {
		panic("hlmailbox: a realm announces itself with its own cur, not a sub-identity (" + path + ")")
	}
	if symbol != SymbolGNOT && symbol != SymbolBUBBLE {
		panic("hlmailbox: the route a successor announces for is GNOT or BUBBLE, not " + symbol)
	}
	if successors.Has(path) {
		panic("hlmailbox: " + path + " announced itself already")
	}
	successors.Set(path, symbol)
	chain.Emit("SuccessorAnnounced", "pkgpath", path, "route", symbol)
}

// SuccessorAnnounced is whether a realm at this pkgpath announced itself as a possible successor: what a route's
// migrate builder and its closure require of the path they name (R25).
func SuccessorAnnounced(path string) bool { return successors.Has(path) }

// SuccessorFor is the route — GNOT or BUBBLE — a realm at this pkgpath announced itself as a successor of (AQ5);
// "" if it never announced itself. A route's migrate builder and its closure refuse another route's successor.
func SuccessorFor(path string) string {
	v := successors.Get(path)
	if v == nil {
		return ""
	}
	return v.(string)
}

// RouteSymbol is the token a realm's route is for (R36): the launch paths' compiled symbols; for every other
// realm the route it announced itself a successor of (SuccessorFor — a registered successor always announced,
// AQ5); "" for one that never did. r/hlgov's kind 6 compares it with the token it names, so a slip can never
// enrol one token's route as the other's router.
func RouteSymbol(path string) string {
	switch path {
	case launchRouteGNOT:
		return SymbolGNOT
	case launchRouteBUBBLE:
		return SymbolBUBBLE
	}
	return SuccessorFor(path)
}

// clearFns removes every seat's flag for the named functions on a route; payouts says whether a standing payouts
// flag went with them, in which case the route's meters restart (the epoch bumps).
func clearFns(path string, fns []string, t int64) (n int, payouts bool) {
	for _, fn := range fns {
		var keys []string
		flags.Iterate(flagPrefix(path, fn), flagPrefix(path, fn)+"~", func(k string, _ any) bool {
			keys = append(keys, k)
			return false
		})
		for _, k := range keys {
			flags.Remove(k)
			n++
			if fn == FnPayouts {
				payouts = true
			}
		}
	}
	if payouts {
		bump(path, t)
	}
	return n, payouts
}

// clearSeat removes every flag a seat holds, on every route, bumping the epoch of each route where a payouts
// flag stood.
func clearSeat(seat int, t int64) (n int) {
	suffix := "|" + strconv.Itoa(seat)
	var keys []string
	flags.Iterate("", "", func(k string, v any) bool {
		if strings.HasSuffix(k, suffix) && v.(*flag).seat == seat {
			keys = append(keys, k)
		}
		return false
	})
	for _, k := range keys {
		flags.Remove(k)
		n++
		parts := strings.Split(k, "|")
		if parts[1] == FnPayouts {
			bump(parts[0], t)
		}
	}
	return n
}

func bump(path string, t int64) {
	v := routes.Get(path)
	if v == nil {
		return
	}
	r := v.(*routeRec)
	r.epoch++
	r.epochAt = t
	chain.Emit("PayoutsReset", "route", path, "epoch", strconv.FormatInt(r.epoch, 10))
}

package hlmailbox

import (
	"chain"
	"chain/runtime"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	"gno.land/r/gov/dao"
)

// The builders (bridge/PLAN.md §5.3): the only way a setting of this realm changes is a decision made with one of
// the New…Request functions — before the governor yields, the governor's own `maketx run` script (M1k):
//
//	hlmailbox.Govern(cross(cur), hlmailbox.NewSetVerifierRequest(cross(cur), origin, path))
//
// and after it a GovDAO proposal from a member's:
//
//	req := hlmailbox.NewSetVerifierRequest(cross(cur), origin, path)
//	dao.MustCreateProposal(cross(cur), req.Proposal())
//
// A builder takes no free text: it checks its parameters, writes them as the proposal's description, and returns
// a Request whose closure runs when the decision is made — the one closure, whether the governor runs it through
// Govern or GovDAO's proxy runs it when the proposal executes. The closure checks who decides (mustBeGovernor: the
// governor's own call until the yield, gno.land/r/gov/dao's proxy after), returns an error only when the request
// is past its 14-day deadline (GovDAO then denies the proposal for good; Govern panics with it) and panics on
// anything else (a proposal survives for a retry), gives the decision a number, and decides the at-once test
// against the live state: a removal or an unpause applies at once; a swap or an addition is queued 7 days and
// anyone applies it with Execute(id) after that. Launch is the one-shot that makes the realms live; it carries the
// same 14-day deadline (a passed launch nobody executed in 14 days lapses and is re-proposed, never a standing
// trap); before it every builder but Launch and cancel is refused.

// Request is what a builder returns (M1k): the proposal GovDAO's proxy executes after the yield (Proposal), and
// the same decision the governor runs directly before it (Govern). The closure is one; only who may run it
// changes with the yield. A Request comes from a builder alone — the type is this realm's and the closure
// unexported, so no other code can build one or change what it decides (the construction and conversion guards of
// the interrealm spec, §3.2 and §8.2) — and a stranger holding one can only hand it back to Govern, which refuses
// everyone but the governor.
type Request struct {
	proposal dao.ProposalRequest
	text     string
	decide   func(cur realm) error
}

// Proposal is the request as a GovDAO proposal: `dao.MustCreateProposal(cross(cur), req.Proposal())`.
func (r Request) Proposal() dao.ProposalRequest { return r.proposal }

// Description is the proposal's: the parameters as the builder wrote them.
func (r Request) Description() string { return r.text }

type (
	launchParams        struct{}
	setVerifierParams   struct {
		origin uint32
		path   string
	}
	rotateSignersParams struct {
		keys []Key
		rule Rule
		// A queued rotation keeps the signer set and rule it was decided against; Execute applies it only while
		// they still stand, so a removal made in between (a compromised key cut at once) can never be undone by
		// an older proposal landing on its 7th day — GovDAO proposes afresh against the set as it is.
		oldKeys []Key
		oldRule Rule
	}
	rotateSeatsParams struct {
		seats  []int
		addrs  []address               // "" removes the seat
		held   []address               // each seat's holder when the proposal was made: a removal of a seat whose occupant changed since is skipped (R21, as the void's and the unpause's, R17)
		before [seatCount + 1]address // the six seats as they stood when the proposal executed (a queued change applies only while they stand)
	}
	unpauseParams struct {
		route      string
		fns        []string
		removeSeat int
		removeAddr address // the seat's holder when the proposal was made: the seat is vacated only while it still holds it (R17)
	}
	cancelParams struct{ id int64 }
)

// who names a previous realm in a refusal: its pkgpath, or a user's address.
func who(path string, a address) string {
	if path != "" {
		return path
	}
	return string(a)
}

// mustBeGovernor is a decision's identity check (M1k), read from the closure's own live cur: until the yield the
// governor's own call — the compiled address, by its own transaction (cur.Previous() a user realm: a MsgCall's, or
// a MsgRun script's ephemeral realm, whose address is the signer's; never another realm), which is Govern's
// non-crossing call of the closure — and gno.land/r/gov/dao's proposals refused; after it, or when no governor
// was compiled, the proxy's exact pkgpath, as before M1k, and the governor refused like anyone. A refusal is a
// panic: a proposal made before the yield survives for a retry after it, within its 14 days.
func mustBeGovernor(cur realm) {
	prev := cur.Previous()
	if decisions.DAOGoverns(launchGovernor, yielded) {
		if p := prev.PkgPath(); p != decisions.DAOPath {
			panic("hlmailbox: only " + decisions.DAOPath + " executes a decision, not " + who(prev.PkgPath(), prev.Address()))
		}
		return
	}
	if !prev.IsUser() || prev.Address() != launchGovernor {
		panic("hlmailbox: until the governor yields, " + string(launchGovernor) + " alone decides, by Govern from its own key: not " + who(prev.PkgPath(), prev.Address()) + " (a GovDAO proposal is refused until the yield)")
	}
}

func mustBeLive() {
	if !live {
		panic("hlmailbox: not launched: before the Launch decision only Launch and cancel are proposed")
	}
}

// propose wraps a builder's effect in the closure every builder shares. apply runs at the decision with the time
// the request was made and the time now; it records the decision.
func propose(cur realm, kind, text string, apply func(made, t int64)) Request {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	made := now()
	cb := func(cur realm) error {
		mustBeGovernor(cur)
		t := now()
		if err := decisions.Expired(made, t); err != nil {
			return err
		}
		apply(made, t)
		return nil
	}
	return request(cur, kind, text, cb)
}

// request is a builder's Request: the proposal around the closure for GovDAO's path, the closure itself for the
// governor's.
func request(cur realm, kind, text string, cb func(cur realm) error) Request {
	return Request{proposal: dao.NewProposalRequest("hlmailbox: "+kind, text, dao.NewSimpleExecutor(0, cur, cb, text)), text: text, decide: cb}
}

// Govern is the governor's way in before the yield (M1k): the governor — the compiled launchGovernor, by its own
// transaction (a MsgCall, or the MsgRun script that makes the request in the same transaction; never through
// another realm) — makes a builder's decision directly, the same closure GovDAO's proxy runs after the yield: the
// same checks, the same at-once test, the same 7-day queue and 14-day deadline, the same record and events. The
// closure is called non-crossing, in this frame, so it reads the governor from cur.Previous() as it reads the
// proxy after the yield. Refused for anyone else, and for everyone once the governor yielded (or when none was
// compiled): GovDAO's proposals decide then. A request past its 14 days is refused (the deadline error, as a
// proposal's denial) and made afresh.
func Govern(cur realm, r Request) {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	if r.decide == nil {
		panic("hlmailbox: not a builder's request")
	}
	if decisions.DAOGoverns(launchGovernor, yielded) {
		panic("hlmailbox: " + governedBy() + ": a decision is a GovDAO proposal, never Govern")
	}
	mustBeGovernor(cur)
	if err := r.decide(cur); err != nil {
		panic("hlmailbox: " + err.Error())
	}
}

// governedBy says why Govern is closed: the yield's height, or no governor compiled.
func governedBy() string {
	if launchGovernor == "" {
		return "no governor was compiled, " + decisions.DAOPath + " governs from the first block"
	}
	return "the governor yielded at height " + strconv.FormatInt(yielded, 10) + ", " + decisions.DAOPath + " governs since"
}

// Yield is the governor's one-way hand-over to GovDAO (M1k): from this block gno.land/r/gov/dao's proposals are
// the only way a decision is made on every bridge realm — each reads Yielded here before it accepts one, so no
// realm is ever yielded apart from the rest — and Govern is closed for good. The governor alone, by its own
// transaction; refused when no governor was compiled (GovDAO governs from the first block) and a second time. A
// decision the governor queued still applies by Execute(id) after its 7 days, or GovDAO cancels it.
func Yield(cur realm) {
	caller(cur)
	if launchGovernor == "" {
		panic("hlmailbox: no governor was compiled: " + decisions.DAOPath + " governs from the first block")
	}
	if yielded != 0 {
		panic("hlmailbox: the governor yielded at height " + strconv.FormatInt(yielded, 10) + " already")
	}
	prev := cur.Previous()
	if !prev.IsUser() || prev.Address() != launchGovernor {
		panic("hlmailbox: only the governor " + string(launchGovernor) + " yields, not " + who(prev.PkgPath(), prev.Address()))
	}
	yielded = runtime.ChainHeight() // never 0: the chain's first executing block is height 1
	chain.Emit("Yielded", "governor", string(launchGovernor), "height", strconv.FormatInt(yielded, 10))
}

func queue(kind, text string, params any, made, t int64) *decisions.Decision {
	d := ledger.Record(kind, text, params, made, t, t+decisions.Delay)
	d.Note = "queued 7 days"
	chain.Emit("Decision", "id", strconv.FormatInt(d.ID, 10), "kind", kind, "state", "queued")
	return d
}

func atOnce(kind, text string, params any, made, t int64, note string) *decisions.Decision {
	d := ledger.Record(kind, text, params, made, t, t)
	ledger.Apply(d, t, "at once: "+note)
	chain.Emit("Decision", "id", strconv.FormatInt(d.ID, 10), "kind", kind, "state", "applied")
	return d
}

// ------------------------------------------------------------- launch --

// NewLaunchRequest is the launch's builder — the governor's decision like any other (M1k), the launch vote's once
// the governor has yielded: its execution makes the realms live, once, with the compiled values. It carries the
// 14-day deadline every builder carries: a passed launch nobody executed within 14 days of its proposal returns
// the deadline error (GovDAO denies it for good) and the launch is proposed again, so a forgotten vote is never a
// standing trap. A second execution errors.
func NewLaunchRequest(cur realm) Request {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	if live {
		panic("hlmailbox: launched already")
	}
	made := now()
	text := "launch: the compiled values go live — verifier " + launchVerifier + " for origin " + u32(launchOrigin) +
		", signers " + launchSigners + " under the rule " + Rule{Threshold: launchThreshold}.String() +
		", routes " + launchRouteGNOT + " and " + launchRouteBUBBLE + ", seats " + seatsText()
	cb := func(cur realm) error {
		mustBeGovernor(cur)
		t := now()
		if err := decisions.Expired(made, t); err != nil {
			return err
		}
		if live {
			return errors.New("hlmailbox: launched already")
		}
		live, launchedAt = true, t
		atOnce("launch", text, launchParams{}, made, t, "live")
		chain.Emit("Launch", "at", strconv.FormatInt(t, 10))
		return nil
	}
	return request(cur, "launch", text, cb)
}

func seatsText() string {
	parts := make([]string, 0, seatCount)
	for i := 1; i <= seatCount; i++ {
		parts = append(parts, strconv.Itoa(i)+":"+string(seats[i]))
	}
	return strings.Join(parts, ",")
}

// ------------------------------------------------------------- verifier --

// NewSetVerifierRequest activates a registered verifier for an origin, 7 days after the proposal executes.
func NewSetVerifierRequest(cur realm, origin uint32, path string) Request {
	mustBeLive()
	if origin == localDomain {
		panic("hlmailbox: this chain's own domain has no verifier")
	}
	if !verifiers.Has(path) {
		panic("hlmailbox: no verifier registered at " + path)
	}
	if ActiveVerifier(origin) == path {
		panic("hlmailbox: " + path + " is the active verifier for origin " + u32(origin) + " already")
	}
	text := "set verifier for origin " + u32(origin) + " to " + path
	return propose(cur, "set verifier", text, func(made, t int64) {
		mustBeLive()
		if !verifiers.Has(path) {
			panic("hlmailbox: no verifier registered at " + path)
		}
		queue("set verifier", text, setVerifierParams{origin, path}, made, t)
	})
}

// -------------------------------------------------------------- signers --

// parseSigners reads a signer set and its rule: keys in hex, comma separated; a threshold, or both groups (comma
// separated hex, subsets of the keys) with threshold 0.
func parseSigners(keys string, threshold int, groupA, groupB string) ([]Key, Rule) {
	ks := parseKeys(keys)
	if len(ks) == 0 {
		panic("hlmailbox: no signers")
	}
	a, b := parseKeys(groupA), parseKeys(groupB)
	if (len(a) == 0) != (len(b) == 0) {
		panic("hlmailbox: name both groups or neither")
	}
	if len(a) > 0 {
		if threshold != 0 {
			panic("hlmailbox: a two-group rule takes no threshold")
		}
		if !subset(a, ks) || !subset(b, ks) {
			panic("hlmailbox: every group member must be a signer")
		}
		for _, k := range a {
			if indexOf(b, k) >= 0 {
				panic("hlmailbox: a key in both groups: " + hx(k[:]))
			}
		}
		return ks, Rule{GroupA: a, GroupB: b}
	}
	if threshold < 1 || threshold > len(ks) {
		panic("hlmailbox: the threshold must be between 1 and the number of signers")
	}
	return ks, Rule{Threshold: threshold}
}

// pruned is the live rule with every key absent from ks dropped from both groups: what a pure removal leaves of
// the rule. A threshold is not pruned (§5.3: a 2-of-3 rule is still met by the 2 that remain after one removal);
// a group is (one of A and one of B is still met by the members that remain). Removing a partner — the only
// member of its group — leaves a group empty, which no proposal names, so that removal is never at once.
func pruned(ks []Key) Rule {
	r := Rule{Threshold: signerRule.Threshold}
	for _, k := range signerRule.GroupA {
		if indexOf(ks, k) >= 0 {
			r.GroupA = append(r.GroupA, k)
		}
	}
	for _, k := range signerRule.GroupB {
		if indexOf(ks, k) >= 0 {
			r.GroupB = append(r.GroupB, k)
		}
	}
	return r
}

// NewRotateSignersRequest sets the signer set and its rule together (§5.3): the keys in hex, comma separated, in
// the order signatures name them; a threshold, or §11.13's two groups (one of each must sign; threshold 0). It
// applies at once only as a pure removal — the new set a subset of the old, under the live rule pruned of the
// removed keys (the same threshold; the groups less the keys that leave), which the active verifier says the
// remaining set can still meet (Satisfiable, decided when the proposal executes); any other change, a lowered
// threshold among them, is queued 7 days, and a queued rotation applies only while the signer set and rule are
// still those it was decided against.
func NewRotateSignersRequest(cur realm, keys string, threshold int, groupA, groupB string) Request {
	mustBeLive()
	ks, rule := parseSigners(keys, threshold, groupA, groupB)
	if sameKeys(ks, signerKeys) && rule.equal(signerRule) {
		panic("hlmailbox: nothing changes")
	}
	// a pure removal is checked against the active verifier's Satisfiable when it is made too (K19): one that
	// would leave the rule unsatisfiable is nonsense, refused early — at execution the test is made again, and a
	// removal it fails then (another landed in between) is queued, never refused (§5.3)
	if rule.sameAs(pruned(ks)) && len(ks) < len(signerKeys) && subset(ks, signerKeys) && !satisfiable(ks) {
		panic("hlmailbox: the active verifier says the signers that remain cannot meet the rule: a removal never leaves the rule unsatisfiable")
	}
	text := "rotate signers to " + keysHex(ks) + " under the rule " + rule.String()
	return propose(cur, "rotate signers", text, func(made, t int64) {
		mustBeLive()
		p := rotateSignersParams{keys: ks, rule: rule}
		if rule.sameAs(pruned(ks)) && len(ks) < len(signerKeys) && subset(ks, signerKeys) && satisfiable(ks) {
			signerKeys, signerRule = ks, rule
			atOnce("rotate signers", text, p, made, t, "a removal the rule survives")
			chain.Emit("SignersSet", "count", strconv.Itoa(len(ks)), "rule", rule.String())
			return
		}
		p.oldKeys, p.oldRule = Signers()
		d := queue("rotate signers", text, p, made, t)
		d.Note += "; applies only while the signer set and rule stand as they do now"
	})
}

// ---------------------------------------------------------------- seats --

// parseSeatChanges reads "seat:address" pairs, comma separated; an empty address ("1:" or "1:-") vacates the seat.
func parseSeatChanges(changes string) ([]int, []address) {
	if strings.TrimSpace(changes) == "" {
		panic("hlmailbox: no changes")
	}
	var ns []int
	var as []address
	g := 0
	for _, p := range strings.Split(changes, ",") {
		i := strings.Index(p, ":")
		if i < 0 {
			panic("hlmailbox: a change is seat:address, not " + p)
		}
		n, err := strconv.Atoi(strings.TrimSpace(p[:i]))
		if err != nil || n < 1 || n > seatCount {
			panic("hlmailbox: the seat must be 1 to 6, not " + p[:i])
		}
		for _, x := range ns {
			if x == n {
				panic("hlmailbox: seat " + strconv.Itoa(n) + " named twice")
			}
		}
		a := address(strings.TrimSpace(p[i+1:]))
		if a == "-" {
			a = ""
		}
		if a != "" && !a.IsValid() {
			panic("hlmailbox: not an address: " + string(a))
		}
		if a == "" && seats[n] == "" {
			panic("hlmailbox: seat " + strconv.Itoa(n) + " is empty already")
		}
		if a != "" && seats[n] == a {
			panic("hlmailbox: seat " + strconv.Itoa(n) + " holds " + string(a) + " already")
		}
		if a != "" && SeatOf(a) != 0 {
			panic("hlmailbox: " + string(a) + " holds seat " + strconv.Itoa(SeatOf(a)) + " already")
		}
		for j, x := range as {
			if x != "" && x == a {
				panic("hlmailbox: " + string(a) + " named for seats " + strconv.Itoa(ns[j]) + " and " + strconv.Itoa(n))
			}
		}
		if IsGuardianSeat(n) {
			g++
		}
		ns = append(ns, n)
		as = append(as, a)
	}
	if g > 2 {
		panic("hlmailbox: two guardians at most per proposal")
	}
	return ns, as
}

func seatChangesText(ns []int, as []address) string {
	parts := make([]string, len(ns))
	for i, n := range ns {
		if as[i] == "" {
			parts[i] = "remove seat " + strconv.Itoa(n) + " (" + string(seats[n]) + ")"
		} else {
			parts[i] = "set seat " + strconv.Itoa(n) + " to " + string(as[i])
		}
	}
	return strings.Join(parts, ", ")
}

// NewRotateSeatsRequest replaces or vacates guardian and watch-key seats: changes is "seat:address" pairs, comma
// separated, an empty address vacating the seat; two guardians at most per proposal; a seat's current key is
// refused. Removals alone apply at once; any replacement queues the whole proposal 7 days, and a queued one
// applies only while the six seats still stand as they did when it was decided. A removed or replaced key's
// flags clear with it. A removal means the key the seat holds when the proposal is made (the description names
// it): a seat whose occupant changed by execution — a replacement landed in between — is skipped and the note says
// so (R21), the proposal spent if nothing was left to remove.
func NewRotateSeatsRequest(cur realm, changes string) Request {
	mustBeLive()
	ns, as := parseSeatChanges(changes)
	held := make([]address, len(ns))
	for i, n := range ns {
		held[i] = seats[n]
	}
	text := "rotate seats: " + seatChangesText(ns, as)
	return propose(cur, "rotate seats", text, func(made, t int64) {
		mustBeLive()
		p := rotateSeatsParams{seats: ns, addrs: as, held: held}
		removals := true
		for _, a := range as {
			if a != "" {
				removals = false
			}
		}
		if removals {
			vacated, skipped := applySeats(p, t)
			if len(vacated) == 0 {
				d := ledger.Record("rotate seats", text, p, made, t, t)
				ledger.Spend(d, "spent: nothing to remove, "+seatsNote(nil, skipped))
				chain.Emit("Decision", "id", strconv.FormatInt(d.ID, 10), "kind", "rotate seats", "state", "spent")
				return
			}
			atOnce("rotate seats", text, p, made, t, "removals: "+seatsNote(vacated, skipped))
			return
		}
		p.before = seats
		d := queue("rotate seats", text, p, made, t)
		d.Note += "; applies only while the seats stand as they do now"
	})
}

// applySeats makes a proposal's seat changes: a replacement as named; a removal only while the seat still holds the
// key the proposal was made against (R21). It reports the seats vacated and the removals skipped.
func applySeats(p rotateSeatsParams, t int64) (vacated, skipped []int) {
	for i, n := range p.seats {
		a := p.addrs[i]
		if a == "" {
			if seats[n] == "" || seats[n] != p.held[i] {
				skipped = append(skipped, n)
				continue
			}
			clearSeat(n, t)
			seats[n] = ""
			vacated = append(vacated, n)
			chain.Emit("SeatSet", "seat", strconv.Itoa(n), "address", "")
			continue
		}
		if SeatOf(a) != 0 && SeatOf(a) != n {
			panic("hlmailbox: " + string(a) + " holds seat " + strconv.Itoa(SeatOf(a)) + " now")
		}
		if seats[n] != "" {
			clearSeat(n, t)
		}
		seats[n] = a
		chain.Emit("SeatSet", "seat", strconv.Itoa(n), "address", string(a))
	}
	return vacated, skipped
}

// seatsNote says which seats a proposal vacated and which it skipped.
func seatsNote(vacated, skipped []int) string {
	var parts []string
	if len(vacated) > 0 {
		parts = append(parts, "seats "+seatList(vacated)+" vacated")
	}
	if len(skipped) > 0 {
		parts = append(parts, "seats "+seatList(skipped)+" skipped (the occupant changed since the proposal was made)")
	}
	return strings.Join(parts, ", ")
}

func seatList(ns []int) string {
	parts := make([]string, len(ns))
	for i, n := range ns {
		parts[i] = strconv.Itoa(n)
	}
	return strings.Join(parts, ",")
}

// -------------------------------------------------------------- unpause --

func parseFns(fns string) []string {
	var out []string
	for _, p := range strings.Split(fns, ",") {
		fn := strings.TrimSpace(p)
		if !isFn(fn) {
			panic("hlmailbox: the functions are sends, credits and payouts, not " + fn)
		}
		for _, x := range out {
			if x == fn {
				panic("hlmailbox: " + fn + " named twice")
			}
		}
		out = append(out, fn)
	}
	return out
}

// NewUnpauseRequest clears every seat's flag for the named functions of a route (sends, credits, payouts; comma
// separated), and may vacate one seat in the same stroke (removeSeat, 0 for none — one seat, so §5.3's cap of two
// guardians per proposal holds by construction; the void builder's unpause option, which takes a list, counts
// them). The seat's holder now is what the proposal means and is recorded with it: a seat whose occupant changed
// by execution — a replacement landed in between — is skipped, and the note says so (R17). It applies at once;
// the builder refuses one that would clear nothing now, and an executed one that finds nothing to clear is spent
// (recorded, no effect, no meter reset), never queued.
func NewUnpauseRequest(cur realm, routePath, fns string, removeSeat int) Request {
	mustBeLive()
	if !routes.Has(routePath) {
		panic("hlmailbox: no route " + routePath)
	}
	list := parseFns(fns)
	var removeAddr address
	if removeSeat != 0 {
		if removeSeat < 1 || removeSeat > seatCount {
			panic("hlmailbox: the seat must be 1 to 6")
		}
		if removeAddr = seats[removeSeat]; removeAddr == "" {
			panic("hlmailbox: seat " + strconv.Itoa(removeSeat) + " is empty")
		}
	}
	clears := false
	for _, fn := range list {
		if Paused(routePath, fn) {
			clears = true
		}
	}
	if !clears {
		panic("hlmailbox: no flag stands on " + fns + " of " + routePath + ": nothing to clear")
	}
	text := "unpause " + strings.Join(list, ",") + " on " + routePath
	if removeSeat != 0 {
		text += ", removing seat " + strconv.Itoa(removeSeat) + " (" + string(removeAddr) + ")"
	}
	return propose(cur, "unpause", text, func(made, t int64) {
		mustBeLive()
		p := unpauseParams{route: routePath, fns: list, removeSeat: removeSeat, removeAddr: removeAddr}
		n, payouts := clearFns(routePath, list, t)
		removed, skipped := false, false
		if removeSeat != 0 {
			if seats[removeSeat] == removeAddr {
				clearSeat(removeSeat, t)
				seats[removeSeat] = ""
				removed = true
				chain.Emit("SeatSet", "seat", strconv.Itoa(removeSeat), "address", "")
			} else {
				skipped = true
			}
		}
		seatNote := ""
		if removed {
			seatNote = ", seat " + strconv.Itoa(removeSeat) + " vacated"
		} else if skipped {
			seatNote = ", seat " + strconv.Itoa(removeSeat) + " skipped (its occupant changed since the proposal was made)"
		}
		if n == 0 && !removed {
			d := ledger.Record("unpause", text, p, made, t, t)
			ledger.Spend(d, "spent: nothing to clear"+seatNote)
			chain.Emit("Decision", "id", strconv.FormatInt(d.ID, 10), "kind", "unpause", "state", "spent")
			return
		}
		note := strconv.Itoa(n) + " flags cleared"
		if payouts {
			note += ", meters restart"
		}
		atOnce("unpause", text, p, made, t, note+seatNote)
	})
}

// --------------------------------------------------------------- cancel --

// NewCancelRequest cancels a queued decision of this realm, at once. It is the one builder proposed before Launch.
func NewCancelRequest(cur realm, id int64) Request {
	d := ledger.Get(id)
	if d == nil || !d.Pending() {
		panic("hlmailbox: decision " + strconv.FormatInt(id, 10) + " is not pending")
	}
	text := "cancel decision " + strconv.FormatInt(id, 10) + " (" + d.Text + ")"
	return propose(cur, "cancel", text, func(made, t int64) {
		if _, err := ledger.Cancel(id, t); err != nil {
			panic("hlmailbox: " + err.Error())
		}
		atOnce("cancel", text, cancelParams{id}, made, t, "cancelled")
	})
}

// -------------------------------------------------------------- execute --

// Execute applies a queued decision whose 7 days have passed. Anyone may call it; the relayers do. A queued
// rotation of signers or seats applies only while the set it was decided against still stands: one that finds
// the signers or the seats changed in between panics (it stays pending; GovDAO cancels it and proposes afresh).
func Execute(cur realm, id int64) {
	caller(cur)
	t := now()
	d, err := ledger.Due(id, t)
	if err != nil {
		panic("hlmailbox: " + err.Error())
	}
	note := "applied after the delay"
	switch p := d.Params.(type) {
	case setVerifierParams:
		if !verifiers.Has(p.path) {
			panic("hlmailbox: no verifier registered at " + p.path)
		}
		active.Set(domainKey(p.origin), p.path)
		chain.Emit("VerifierSet", "origin", u32(p.origin), "pkgpath", p.path)
	case rotateSignersParams:
		if !sameKeys(signerKeys, p.oldKeys) || !signerRule.equal(p.oldRule) {
			panic("hlmailbox: the signer set or rule changed since decision " + strconv.FormatInt(id, 10) + " was decided: cancel it and propose the rotation against the set as it stands")
		}
		signerKeys, signerRule = p.keys, p.rule
		chain.Emit("SignersSet", "count", strconv.Itoa(len(p.keys)), "rule", p.rule.String())
	case rotateSeatsParams:
		if p.before != seats {
			panic("hlmailbox: the seats changed since decision " + strconv.FormatInt(id, 10) + " was decided: cancel it and propose the change against the seats as they stand")
		}
		if _, skipped := applySeats(p, t); len(skipped) > 0 {
			note += "; " + seatsNote(nil, skipped)
		}
	default:
		panic("hlmailbox: decision " + strconv.FormatInt(id, 10) + " is not one that waits")
	}
	ledger.Apply(d, t, note)
	chain.Emit("Decision", "id", strconv.FormatInt(id, 10), "kind", d.Kind, "state", "applied")
}

// Package hlmailbox is the gno.land end of the bridge's message layer (bridge/PLAN.md §5.1): realms send messages to
// other chains through it and take the messages other chains send them from it. Messages, ids and the merkle tree
// are Hyperlane's byte for byte (gno.land/p/…/hyperlane/v0), so the Solana side runs Hyperlane's own programs.
//
// Out. Dispatch takes a message from the realm that calls it, numbers it, puts its id in the merkle tree, keeps the
// message, and emits the Dispatch event the Solana light client proves from LastResultsHash (§13: id, nonce, origin,
// destination, sender, recipient, hash). Reemit emits it again from a fresh block, by anyone.
//
// In. A recipient realm pulls its own messages: it calls Process with the message and the verifier's metadata;
// Process checks the caller is the recipient, that the message is for this chain and was never delivered, marks it
// delivered, and only then asks the active verifier — a realm that registered itself here, chosen by GovDAO by
// pkgpath — whether the message is genuine; a verifier's error is a panic, so the transaction and the mark revert
// together and a refused message stays deliverable.
//
// Who may change what. Nobody holds an admin key: every setting moves by a decision made with this realm's
// builders (gov.gno), at once or after 7 days (§5.3), and nothing but Launch and cancel before the one-shot
// Launch. Who decides is the governor's (M1k): the compiled launchGovernor alone, by its own call through Govern,
// until it yields (Yield, once, for every bridge realm at once), and GovDAO's proposals from then on — or from the
// first block, when no governor was compiled. The guardians and watch keys (flags.gno) can only pause: three flags
// per key per route — sends, credits, payouts — which the routes ask about with Paused. Every launch value is
// compiled in below and written by init.
package hlmailbox

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	hl "gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hyperlane/v0"
)

const (
	namespace = "gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/"
	pkgPath   = namespace + "hlmailbox" // must match gnomod.toml

	// DomainMainnet and DomainTest are gno.land's Hyperlane domain ids, "GnoL" and "GnoT" in ASCII; nobody in the
	// Hyperlane registry holds either (2026-10-10). gnoland-1 is mainnet; every other chain is a test chain.
	DomainMainnet  = uint32(1198419788)
	DomainTest     = uint32(1198419796)
	mainnetChainID = "gnoland-1"

	// SolanaMainnet and SolanaLocal are the destination's domains: Solana's own on mainnet; on any other gno chain
	// the one the local test validator and the e2e run use (Hyperlane's "solanatestnet"). Devnet is 1399811151.
	SolanaMainnet = uint32(1399811149)
	SolanaLocal   = uint32(1399811150)

	// The launch values (§5.3): the active verifier, the signers and their rule, the routes. The signer keys below
	// are PLACEHOLDERS (the three test signers of the vectors) until the operator's three machines exist; the
	// launch vote reads the real ones in the deployed source. bridge/local/e2e.sh swaps them for its run's keys.
	launchVerifier  = namespace + "hlverifier"
	launchThreshold = 2
	launchSigners   = "e2c2b621677535e5b2a0a92f37aec61e7ce0397cf1cf713f91a18227eafec2ef,d837b6369a315b6d26babddc0af241d8908a1809481b29e98365965cf8301689,c0b2dc0da05eb6ee67b68068611a72858f3093c79e8d90589ff2ac1f0ea4da26"
	launchRouteGNOT   = namespace + "hlgnot"
	launchRouteBUBBLE = namespace + "hlbubble"
	hlgovPath         = namespace + "hlgov" // r/hlgov: the one realm that notes a route's enrolment on Solana (NoteEnrolled, AR1)

	maxSigners = 255 // a signature names its signer in one byte
)

// launchGovernor is the governor (M1k, §5.3): the one address whose own direct call decides — through Govern, the
// same closures, checks, queues and delays a GovDAO proposal's execution runs — until it yields (Yield), from
// which block GovDAO's proposals decide and nothing else; "" means GovDAO from the first block. Every bridge
// realm compiles the same address and refuses to deploy with another (its init reads Governor here), and reads
// Yielded here, so no realm is ever governed apart from the rest. A PLACEHOLDER (testutils.TestAddress("hl-
// governor")) until the launch notice names the real key; bridge/local/e2e.sh swaps it for gnodev's test1 in all
// six realms. Its own line, so one sed on `^const launchGovernor = address(…)` finds it in every realm.
const launchGovernor = address("g1ecsuj0q572jr0dhu29q9njtnmw03hyu7tyyvv6")

var (
	localDomain  = domainOf(runtime.ChainID())
	launchOrigin = solanaOf(runtime.ChainID())
	// hook is this realm's address as Hyperlane carries it: the merkle tree hook id inside every checkpoint signed
	// for a message from here.
	hook = mustBytes32(chain.PackageAddress(pkgPath))

	tree hl.Tree
	sent avl.Tree // nonceKey(nonce) → *sentMsg
	done avl.Tree // message id in hex → the block height it was delivered at

	verifiers avl.Tree // pkgpath → Verifier, every realm that registered
	active    avl.Tree // domainKey(origin) → the pkgpath of the verifier GovDAO chose for that origin

	signerKeys []Key // the one signer set, in the order signatures name them
	signerRule Rule

	live       bool  // after the Launch decision executed
	launchedAt int64 // unix time it did

	yielded int64 // the block height the governor yielded at (Yield); 0 until then — every bridge realm reads it

	ledger decisions.Ledger
)

// sentMsg is one dispatched message and the checkpoint it made.
type sentMsg struct {
	raw    string   // the message as it went out
	root   [32]byte // the tree's root right after its id went in, at index = its nonce
	height int64
}

// Key is a signer's ed25519 public key.
type Key [32]byte

// Rule is how many signers must sign: Threshold of the set, or — when both groups are named (§11.13) — one key of
// GroupA and one of GroupB. The verifier applies it; Satisfiable says whether a set can still meet it.
type Rule struct {
	Threshold int
	GroupA    []Key
	GroupB    []Key
}

// TwoGroups is whether the rule is "one of A and one of B" rather than a threshold.
func (r Rule) TwoGroups() bool { return len(r.GroupA) > 0 && len(r.GroupB) > 0 }

// String says the rule in words.
func (r Rule) String() string {
	if r.TwoGroups() {
		return "one of group A (" + keysHex(r.GroupA) + ") and one of group B (" + keysHex(r.GroupB) + ")"
	}
	return strconv.Itoa(r.Threshold) + " of the set"
}

func (r Rule) equal(o Rule) bool {
	return r.Threshold == o.Threshold && sameKeys(r.GroupA, o.GroupA) && sameKeys(r.GroupB, o.GroupB)
}

// sameAs is whether two rules are the same rule, the groups compared as sets.
func (r Rule) sameAs(o Rule) bool {
	return r.Threshold == o.Threshold && sameSet(r.GroupA, o.GroupA) && sameSet(r.GroupB, o.GroupB)
}

// Verifier decides whether an incoming message is genuine (§5.1). A verifier is a realm; it registers once with
// RegisterVerifier and GovDAO activates it by pkgpath. Both methods are non-crossing. An implementation is a type
// declared in the registering realm: its methods then run under that realm's authority (borrow rule #1) and can
// write nothing of this realm's. A type declared in /p/ with no object to anchor on (`type V int`) would run under
// this realm's own authority instead — the no-anchor case — which RegisterVerifier cannot tell apart, so GovDAO
// activates a verifier whose source it has read; what the mailbox hands a verifier is the recipient's bytes
// (Verify) or a copy of its own keys (Satisfiable), never a value it keeps.
type Verifier interface {
	Verify(origin uint32, metadata, message []byte) error
	Satisfiable(signers []Key) bool
}

func domainOf(chainID string) uint32 {
	if chainID == mainnetChainID {
		return DomainMainnet
	}
	return DomainTest
}

func solanaOf(chainID string) uint32 {
	if chainID == mainnetChainID {
		return SolanaMainnet
	}
	return SolanaLocal
}

func mustBytes32(a address) [32]byte {
	b, err := hl.AddressToBytes32(a)
	if err != nil {
		panic(err.Error())
	}
	return b
}

func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	return cur.Previous().Address()
}

func u32(n uint32) string { return strconv.FormatUint(uint64(n), 10) }

func hx(b []byte) string { return hex.EncodeToString(b) }

func keysHex(ks []Key) string {
	s := make([]string, len(ks))
	for i, k := range ks {
		s[i] = hx(k[:])
	}
	return strings.Join(s, ",")
}

// nonceKey sorts nonces by number.
func nonceKey(n uint32) string {
	s := u32(n)
	return strings.Repeat("0", 10-len(s)) + s
}

func domainKey(d uint32) string { return nonceKey(d) }

func init() {
	signerKeys = parseKeys(launchSigners)
	signerRule = Rule{Threshold: launchThreshold}
	active.Set(domainKey(launchOrigin), launchVerifier)
	initSeats()
	routes.Set(launchRouteGNOT, &routeRec{})
	routes.Set(launchRouteBUBBLE, &routeRec{})
}

// ------------------------------------------------------------- reading --

// LocalDomain is this chain's Hyperlane domain id.
func LocalDomain() uint32 { return localDomain }

// LaunchOrigin is the Solana domain the launch values name.
func LaunchOrigin() uint32 { return launchOrigin }

// Address is this realm's address.
func Address() address { return chain.PackageAddress(pkgPath) }

// Hook is this mailbox's merkle tree hook id in hex: the 32 bytes every checkpoint for a message from here names.
func Hook() string { return hx(hook[:]) }

// Count is how many messages went out: the next message's nonce.
func Count() uint32 { return tree.Count }

// Root is the merkle tree's root now, in hex.
func Root() string {
	r := tree.Root()
	return hx(r[:])
}

// Live is whether the Launch decision has executed: before it the routes refuse sends and credits.
func Live() bool { return live }

// LaunchedAt is the unix time the Launch decision executed, 0 before: the routes' meters start empty there.
func LaunchedAt() int64 { return launchedAt }

// Governor is the compiled governor (M1k): the address whose own call decides until it yields; "" when GovDAO
// governs from the first block. Every other bridge realm compiles the same and checks it here at deploy.
func Governor() address { return launchGovernor }

// Yielded is the block height the governor yielded at (Yield), 0 until then: what every bridge realm reads before
// it accepts a decision — the governor's own call before, GovDAO's proxy after (decisions.DAOGoverns).
func Yielded() int64 { return yielded }

// Message is the message dispatched with this nonce, in hex, and the tree's root right after it ("", "" if none).
func Message(nonce uint32) (message, root string) {
	v := sent.Get(nonceKey(nonce))
	if v == nil {
		return "", ""
	}
	s := v.(*sentMsg)
	return hx([]byte(s.raw)), hx(s.root[:])
}

// Delivered is the block height a message (by id, in hex) was delivered at here; 0 if it never was.
func Delivered(id string) int64 {
	v := done.Get(cleanID(id))
	if v == nil {
		return 0
	}
	return v.(int64)
}

func cleanID(id string) string { return strings.TrimPrefix(strings.ToLower(strings.TrimSpace(id)), "0x") }

// Signers is the signer set and its rule: copies, so a verifier can read them and nobody can change them.
func Signers() ([]Key, Rule) {
	ks := append([]Key(nil), signerKeys...)
	r := Rule{Threshold: signerRule.Threshold, GroupA: append([]Key(nil), signerRule.GroupA...), GroupB: append([]Key(nil), signerRule.GroupB...)}
	return ks, r
}

// SignerKeys is the signer set in hex, comma separated, in the order signatures name them.
func SignerKeys() string { return keysHex(signerKeys) }

// ActiveVerifier is the pkgpath of the verifier GovDAO chose for an origin ("" if none).
func ActiveVerifier(origin uint32) string {
	v := active.Get(domainKey(origin))
	if v == nil {
		return ""
	}
	return v.(string)
}

// VerifierRegistered is whether a realm at this pkgpath registered as a verifier.
func VerifierRegistered(path string) bool { return verifiers.Has(path) }

// --------------------------------------------------------------- keys --

func parseKey(s string) Key {
	p := strings.TrimPrefix(strings.ToLower(strings.TrimSpace(s)), "0x")
	b, err := hex.DecodeString(p)
	if err != nil || len(b) != 32 {
		panic("hlmailbox: not a 32-byte ed25519 key in hex: " + p)
	}
	var k Key
	copy(k[:], b)
	return k
}

// parseKeys reads comma-separated keys in hex, refusing a key named twice.
func parseKeys(s string) []Key {
	if strings.TrimSpace(s) == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	if len(parts) > maxSigners {
		panic("hlmailbox: more than 255 keys")
	}
	ks := make([]Key, 0, len(parts))
	for _, p := range parts {
		k := parseKey(p)
		if indexOf(ks, k) >= 0 {
			panic("hlmailbox: a key named twice: " + hx(k[:]))
		}
		ks = append(ks, k)
	}
	return ks
}

func indexOf(ks []Key, k Key) int {
	for i, x := range ks {
		if x == k {
			return i
		}
	}
	return -1
}

// sameKeys is whether two lists hold the same keys in the same order.
func sameKeys(a, b []Key) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// subset is whether every key of a is in b.
func subset(a, b []Key) bool {
	for _, k := range a {
		if indexOf(b, k) < 0 {
			return false
		}
	}
	return true
}

// sameSet is whether two lists hold the same keys, in any order (a list never names a key twice).
func sameSet(a, b []Key) bool { return len(a) == len(b) && subset(a, b) && subset(b, a) }

// ----------------------------------------------------------- verifiers --

// RegisterVerifier is how a verifier realm offers itself: called once from that realm (its init, usually), it is
// kept under the caller's pkgpath, which GovDAO names to activate it. Only an /r/ realm may register, and once;
// a sub-realm identity (`cur.Sub(…)`, a token a realm mints for free, whose pkgpath `host#subpath` passes the
// prefix test) is refused, so every entry costs a package deployment and the listing (bounded; render.gno)
// cannot be flooded. Nothing is ever unregistered.
func RegisterVerifier(cur realm, v Verifier) {
	if !cur.IsCurrent() {
		panic("hlmailbox: that realm value is not live; pass your own cur")
	}
	path := cur.Previous().PkgPath()
	if !strings.HasPrefix(path, "gno.land/r/") {
		panic("hlmailbox: only a realm under gno.land/r/ registers a verifier, not " + path)
	}
	if cur.Previous().Subpath() != "" {
		panic("hlmailbox: a realm registers with its own cur, not a sub-identity (" + path + ")")
	}
	if v == nil {
		panic("hlmailbox: a nil verifier")
	}
	if verifiers.Has(path) {
		panic("hlmailbox: " + path + " registered already")
	}
	verifiers.Set(path, v)
	chain.Emit("VerifierRegistered", "pkgpath", path)
}

// satisfiable asks every active verifier whether the signer set ks can still meet the rule; an active verifier
// that is not registered answers no. Each verifier is handed its own copy of ks: the builders store ks after
// asking, and a verifier that runs under this realm's authority (the no-anchor case, see Verifier) must find
// nothing of the mailbox's to write into.
func satisfiable(ks []Key) bool {
	ok := true
	active.Iterate("", "", func(_ string, v any) bool {
		path := v.(string)
		r := verifiers.Get(path)
		if r == nil || !r.(Verifier).Satisfiable(append([]Key(nil), ks...)) {
			ok = false
			return true
		}
		return false
	})
	return ok
}

// ---------------------------------------------------------------- out --

// Dispatch sends body to recipient on destination, from whoever calls it — a realm, usually — and returns the
// message's id. The sender is the caller's address as Hyperlane carries one; the nonce is the message's index in
// the merkle tree. The event is §13's: id, nonce, origin, destination, sender, recipient, hash.
func Dispatch(cur realm, destination uint32, recipient [32]byte, body []byte) [32]byte {
	sender := mustBytes32(caller(cur))
	// a successor a re-point dropped is a route no more (R35): Solana's token may still name it the router until
	// the next kind 6, so a message from it would mint against a lock no realm of the line holds
	if path := cur.Previous().PkgPath(); path != "" {
		if by := Dropped(path); by != "" {
			panic("hlmailbox: " + path + " is a route no more (its predecessor " + by + " re-pointed the migration to another successor): it sends nothing")
		}
	}
	m := hl.Message{
		Version:     hl.Version,
		Nonce:       tree.Count,
		Origin:      localDomain,
		Sender:      sender,
		Destination: destination,
		Recipient:   recipient,
		Body:        body,
	}
	raw := m.Bytes()
	id := hl.ID(raw)
	tree.Insert(id)
	root := tree.Root()
	sent.Set(nonceKey(m.Nonce), &sentMsg{raw: string(raw), root: root, height: runtime.ChainHeight()})
	emitDispatch(m, raw, id)
	return id
}

func emitDispatch(m hl.Message, raw []byte, id [32]byte) {
	h := sha256.Sum256(raw)
	chain.Emit("Dispatch",
		"id", hx(id[:]),
		"nonce", u32(m.Nonce),
		"origin", u32(m.Origin),
		"destination", u32(m.Destination),
		"sender", hx(m.Sender[:]),
		"recipient", hx(m.Recipient[:]),
		"hash", hx(h[:]),
	)
}

// Reemit emits the Dispatch event of a message dispatched earlier again, in this block, by anyone: a message
// dispatched before a validator-set change, or whose results leaf is bigger than the ISM accepts, is then delivered
// from a fresh header. The id is unchanged, so the other side's processed-message record still refuses a second
// delivery.
func Reemit(cur realm, nonce uint32) {
	caller(cur)
	v := sent.Get(nonceKey(nonce))
	if v == nil {
		panic("hlmailbox: no message with nonce " + u32(nonce))
	}
	raw := []byte(v.(*sentMsg).raw)
	m, err := hl.ParseMessage(raw)
	if err != nil {
		panic(err.Error())
	}
	emitDispatch(m, raw, hl.ID(raw))
}

// ----------------------------------------------------------------- in --

// Process takes a message from another chain for the caller, who must be its recipient — or a route that
// succeeds the recipient along the chain of migrations (AQ1: a burn addressed to a migrated route is the
// successor's to credit, once its last page is in; the route decides when), a successor a re-point dropped from
// that chain counted as a hop of its predecessor's (R35: the line's last realm takes what is addressed to it; the
// dropped realm itself, a route no more, is refused). metadata is whatever the origin's active verifier needs
// (the signers' checkpoint and signatures, for the ed25519 one). The message must be for this chain and never
// delivered; it is marked delivered, then the verifier is asked, and a verifier's error is a panic, so the whole
// transaction reverts with the mark and the message stays deliverable (§5.1). It is then handed back for the
// recipient to act on.
func Process(cur realm, metadata, message []byte) (origin uint32, sender [32]byte, body []byte) {
	who := caller(cur)
	callerPath := cur.Previous().PkgPath()
	if by := Dropped(callerPath); by != "" {
		panic("hlmailbox: " + callerPath + " is a route no more (its predecessor " + by + " re-pointed the migration to another successor): the line's last realm takes this message")
	}
	m, err := hl.ParseMessage(message)
	if err != nil {
		panic(err.Error())
	}
	if m.Version != hl.Version {
		panic("hlmailbox: message version " + strconv.Itoa(int(m.Version)) + ", not " + strconv.Itoa(hl.Version))
	}
	if m.Destination != localDomain {
		panic("hlmailbox: the message is for domain " + u32(m.Destination) + ", not this one (" + u32(localDomain) + ")")
	}
	if mustBytes32(who) != m.Recipient && !successorOf(callerPath, m.Recipient) {
		panic("hlmailbox: only the message's recipient, or a successor of it, can take it")
	}
	idb := hl.ID(message)
	id := hx(idb[:])
	if done.Has(id) {
		panic("hlmailbox: already delivered")
	}
	path := active.Get(domainKey(m.Origin))
	if path == nil {
		panic("hlmailbox: no verifier for domain " + u32(m.Origin))
	}
	v := verifiers.Get(path.(string))
	if v == nil {
		panic("hlmailbox: the active verifier " + path.(string) + " is not registered")
	}
	done.Set(id, runtime.ChainHeight())
	if err := v.(Verifier).Verify(m.Origin, metadata, message); err != nil {
		panic(err.Error())
	}
	chain.Emit("Process",
		"origin", u32(m.Origin),
		"nonce", u32(m.Nonce),
		"id", id,
		"sender", hx(m.Sender[:]),
		"recipient", hx(m.Recipient[:]),
	)
	return m.Origin, m.Sender, m.Body
}

// MarkDone marks a message id delivered without a message: a route's credit-by-vote (§5.3) does it, so the id
// can never be credited twice. Only a registered route may call it, and only for an id not done.
func MarkDone(cur realm, id string) {
	mustBeRoute(cur)
	id = cleanID(id)
	if b, err := hex.DecodeString(id); err != nil || len(b) != 32 {
		panic("hlmailbox: not a 32-byte message id in hex: " + id)
	}
	if done.Has(id) {
		panic("hlmailbox: already delivered")
	}
	done.Set(id, runtime.ChainHeight())
}

package hlmailbox

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	hl "gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hyperlane/v0"
)

const (
	pageMax      = 20 // messages a "msgs/" page holds
	verifiersMax = 20 // registered verifier paths (and announced successors) the page and "json" name, and a "verifiers/" ("successors/") page holds
)

// Render:
//
//	""                  the mailbox's page: the launch values live or waiting, verifiers, signers, seats, flags
//	"decisions"         the decisions page: the last 100 pending and executed per kind
//	"json"              domain, hook, count, root, live, signers, verifiers (the first 20 registered paths and the
//	                    count), seats, flags, routes (each with its predecessor and successor, and the height and
//	                    time of the kind 6 that enrolled it on Solana: enrolled, enrolledAt), successors (the
//	                    first 20 announced paths, the count, and successorRoutes: the route each announced for),
//	                    for the agents
//	"decisions.json"    every decision, as a JSON array
//	"msg/<nonce>"       one dispatched message: {"nonce","id","root","height","message"}; "null" if none
//	"msgs/<from>"       up to 20 messages from nonce <from> on, as a JSON array
//	"verifiers/<from>"  up to 20 registered verifier paths from offset <from> on, in path order, as a JSON array
//	"successors/<from>" up to 20 announced successor paths from offset <from> on, in path order, as a JSON array
//	"delivered/<id>"    the block height a message id (hex) was delivered at here, 0 if never
func Render(path string) string {
	switch {
	case path == "":
		return page()
	case path == "decisions":
		return "# Decisions\n\n" + ledger.Page()
	case path == "json":
		return summaryJSON()
	case path == "decisions.json":
		return ledger.JSON()
	case strings.HasPrefix(path, "msg/"):
		n, ok := parseNonce(path[len("msg/"):])
		if !ok {
			return "null"
		}
		return msgJSON(n)
	case strings.HasPrefix(path, "msgs/"):
		from, ok := parseNonce(path[len("msgs/"):])
		if !ok {
			return "[]"
		}
		var b strings.Builder
		b.WriteString("[")
		for i := uint32(0); i < pageMax && uint64(from)+uint64(i) < uint64(tree.Count); i++ {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(msgJSON(from + i))
		}
		b.WriteString("]")
		return b.String()
	case strings.HasPrefix(path, "verifiers/"):
		from, ok := parseNonce(path[len("verifiers/"):])
		if !ok {
			return "[]"
		}
		return pathsJSON(&verifiers, int(from))
	case strings.HasPrefix(path, "successors/"):
		from, ok := parseNonce(path[len("successors/"):])
		if !ok {
			return "[]"
		}
		return pathsJSON(&successors, int(from))
	case strings.HasPrefix(path, "delivered/"):
		return strconv.FormatInt(Delivered(path[len("delivered/"):]), 10)
	}
	return "unknown path; see the mailbox's page"
}

func parseNonce(s string) (uint32, bool) {
	n, err := strconv.ParseUint(s, 10, 32)
	return uint32(n), err == nil
}

func q(s string) string { return strconv.Quote(s) }

func msgJSON(n uint32) string {
	v := sent.Get(nonceKey(n))
	if v == nil {
		return "null"
	}
	s := v.(*sentMsg)
	id := hl.ID([]byte(s.raw))
	return "{\"nonce\":" + u32(n) + ",\"id\":" + q(hx(id[:])) + ",\"root\":" + q(hx(s.root[:])) +
		",\"height\":" + strconv.FormatInt(s.height, 10) + ",\"message\":" + q(hx([]byte(s.raw))) + "}"
}

func keysJSON(ks []Key) string {
	parts := make([]string, len(ks))
	for i, k := range ks {
		parts[i] = q(hx(k[:]))
	}
	return "[" + strings.Join(parts, ",") + "]"
}

// pathsJSON is up to verifiersMax keys of a tree of pkgpaths (the registered verifiers, the announced successors)
// from offset from on, in path order: the listing is bounded whatever the count, since nothing is ever removed.
func pathsJSON(t *avl.Tree, from int) string {
	var b strings.Builder
	b.WriteString("[")
	first := true
	t.IterateByOffset(from, verifiersMax, func(k string, _ any) bool {
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(q(k))
		return false
	})
	b.WriteString("]")
	return b.String()
}

// pathsLine is a tree of pkgpaths on the page: the first verifiersMax in path order and, past them, where the rest
// are (page is the Render path that pages them); "none" for an empty tree.
func pathsLine(t *avl.Tree, page string) string {
	n := t.Size()
	if n == 0 {
		return "none"
	}
	var b strings.Builder
	i := 0
	t.IterateByOffset(0, verifiersMax, func(k string, _ any) bool {
		if i > 0 {
			b.WriteString(", ")
		}
		i++
		b.WriteString("`" + k + "`")
		return false
	})
	if n > verifiersMax {
		m := strconv.Itoa(verifiersMax)
		b.WriteString(", … (the first " + m + "; the rest at [" + page + "/" + m + "](" + pkgPathLink() + ":" + page + "/" + m + "))")
	}
	return b.String()
}

func summaryJSON() string {
	var b strings.Builder
	b.WriteString("{\"domain\":" + u32(localDomain) + ",\"hook\":" + q(Hook()) + ",\"address\":" + q(string(Address())) +
		",\"count\":" + u32(tree.Count) + ",\"root\":" + q(Root()) + ",\"delivered\":" + strconv.Itoa(done.Size()) +
		",\"live\":" + strconv.FormatBool(live) + ",\"launchedAt\":" + strconv.FormatInt(launchedAt, 10) +
		"," + decisions.GovernorJSON(launchGovernor, yielded) +
		",\"launchOrigin\":" + u32(launchOrigin) + ",\"clocks\":" + decisions.ClocksJSON() + ",\"decisions\":" + strconv.FormatInt(ledger.Last(), 10) +
		",\"signers\":{\"keys\":" + keysJSON(signerKeys) + ",\"threshold\":" + strconv.Itoa(signerRule.Threshold) +
		",\"groupA\":" + keysJSON(signerRule.GroupA) + ",\"groupB\":" + keysJSON(signerRule.GroupB) + "}" +
		",\"verifiers\":{")
	first := true
	active.Iterate("", "", func(k string, v any) bool {
		origin, _ := strconv.ParseUint(k, 10, 32)
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(q(strconv.FormatUint(origin, 10)) + ":{\"pkgpath\":" + q(v.(string)) + ",\"registered\":" + strconv.FormatBool(verifiers.Has(v.(string))) + "}")
		return false
	})
	b.WriteString("},\"registered\":" + pathsJSON(&verifiers, 0) + ",\"registeredCount\":" + strconv.Itoa(verifiers.Size()) + ",\"seats\":[")
	for i := 1; i <= seatCount; i++ {
		if i > 1 {
			b.WriteString(",")
		}
		b.WriteString(q(string(seats[i])))
	}
	b.WriteString("],\"routes\":{")
	first = true
	routes.Iterate("", "", func(k string, v any) bool {
		r := v.(*routeRec)
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(q(k) + ":{\"epoch\":" + strconv.FormatInt(r.epoch, 10) + ",\"epochAt\":" + strconv.FormatInt(r.epochAt, 10) +
			",\"sends\":" + strconv.FormatBool(Paused(k, FnSends)) + ",\"credits\":" + strconv.FormatBool(Paused(k, FnCredits)) +
			",\"payouts\":" + strconv.FormatBool(Paused(k, FnPayouts)) + ",\"flags\":[")
		for i, f := range Flags(k) {
			if i > 0 {
				b.WriteString(",")
			}
			b.WriteString(q(f))
		}
		b.WriteString("],\"predecessor\":" + q(r.predecessor) + ",\"successor\":" + q(r.successor) +
			",\"enrolled\":" + strconv.FormatInt(r.enrolled, 10) + ",\"enrolledAt\":" + strconv.FormatInt(r.enrolledAt, 10) +
			",\"pulled\":" + strconv.FormatBool(r.pulled) + ",\"dropped\":" + quotedJSON(r.dropped) + "}")
		return false
	})
	b.WriteString("},\"droppedRoutes\":" + droppedRoutesJSON() + ",\"successors\":" + pathsJSON(&successors, 0) + ",\"successorCount\":" + strconv.Itoa(successors.Size()) + ",\"successorRoutes\":" + successorRoutesJSON() + "}")
	return b.String()
}

// quotedJSON is a list of strings as a JSON array.
func quotedJSON(ss []string) string {
	parts := make([]string, len(ss))
	for i, s := range ss {
		parts[i] = q(s)
	}
	return "[" + strings.Join(parts, ",") + "]"
}

// droppedRoutesJSON is every dropped successor (R35) with the predecessor whose re-point dropped it, as an object
// of pkgpath → pkgpath: the tombstones, bounded by the migrations a bridge sees in its life.
func droppedRoutesJSON() string {
	var b strings.Builder
	b.WriteString("{")
	first := true
	droppedRoutes.Iterate("", "", func(k string, v any) bool {
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(q(k) + ":" + q(v.(string)))
		return false
	})
	b.WriteString("}")
	return b.String()
}

// droppedLine is the dropped successors on the page, each with the predecessor that re-pointed away from it; ""
// when none.
func droppedLine() string {
	if droppedRoutes.Size() == 0 {
		return ""
	}
	var parts []string
	droppedRoutes.Iterate("", "", func(k string, v any) bool {
		parts = append(parts, "`"+k+"` (by `"+v.(string)+"`)")
		return false
	})
	return "- dropped (routes no more, re-pointed away): " + strings.Join(parts, ", ") + "\n"
}

// successorRoutesJSON is the first verifiersMax announced successors with the route each announced for (AQ5), as
// an object of pkgpath → "GNOT" or "BUBBLE".
func successorRoutesJSON() string {
	var b strings.Builder
	b.WriteString("{")
	first := true
	successors.IterateByOffset(0, verifiersMax, func(k string, v any) bool {
		if !first {
			b.WriteString(",")
		}
		first = false
		b.WriteString(q(k) + ":" + q(v.(string)))
		return false
	})
	b.WriteString("}")
	return b.String()
}

// successorsLine is the announced successors on the page, each with the route it announced for (AQ5): the first
// verifiersMax in path order and, past them, where the rest are; "none" for an empty tree.
func successorsLine() string {
	n := successors.Size()
	if n == 0 {
		return "none"
	}
	var b strings.Builder
	i := 0
	successors.IterateByOffset(0, verifiersMax, func(k string, v any) bool {
		if i > 0 {
			b.WriteString(", ")
		}
		i++
		b.WriteString("`" + k + "` (" + v.(string) + ")")
		return false
	})
	if n > verifiersMax {
		m := strconv.Itoa(verifiersMax)
		b.WriteString(", … (the first " + m + "; the rest at [successors/" + m + "](" + pkgPathLink() + ":successors/" + m + "))")
	}
	return b.String()
}

func page() string {
	var b strings.Builder
	b.WriteString("# The bridge's mailbox\n\n")
	b.WriteString("gno.land's end of the GNOT and BUBBLE bridge to Solana: messages out to Solana (the Dispatch event the light client proves), and in from it under the active verifier. Every setting here moves only by a decision made with this realm's builders — the governor's own until it yields, a GovDAO proposal after; the guardians and watch keys can only pause.\n\n")
	if live {
		b.WriteString("- **live** since " + strconv.FormatInt(launchedAt, 10) + " (the Launch decision executed)\n")
	} else {
		b.WriteString("- **not launched**: the values below are the compiled launch values, waiting for the Launch decision; the routes refuse sends and credits. A passed Launch executes within 14 days of its proposal, like every decision; one nobody executed by then lapses and is proposed again\n")
	}
	b.WriteString("- " + decisions.GovernorLine(launchGovernor, yielded) + "\n")
	b.WriteString("- a proposal made with a builder (of this realm, a route, r/hlfees or r/hlgov) is executed with r/gov/dao's `ExecuteOrRejectProposal`: the one error a closure returns — the 14-day deadline — then denies it for good; under `ExecuteProposal` that error reverts the transaction instead and the proposal stands, every retry failing the same way. Anything else a closure refuses is a panic, which leaves the proposal for a retry under either call\n")
	b.WriteString("- domain: " + u32(localDomain) + "; Solana: " + u32(launchOrigin) + "\n")
	b.WriteString("- " + decisions.Clocks() + "\n")
	b.WriteString("- merkle tree hook: `" + Hook() + "`\n")
	b.WriteString("- messages out: " + u32(tree.Count) + ", root `" + Root() + "`; in: " + strconv.Itoa(done.Size()) + "\n")
	b.WriteString("- decisions: " + strconv.FormatInt(ledger.Last(), 10) + " ([page](" + pkgPathLink() + ":decisions))\n")
	b.WriteString("\n## Verifiers\n\n")
	active.Iterate("", "", func(k string, v any) bool {
		origin, _ := strconv.ParseUint(k, 10, 32)
		note := ""
		if !verifiers.Has(v.(string)) {
			note = " (**not registered**: nothing from this origin is taken until it is)"
		}
		b.WriteString("- from " + strconv.FormatUint(origin, 10) + ": `" + v.(string) + "`" + note + "\n")
		return false
	})
	b.WriteString("- registered (" + strconv.Itoa(verifiers.Size()) + "): " + pathsLine(&verifiers, "verifiers"))
	b.WriteString("\n\n## Signers\n\n- rule: " + signerRule.String() + "\n")
	for i, k := range signerKeys {
		b.WriteString("- " + strconv.Itoa(i) + ": `" + hx(k[:]) + "`\n")
	}
	b.WriteString("\n## Seats\n\n")
	for i := 1; i <= seatCount; i++ {
		kind := "guardian"
		if !IsGuardianSeat(i) {
			kind = "watch key"
		}
		a := string(seats[i])
		if a == "" {
			a = "(empty)"
		}
		b.WriteString("- seat " + strconv.Itoa(i) + " (" + kind + "): " + a + "\n")
	}
	b.WriteString("\n## Routes and flags\n\n")
	routes.Iterate("", "", func(k string, v any) bool {
		r := v.(*routeRec)
		b.WriteString("- `" + k + "`: payouts epoch " + strconv.FormatInt(r.epoch, 10))
		if r.predecessor != "" {
			b.WriteString(", successor of `" + r.predecessor + "`")
		}
		if r.pulled {
			b.WriteString(", page 0 pulled")
		}
		if r.successor != "" {
			b.WriteString(", migrated to `" + r.successor + "`")
		}
		if len(r.dropped) > 0 {
			b.WriteString(", dropped `" + strings.Join(r.dropped, "`, `") + "`")
		}
		if r.enrolled != 0 {
			b.WriteString(", enrolled on Solana by kind 6 at height " + strconv.FormatInt(r.enrolled, 10) + " (" + strconv.FormatInt(r.enrolledAt, 10) + ")")
		}
		fs := Flags(k)
		if len(fs) == 0 {
			b.WriteString(", no flag\n")
		} else {
			b.WriteString("\n")
			for _, f := range fs {
				b.WriteString("  - **paused** " + f + "\n")
			}
		}
		return false
	})
	b.WriteString(droppedLine())
	b.WriteString("- successors announced (" + strconv.Itoa(successors.Size()) + "): " + successorsLine() + " (a route's migrate names only one of them, announced for its own route)\n")
	if tree.Count > 0 {
		b.WriteString("\n## Latest out\n\n")
		sent.ReverseIterateByOffset(0, 10, func(k string, v any) bool {
			s := v.(*sentMsg)
			m, _ := hl.ParseMessage([]byte(s.raw))
			id := hl.ID([]byte(s.raw))
			b.WriteString("- #" + u32(m.Nonce) + " to " + u32(m.Destination) + " at block " + strconv.FormatInt(s.height, 10) + ": `" + hx(id[:]) + "`\n")
			return false
		})
	}
	return b.String()
}

func pkgPathLink() string { return strings.TrimPrefix(pkgPath, "gno.land") }

// Package hlverifier is the launch verifier of bridge/PLAN.md §5.1: the ed25519 check of the signers' signatures
// over a message's Hyperlane checkpoint, under the rule r/hlmailbox keeps beside its signer set — a threshold over
// the set, or §11.13's two groups (one key of group A and one of group B must sign). It registers itself with the
// mailbox at deploy and keeps no state: the signers and the rule are the mailbox's, read at every check, so a
// rotation there is a rotation here. Satisfiable answers whether a signer set could still meet the rule, which is
// what makes a signer's removal at once or a 7-day wait (§5.3).
package hlverifier

import (
	"crypto/ed25519"
	"errors"
	"strconv"

	hl "gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hyperlane/v0"
	"gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlmailbox"
)

const pkgPath = "gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlverifier" // must match gnomod.toml

// verifier is the hlmailbox.Verifier this realm registers.
type verifier struct{}

func init(cur realm) {
	hlmailbox.RegisterVerifier(cross(cur), verifier{})
}

// Verify checks the metadata — Hyperlane's checkpoint head (hook 32 ‖ root 32 ‖ index 4), then 65 bytes a
// signature: the signer's index in the set, then its ed25519 signature over the checkpoint digest of this message
// — and the rule: every signature present must verify, in increasing signer order, and the signers that signed
// must meet the rule.
func (verifier) Verify(origin uint32, metadata, message []byte) error {
	keys, rule := hlmailbox.Signers()
	if len(keys) == 0 {
		return errors.New("hlverifier: no signers")
	}
	m, err := hl.ParseMessage(message)
	if err != nil {
		return err
	}
	if m.Origin != origin {
		return errors.New("hlverifier: the message is from domain " + strconv.FormatUint(uint64(m.Origin), 10) + ", not " + strconv.FormatUint(uint64(origin), 10))
	}
	c, sigs, err := hl.ParseMultisigMetadata(metadata)
	if err != nil {
		return err
	}
	if len(sigs) == 0 {
		return errors.New("hlverifier: no signatures")
	}
	digest := hl.CheckpointDigest(m.Origin, c.Hook, c.Root, c.Index, hl.ID(message))
	var signed []hlmailbox.Key
	last := -1
	for _, s := range sigs {
		i := int(s.Validator)
		if i <= last {
			return errors.New("hlverifier: signatures out of signer order")
		}
		if i >= len(keys) {
			return errors.New("hlverifier: a signature names no signer")
		}
		k := keys[i]
		if !ed25519.Verify(k[:], digest[:], s.Sig[:]) {
			return errors.New("hlverifier: a signature does not verify")
		}
		signed = append(signed, k)
		last = i
	}
	if !satisfies(rule, signed) {
		return errors.New("hlverifier: the signatures do not meet the rule: " + rule.String())
	}
	return nil
}

// Satisfiable is whether a signer set could meet the rule the mailbox keeps now: the threshold many of them, or
// one of each group among them.
func (verifier) Satisfiable(signers []hlmailbox.Key) bool {
	_, rule := hlmailbox.Signers()
	return satisfies(rule, signers)
}

func satisfies(rule hlmailbox.Rule, signed []hlmailbox.Key) bool {
	if rule.TwoGroups() {
		return anyOf(rule.GroupA, signed) && anyOf(rule.GroupB, signed)
	}
	return rule.Threshold >= 1 && len(signed) >= rule.Threshold
}

func anyOf(group, signed []hlmailbox.Key) bool {
	for _, g := range group {
		for _, s := range signed {
			if g == s {
				return true
			}
		}
	}
	return false
}

// Registered is whether the mailbox holds this realm as a verifier.
func Registered() bool { return hlmailbox.VerifierRegistered(pkgPath) }

// Render: the rule enforced now.
func Render(path string) string {
	keys, rule := hlmailbox.Signers()
	active := ""
	if hlmailbox.ActiveVerifier(hlmailbox.LaunchOrigin()) == pkgPath {
		active = "the active verifier"
	} else {
		active = "registered, not the active verifier"
	}
	return "# The ed25519 verifier\n\n" + active + " for origin " + strconv.FormatUint(uint64(hlmailbox.LaunchOrigin()), 10) +
		": " + strconv.Itoa(len(keys)) + " signers in r/hlmailbox under the rule " + rule.String() + "\n"
}

// Package hlfees is the bridge's fee realm (bridge/PLAN.md §5.5): the routes pay every fee here — GNOT as coins,
// BUBBLE through the token realm — and only the treasurer a decision names may withdraw, to itself. The treasurer
// at launch is compiled in below; a decision made with the builder changes it, 7 days after it is made — the
// governor's own through Govern until it yields on r/hlmailbox, a GovDAO proposal's after (M1k).
package hlfees

import (
	"chain"
	"chain/banker"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble"
	"gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlmailbox"
	"gno.land/r/gov/dao"
)

const (
	namespace = "gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/"
	pkgPath   = namespace + "hlfees" // must match gnomod.toml

	// launchTreasurer is the operator's named key (§5.5, §11.12): a PLACEHOLDER — the deployer's hotkey — until
	// the launch notice names it; GovDAO can name the chain's own address instead at any vote.
	launchTreasurer = address("g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp")
)

// launchGovernor is the governor (M1k): the mailbox's, compiled here too so a member reads it in this realm's
// served source; init refuses a deploy with another. bridge/local/e2e.sh swaps it for gnodev's test1.
const launchGovernor = address("g1ecsuj0q572jr0dhu29q9njtnmw03hyu7tyyvv6")

var (
	treasurer = launchTreasurer
	ledger    decisions.Ledger
)

// init refuses a deploy whose compiled governor is not the mailbox's (M1k): the bridge's realms are governed by
// one key until it yields, or by GovDAO from the first block, never a mix.
func init() {
	if launchGovernor != hlmailbox.Governor() {
		panic("hlfees: the compiled governor " + string(launchGovernor) + " is not the mailbox's " + string(hlmailbox.Governor()))
	}
}

type (
	treasurerParams struct{ to address }
	cancelParams    struct{ id int64 }
)

func now() int64 { return time.Now().Unix() }

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// Address is this realm's address: where the routes pay the fees.
func Address() address { return chain.PackageAddress(pkgPath) }

// Treasurer is the one address that may withdraw.
func Treasurer() address { return treasurer }

// Balances are the fees held: ugnot and BUBBLE base units.
func Balances() (ugnot, bubbles int64) {
	return banker.NewReadonlyBanker().GetCoin(Address(), "ugnot"), bubble.BalanceOf(Address())
}

// Withdraw pays everything held to the treasurer, who alone may call it.
func Withdraw(cur realm) {
	if !cur.IsCurrent() {
		panic("hlfees: that realm value is not live; pass your own cur")
	}
	if cur.Previous().Address() != treasurer {
		panic("hlfees: only the treasurer withdraws")
	}
	ugnot, bubbles := Balances()
	if ugnot > 0 {
		banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(Address(), treasurer, chain.Coins{{"ugnot", ugnot}})
	}
	if bubbles > 0 {
		bubble.Transfer(cross(cur), treasurer, bubbles)
	}
	chain.Emit("Withdrawn", "to", string(treasurer), "ugnot", itoa(ugnot), "bubble", itoa(bubbles))
}

// ------------------------------------------------------------ builders --

// Request is what a builder returns (M1k): the proposal GovDAO's proxy executes after the yield (Proposal), and
// the same decision the governor runs directly before it (Govern); see hlgnot's.
type Request struct {
	proposal dao.ProposalRequest
	text     string
	decide   func(cur realm) error
}

// Proposal is the request as a GovDAO proposal: `dao.MustCreateProposal(cross(cur), req.Proposal())`.
func (r Request) Proposal() dao.ProposalRequest { return r.proposal }

// Description is the proposal's: the parameters as the builder wrote them.
func (r Request) Description() string { return r.text }

// who names a previous realm in a refusal: its pkgpath, or a user's address.
func who(path string, a address) string {
	if path != "" {
		return path
	}
	return string(a)
}

// mustBeGovernor is a decision's identity check (M1k), read from the closure's own live cur: the governor's own
// call until it yields on r/hlmailbox, gno.land/r/gov/dao's proxy exactly after (or from the first block, when no
// governor was compiled); see hlgnot's.
func mustBeGovernor(cur realm) {
	prev := cur.Previous()
	if decisions.DAOGoverns(launchGovernor, hlmailbox.Yielded()) {
		if p := prev.PkgPath(); p != decisions.DAOPath {
			panic("hlfees: only " + decisions.DAOPath + " executes a decision, not " + who(prev.PkgPath(), prev.Address()))
		}
		return
	}
	if !prev.IsUser() || prev.Address() != launchGovernor {
		panic("hlfees: until the governor yields, " + string(launchGovernor) + " alone decides, by Govern from its own key: not " + who(prev.PkgPath(), prev.Address()) + " (a GovDAO proposal is refused until the yield)")
	}
}

func mustBeLive() {
	if !hlmailbox.Live() {
		panic("hlfees: not launched: before the Launch decision only cancel is proposed")
	}
}

func propose(cur realm, kind, text string, apply func(made, t int64)) Request {
	if !cur.IsCurrent() {
		panic("hlfees: that realm value is not live; pass your own cur")
	}
	made := now()
	cb := func(cur realm) error {
		mustBeGovernor(cur)
		t := now()
		if err := decisions.Expired(made, t); err != nil {
			return err
		}
		apply(made, t)
		return nil
	}
	return Request{proposal: dao.NewProposalRequest("hlfees: "+kind, text, dao.NewSimpleExecutor(0, cur, cb, text)), text: text, decide: cb}
}

// Govern is the governor's way in before the yield (M1k): the same closure GovDAO's proxy runs after it, called
// non-crossing in this frame so it reads the governor from cur.Previous(); refused for anyone else and for
// everyone once the governor yielded on r/hlmailbox (or when none was compiled); see hlgnot's.
func Govern(cur realm, r Request) {
	if !cur.IsCurrent() {
		panic("hlfees: that realm value is not live; pass your own cur")
	}
	if r.decide == nil {
		panic("hlfees: not a builder's request")
	}
	if yielded := hlmailbox.Yielded(); decisions.DAOGoverns(launchGovernor, yielded) {
		if launchGovernor == "" {
			panic("hlfees: no governor was compiled, " + decisions.DAOPath + " governs from the first block: a decision is a GovDAO proposal, never Govern")
		}
		panic("hlfees: the governor yielded at height " + itoa(yielded) + ", " + decisions.DAOPath + " governs since: a decision is a GovDAO proposal, never Govern")
	}
	mustBeGovernor(cur)
	if err := r.decide(cur); err != nil {
		panic("hlfees: " + err.Error())
	}
}

// NewSetTreasurerRequest names the address that may withdraw, 7 days after the decision is made.
func NewSetTreasurerRequest(cur realm, to address) Request {
	mustBeLive()
	if !to.IsValid() {
		panic("hlfees: not an address: " + string(to))
	}
	if to == treasurer {
		panic("hlfees: " + string(to) + " is the treasurer already")
	}
	text := "set treasurer to " + string(to) + " (now " + string(treasurer) + ")"
	return propose(cur, "set treasurer", text, func(made, t int64) {
		mustBeLive()
		d := ledger.Record("set treasurer", text, treasurerParams{to}, made, t, t+decisions.Delay)
		d.Note = "queued 7 days"
		chain.Emit("Decision", "id", itoa(d.ID), "kind", "set treasurer", "state", "queued")
	})
}

// NewCancelRequest cancels a pending decision of this realm, at once.
func NewCancelRequest(cur realm, id int64) Request {
	d := ledger.Get(id)
	if d == nil || !d.Pending() {
		panic("hlfees: decision " + itoa(id) + " is not pending")
	}
	text := "cancel decision " + itoa(id) + " (" + d.Text + ")"
	return propose(cur, "cancel", text, func(made, t int64) {
		if _, err := ledger.Cancel(id, t); err != nil {
			panic("hlfees: " + err.Error())
		}
		c := ledger.Record("cancel", text, cancelParams{id}, made, t, t)
		ledger.Apply(c, t, "at once: cancelled")
	})
}

// Execute applies a queued decision whose 7 days have passed; anyone may call it.
func Execute(cur realm, id int64) {
	if !cur.IsCurrent() {
		panic("hlfees: that realm value is not live; pass your own cur")
	}
	t := now()
	d, err := ledger.Due(id, t)
	if err != nil {
		panic("hlfees: " + err.Error())
	}
	p, ok := d.Params.(treasurerParams)
	if !ok {
		panic("hlfees: decision " + itoa(id) + " has nothing to apply")
	}
	treasurer = p.to
	ledger.Apply(d, t, "applied after the delay")
	chain.Emit("TreasurerSet", "address", string(treasurer))
}

// --------------------------------------------------------------- pages --

// Render: "" the page; "json" the figures; "decisions" and "decisions.json" the decisions.
func Render(path string) string {
	ugnot, bubbles := Balances()
	switch path {
	case "":
		var b strings.Builder
		b.WriteString("# The bridge's fees\n\n")
		b.WriteString("Every fee the bridge takes lands here: GNOT as coins, BUBBLE as the token. Only the treasurer a decision names withdraws, to itself.\n\n")
		b.WriteString("- held: " + itoa(ugnot) + " ugnot, " + itoa(bubbles) + " BUBBLE base units\n")
		b.WriteString("- treasurer: " + string(treasurer) + "\n")
		b.WriteString("- " + decisions.GovernorLine(launchGovernor, hlmailbox.Yielded()) + "\n")
		b.WriteString("- " + decisions.Clocks() + "\n")
		b.WriteString("\n## Decisions\n\n" + ledger.Page())
		return b.String()
	case "json":
		return "{\"address\":" + strconv.Quote(string(Address())) + ",\"treasurer\":" + strconv.Quote(string(treasurer)) +
			"," + decisions.GovernorJSON(launchGovernor, hlmailbox.Yielded()) +
			",\"ugnot\":" + itoa(ugnot) + ",\"bubble\":" + itoa(bubbles) + ",\"clocks\":" + decisions.ClocksJSON() + ",\"decisions\":" + itoa(ledger.Last()) + "}"
	case "decisions":
		return "# Decisions\n\n" + ledger.Page()
	case "decisions.json":
		return ledger.JSON()
	}
	return "unknown path; see the page"
}

// Package hlgnot is the GNOT lock: the bridge's GNOT route on gno.land (bridge/PLAN.md §5.2, §5.4, §5.5).
//
// Out. TransferRemote takes the coins a direct user call sends — exactly amount + fee in ugnot — keeps the amount
// in the lock, pays the fee to r/hlfees, and sends a token message through r/hlmailbox to the synthetic GNOT
// program on Solana, which mints as much there.
//
// In. A burn on Solana comes back as a token message: Process takes it from the mailbox (which checks the active
// verifier and that it was never delivered), checks it came from the enrolled router, and writes a claim in the
// recipient's queue — never a payment on the spot. Claim pays claims in turns under the meters: a tenth of the
// lock a day (never below the floor), a quarter of that for any one recipient, the fee as the first installment,
// from a meter that starts empty at launch and after every unpause that clears a payouts flag. A burn below the
// fee, or to a realm address, is credited to the sweep queue, which only a GovDAO decision pays.
//
// Who may change what. Nobody: every setting moves by a decision made with the builders below (the fee and
// minimum, the fee floor, the cap floor, the per-message maximum, the router; a void, a restore or a credit by
// message id; a sweep payment; a refund by id; a migration to a successor), at once or after 7 days as §5.3 says —
// the governor's own decision through Govern until it yields on r/hlmailbox, a GovDAO proposal's after (M1k);
// the guardians and watch keys can only pause (sends, credits, payouts) through r/hlmailbox. Every launch value is
// compiled in below and written at deploy; nothing is sent or credited until the Launch decision executes.
//
// The state machine — claims, meters, counters, the identity of §5.9 — is gno.land/p/…/hlroute/v0; this realm
// holds the coins and makes the calls.
package hlgnot

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlroute/v0"
	hl "gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hyperlane/v0"
	"gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlmailbox"
	"gno.land/r/gov/dao"
)

const (
	namespace = "gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/"
	pkgPath   = namespace + "hlgnot" // must match gnomod.toml

	mailboxPath  = namespace + "hlmailbox"
	feesPath     = namespace + "hlfees"
	bubblePath   = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble" // the live token realm, never redeployed
	hlbubblePath = namespace + "hlbubble"
	hlgovPath    = namespace + "hlgov"

	gnot = int64(1_000_000) // one GNOT in ugnot

	// The launch values (§5.3, §5.5): the fee, the minimum, the fee floor, the cap floor, the per-message maximum,
	// and the router — the synthetic GNOT program on Solana. The router is a PLACEHOLDER (the test route of the
	// vectors) until the setup step (§5.8) gives the program id; bridge/local/e2e.sh swaps it for its run's.
	launchFee      = 5 * gnot
	launchMinimum  = 10 * gnot
	launchFeeFloor = 2 * gnot
	launchCapFloor = 10_000 * gnot
	launchMaximum  = 25_000 * gnot
	launchRouter   = "9c79e6474d5e4cb2e1bb479df49c8d7c0244af0bb1cf452aa573386632894895" // the GNOT token program BXpQkFcsHEsqVxvFQ2e4VSgfDSNBCKQsuKx9Qd2xtKj2

	maxI64 = uint64(1<<63 - 1)
)

// launchGovernor is the governor (M1k): the mailbox's, compiled here too so a member reads it in this realm's
// served source; init refuses a deploy with another. bridge/local/e2e.sh swaps it for gnodev's test1.
const launchGovernor = address("g1ecsuj0q572jr0dhu29q9njtnmw03hyu7tyyvv6")

var (
	st = hlroute.New(hlroute.Launch{Symbol: "GNOT", Fee: launchFee, Minimum: launchMinimum, FeeFloor: launchFeeFloor,
		CapFloor: launchCapFloor, Maximum: launchMaximum, Domain: hlmailbox.LaunchOrigin(), Router: mustKey(launchRouter),
		Now: time.Now().Unix()})

	// realms are the addresses a transfer may not name as its recipient on either side (§5.2): a burn to one of
	// them goes to the sweep queue, a send to one is refused.
	realms = []address{chain.PackageAddress(pkgPath), chain.PackageAddress(mailboxPath), chain.PackageAddress(feesPath),
		chain.PackageAddress(bubblePath), chain.PackageAddress(hlbubblePath), chain.PackageAddress(hlgovPath)}
)

// init refuses a deploy whose compiled governor is not the mailbox's (M1k): the bridge's realms are governed by
// one key until it yields, or by GovDAO from the first block, never a mix.
func init() {
	if launchGovernor != hlmailbox.Governor() {
		panic("hlgnot: the compiled governor " + string(launchGovernor) + " is not the mailbox's " + string(hlmailbox.Governor()))
	}
}

func mustKey(s string) [32]byte {
	k, err := hl.ParseKey32(s)
	if err != nil {
		panic(err.Error())
	}
	return k
}

func now() int64 { return time.Now().Unix() }

func u32(n uint32) string { return strconv.FormatUint(uint64(n), 10) }
func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("hlgnot: that realm value is not live; pass your own cur")
	}
	return cur.Previous().Address()
}

func mustHex(s, what string) []byte {
	b, err := hex.DecodeString(strings.TrimPrefix(strings.TrimSpace(s), "0x"))
	if err != nil {
		panic("hlgnot: the " + what + " is not hex")
	}
	return b
}

// isRealm is whether an address is a realm of the bridge: the six compiled here, every route realm the mailbox
// registers (R39) and every one it dropped (AT6: a re-pointed-away successor, a route no more that nothing of the
// line can move coins out of) — a successor's address, which its page prints as the lock's holder and a holder
// pastes as a deposit address, is refused as a recipient at send and swept at a credit, to be credited to its
// owner by id, never paid into a realm's account outside every counter. A handful of reads.
func isRealm(a address) bool {
	for _, r := range realms {
		if r == a {
			return true
		}
	}
	for _, p := range hlmailbox.Routes() {
		if chain.PackageAddress(p) == a {
			return true
		}
	}
	for _, p := range hlmailbox.DroppedRoutes() {
		if chain.PackageAddress(p) == a {
			return true
		}
	}
	return false
}

func mustBeLive() {
	if !hlmailbox.Live() {
		panic("hlgnot: not launched: nothing is sent, credited or paid before the Launch decision")
	}
}

func mustNotBePaused(fn string) {
	if hlmailbox.Paused(pkgPath, fn) {
		panic("hlgnot: " + fn + " are paused by a guardian or a watch key")
	}
}

// mustNotBeDropped refuses a realm the mailbox dropped from its line (R35): its predecessor re-pointed the migration
// to another successor while this realm had pulled nothing, so it is a route no more — Solana's token may still
// name it the router until the next kind 6, and a send or a credit here would be against a lock no realm of the
// line holds. The mailbox refuses its Dispatch and its Process too; the line's last realm takes every message
// addressed to it once its import has ended.
func mustNotBeDropped() {
	if by := hlmailbox.Dropped(pkgPath); by != "" {
		panic("hlgnot: a route no more: " + by + " re-pointed its migration to another successor; the line's last realm takes every message and send")
	}
}

// syncLaunch empties the meters at the launch, once: they start empty there as at a deploy (§5.4).
func syncLaunch() {
	if la := hlmailbox.LaunchedAt(); la != st.LaunchSeen {
		st.ResetMeters(la)
		st.LaunchSeen = la
	}
}

// ------------------------------------------------------------- reading --

// Address is this realm's address: the holder of the lock, and (as 32 bytes) the router the Solana program enrolls.
func Address() address { return chain.PackageAddress(pkgPath) }

// Locked is the lock: what backs synthetic GNOT on Solana, by the counters (sent − paid).
func Locked() int64 { return st.Lock }

// Balance is the ugnot this realm's account holds; it is the lock unless someone sent coins here outside a transfer.
func Balance() int64 { return banker.NewReadonlyBanker().GetCoin(Address(), "ugnot") }

// Router is the enrolled router on Solana, in hex.
func Router() string { return hex.EncodeToString(st.Router[:]) }

// Domain is the Solana domain this route sends to and takes from.
func Domain() uint32 { return st.Domain }

func Fee() int64      { return st.Fee }
func Minimum() int64  { return st.Minimum }
func FeeFloor() int64 { return st.FeeFloor }
func CapFloor() int64 { return st.CapFloor }
func Maximum() int64  { return st.Maximum }
func Cap() int64      { return st.Cap() }

// Counters is the identity's five counters (§5.9): sentTotal, paidTotal, owed, voided, lost.
func Counters() (sentTotal, paidTotal, owed, voided, lost int64) {
	return st.SentTotal, st.PaidTotal, st.Owed, st.Voided, st.Lost
}

// Migrated is the successor's pkgpath once a migration applied, "" before.
func Migrated() string { return st.MigratedTo }

// ---------------------------------------------------------------- out --

// TransferRemote sends amount of GNOT to recipient on destination (a Solana address in base58, or 32 bytes in
// hex) and returns the message id in hex. The call must be a direct user call sending exactly amount + fee in
// ugnot: the amount is locked here, the fee goes to r/hlfees. The amount is between the minimum and the
// per-message maximum; a realm's address as recipient is refused.
func TransferRemote(cur realm, destination uint32, recipient string, amount int64) string {
	mustBeLive()
	mustNotBePaused(hlmailbox.FnSends)
	mustNotBeDropped()
	st.MustSend(hlmailbox.Predecessor(pkgPath), env(cur)) // a successor takes no send before its last page is in (R35, F28) and before kind 6 names it (AT7)
	if destination != st.Domain {
		panic("hlgnot: no route to domain " + u32(destination))
	}
	st.CheckSend(amount)
	to, err := hl.ParseKey32(recipient)
	if err != nil {
		panic(err.Error())
	}
	if to == ([32]byte{}) {
		panic("hlgnot: the recipient is all zeros")
	}
	if a, err := hl.Bytes32ToAddress(to); err == nil && isRealm(a) {
		panic("hlgnot: the recipient is a realm of the bridge")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("hlgnot: a direct user call only")
	}
	want := amount + st.Fee
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != want {
		panic("hlgnot: send exactly " + itoa(want) + "ugnot (the amount plus the fee of " + itoa(st.Fee) + "), not " + sent.String())
	}
	runtime.AssertOriginCall() // a direct MsgCall, so the envelope landed here and nothing ran in between
	who := prev.Address()
	banker.NewBanker(banker.BankerTypeOriginSend, cur).SendCoins(Address(), chain.PackageAddress(feesPath), chain.Coins{{"ugnot", st.Fee}})
	id := hlmailbox.Dispatch(cross(cur), destination, st.Router, hl.TokenMessage(to, uint64(amount), nil))
	idHex := hex.EncodeToString(id[:])
	st.Send(now(), idHex, who, amount)
	chain.Emit("SentTransferRemote",
		"destination", u32(destination),
		"recipient", hex.EncodeToString(to[:]),
		"amount", itoa(amount),
		"fee", itoa(st.Fee),
		"from", string(who),
		"id", idHex,
	)
	return idHex
}

// ----------------------------------------------------------------- in --

// Process takes a token message from Solana and credits a claim to its recipient. Anyone may call it — a relayer,
// usually — with the verifier's metadata and the message, both in hex. The mailbox checks the verifier and that
// the message was never delivered; this checks it came from the enrolled router (the old one too, for 7 days after
// a swap). A refused message stays undelivered and can be brought again. A realm registered as a successor credits
// nothing before the last page of its predecessor's migration is in (R32) — a message addressed to itself as much
// as one addressed to the predecessor (AQ1: the mailbox hands a migrated route's messages to its successor) — and
// a migrated realm refuses before the mailbox is asked: the successor takes it.
func Process(cur realm, metadata, message string) {
	caller(cur)
	mustBeLive()
	mustNotBePaused(hlmailbox.FnCredits)
	mustNotBeDropped()
	msg := mustHex(message, "message")
	m, err := hl.ParseMessage(msg)
	if err != nil {
		panic(err.Error())
	}
	if st.Migrated() {
		panic("hlgnot: migrated to " + st.MigratedTo + ": the successor takes this message")
	}
	if self, err := hl.AddressToBytes32(Address()); err != nil {
		panic(err.Error())
	} else {
		st.MustTake(m.Recipient == self, hlmailbox.Predecessor(pkgPath))
	}
	t := now()
	if m.Origin != st.Domain || !st.RouterAccepts(t, m.Sender) {
		panic("hlgnot: the message is not from the router enrolled for domain " + u32(st.Domain))
	}
	rcpt, amount, _, err := hl.ParseTokenMessage(m.Body)
	if err != nil {
		panic(err.Error())
	}
	if amount > maxI64 {
		panic("hlgnot: the amount is past what GNOT can hold")
	}
	origin, sender, body := hlmailbox.Process(cross(cur), mustHex(metadata, "metadata"), msg)
	if origin != m.Origin || sender != m.Sender || string(body) != string(m.Body) {
		panic("hlgnot: the mailbox read the message differently") // cannot happen: the same bytes, the same parser
	}
	// a recipient that is no gno address (its top twelve bytes not zero, §13) or a realm of the bridge is swept:
	// owed, paying nobody until GovDAO credits it by id to its owner
	to, err := hl.Bytes32ToAddress(rcpt)
	recipient := string(to)
	if err != nil {
		recipient = hex.EncodeToString(rcpt[:])
	}
	idb := hl.ID(msg)
	id := hex.EncodeToString(idb[:])
	epoch, _ := hlmailbox.PayoutsEpoch(pkgPath)
	swept := st.Credit(t, runtime.ChainHeight(), epoch, id, to, int64(amount), hlroute.BySigners, err != nil || isRealm(to))
	chain.Emit("Credited",
		"origin", u32(origin),
		"recipient", recipient,
		"amount", itoa(int64(amount)),
		"id", id,
		"swept", strconv.FormatBool(swept),
	)
}

// Claim pays up to n claims (n ≤ 20) taking recipients in turns under the meters, the fee as each claim's first
// installment. Anyone may call it; the relayers do. It returns how many claims it paid something on.
func Claim(cur realm, n int) int {
	caller(cur)
	mustBeLive()
	mustNotBePaused(hlmailbox.FnPayouts)
	mustNotBeDropped()
	syncLaunch()
	epoch, at := hlmailbox.PayoutsEpoch(pkgPath)
	paid := st.Claim(now(), n, epoch, at, env(cur))
	chain.Emit("Claimed", "count", strconv.Itoa(paid))
	return paid
}

func pay(cur realm, to address, amount int64) {
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(Address(), to, chain.Coins{{"ugnot", amount}})
}

// env is what the state machine asks of this realm.
func env(cur realm) hlroute.Env {
	return hlroute.Env{
		Flagged:    func(id string, height int64, verifier bool) bool { return hlmailbox.Flagged(pkgPath, id, height, verifier) },
		ClearFlags: func(fn string) bool { return hlmailbox.ClearFlags(cross(cur), fn) },
		RemoveSeat: func(seat int, holder address) bool { return hlmailbox.VacateSeat(cross(cur), seat, holder) },
		Delivered:  func(id string) bool { return hlmailbox.Delivered(id) != 0 },
		MarkDone:   func(id string) { hlmailbox.MarkDone(cross(cur), id) },
		Epoch:      func() int64 { e, _ := hlmailbox.PayoutsEpoch(pkgPath); return e },
		Height:     func() int64 { return runtime.ChainHeight() },
		Pay:        func(to address, amount int64) { pay(cur, to, amount) },
		PayFee:     func(amount int64) { pay(cur, chain.PackageAddress(feesPath), amount) },
		AddRoute:     func(path string) { hlmailbox.AddRoute(cross(cur), path) },
		AnnouncedFor: func(path string) string { return hlmailbox.SuccessorFor(path) },
		Predecessor:  func() string { return hlmailbox.Predecessor(pkgPath) },
		IsRoute:      func(path string) bool { return hlmailbox.IsRoute(path) },
		Enrolled:     func() (int64, int64) { return hlmailbox.Enrolled(pkgPath) },
	}
}

// ------------------------------------------------------------ builders --

// The builders (§5.3): a decision made with one of these is the only way a setting changes — the governor's own,
// through Govern, until it yields on r/hlmailbox (M1k):
//
//	hlgnot.Govern(cross(cur), hlgnot.NewSetCapFloorRequest(cross(cur), 12_000_000_000))
//
// and a GovDAO proposal after:
//
//	req := hlgnot.NewSetCapFloorRequest(cross(cur), 12_000_000_000)
//	dao.MustCreateProposal(cross(cur), req.Proposal())
//
// Each checks its parameters, writes them as the proposal's description, and returns a Request whose closure —
// the one closure, run by the governor through Govern or by GovDAO's proxy when the proposal executes — records
// the decision and settles its at-once test against the live state: a lowering, a cancel, a restore of a withheld
// claim and the void of ids a guardian's standing payouts flag names apply at once; a raise, a swap, a credit, a
// sweep payment, a migration, a void of unnamed ids and a restore of a forged claim wait 7 days, and anyone
// applies them with Execute(id); a refund waits 7 days too and is then applied by the governor's (GovDAO's, after
// the yield) own at-once decision (NewApplyRefundRequest, AT2), never by Execute. Before the Launch decision only
// cancel is proposed.

// Request is what a builder returns (M1k): the proposal GovDAO's proxy executes after the yield (Proposal), and
// the same decision the governor runs directly before it (Govern). The closure is one; only who may run it
// changes with the yield. A Request comes from a builder alone — the type is this realm's and the closure
// unexported, so no other code can build one or change what it decides — and a stranger holding one can only
// hand it back to Govern, which refuses everyone but the governor.
type Request struct {
	proposal dao.ProposalRequest
	text     string
	decide   func(cur realm) error
}

// Proposal is the request as a GovDAO proposal: `dao.MustCreateProposal(cross(cur), req.Proposal())`.
func (r Request) Proposal() dao.ProposalRequest { return r.proposal }

// Description is the proposal's: the parameters as the builder wrote them.
func (r Request) Description() string { return r.text }

// who names a previous realm in a refusal: its pkgpath, or a user's address.
func who(path string, a address) string {
	if path != "" {
		return path
	}
	return string(a)
}

// mustBeGovernor is a decision's identity check (M1k), read from the closure's own live cur: until the governor
// yields on r/hlmailbox, the governor's own call — the compiled address, by its own transaction (cur.Previous() a
// user realm: a MsgCall's, or a MsgRun script's ephemeral realm, whose address is the signer's; never another
// realm), which is Govern's non-crossing call of the closure — and gno.land/r/gov/dao's proposals refused; after
// it, or when no governor was compiled, the proxy's exact pkgpath, as before M1k, and the governor refused like
// anyone. A refusal is a panic: a proposal made before the yield survives for a retry after it, within its 14
// days.
func mustBeGovernor(cur realm) {
	prev := cur.Previous()
	if decisions.DAOGoverns(launchGovernor, hlmailbox.Yielded()) {
		if p := prev.PkgPath(); p != decisions.DAOPath {
			panic("hlgnot: only " + decisions.DAOPath + " executes a decision, not " + who(prev.PkgPath(), prev.Address()))
		}
		return
	}
	if !prev.IsUser() || prev.Address() != launchGovernor {
		panic("hlgnot: until the governor yields, " + string(launchGovernor) + " alone decides, by Govern from its own key: not " + who(prev.PkgPath(), prev.Address()) + " (a GovDAO proposal is refused until the yield)")
	}
}

func propose(cur realm, d hlroute.Draft) Request {
	if !cur.IsCurrent() {
		panic("hlgnot: that realm value is not live; pass your own cur")
	}
	made := now()
	cb := func(cur realm) error {
		mustBeGovernor(cur)
		t := now()
		if err := decisions.Expired(made, t); err != nil {
			return err
		}
		if d.Kind != hlroute.KindCancel {
			mustBeLive()
		}
		if d.Kind == hlroute.KindApplyRefund {
			mustNotBePaused(hlmailbox.FnPayouts) // a refund moves coins out of the lock: under a standing payouts flag it waits like a claim (§5.9; the proposal survives for a retry)
		}
		dec := st.Decide(made, t, d, env(cur))
		chain.Emit("Decision", "id", itoa(dec.ID), "kind", dec.Kind, "state", dec.State())
		return nil
	}
	return Request{proposal: dao.NewProposalRequest("hlgnot: "+d.Kind, d.Text, dao.NewSimpleExecutor(0, cur, cb, d.Text)), text: d.Text, decide: cb}
}

// Govern is the governor's way in before the yield (M1k): the governor — the compiled launchGovernor, by its own
// transaction (the MsgRun script that makes the request in the same transaction; never through another realm) —
// makes a builder's decision directly, the same closure GovDAO's proxy runs after the yield: the same checks, the
// same at-once test, the same 7-day queue and 14-day deadline, the same record and events. The closure is called
// non-crossing, in this frame, so it reads the governor from cur.Previous() as it reads the proxy after the yield.
// Refused for anyone else, and for everyone once the governor yielded on r/hlmailbox (or when none was compiled):
// GovDAO's proposals decide then. A request past its 14 days is refused (the deadline error) and made afresh.
func Govern(cur realm, r Request) {
	if !cur.IsCurrent() {
		panic("hlgnot: that realm value is not live; pass your own cur")
	}
	if r.decide == nil {
		panic("hlgnot: not a builder's request")
	}
	if yielded := hlmailbox.Yielded(); decisions.DAOGoverns(launchGovernor, yielded) {
		if launchGovernor == "" {
			panic("hlgnot: no governor was compiled, " + decisions.DAOPath + " governs from the first block: a decision is a GovDAO proposal, never Govern")
		}
		panic("hlgnot: the governor yielded at height " + itoa(yielded) + ", " + decisions.DAOPath + " governs since: a decision is a GovDAO proposal, never Govern")
	}
	mustBeGovernor(cur)
	if err := r.decide(cur); err != nil {
		panic("hlgnot: " + err.Error())
	}
}

// NewSetCapFloorRequest sets the day cap's floor (in ugnot): a lowering at once, never below the launch floor; a
// raise after 7 days.
func NewSetCapFloorRequest(cur realm, n int64) Request {
	mustBeLive()
	return propose(cur, st.DraftCapFloor(n))
}

// NewSetMaximumRequest sets the per-message maximum (in ugnot), never below the minimum: a lowering at once, a
// raise after 7 days.
func NewSetMaximumRequest(cur realm, n int64) Request {
	mustBeLive()
	return propose(cur, st.DraftMaximum(n))
}

// NewSetFeeRequest sets the fee and the minimum together (in ugnot), the fee not below the fee floor: lowering
// both at once, raising either after 7 days.
func NewSetFeeRequest(cur realm, fee, minimum int64) Request {
	mustBeLive()
	return propose(cur, st.DraftFee(fee, minimum))
}

// NewSetFeeFloorRequest sets the fee floor (in ugnot), not above the fee: a lowering at once, a raise after 7 days.
func NewSetFeeFloorRequest(cur realm, n int64) Request {
	mustBeLive()
	return propose(cur, st.DraftFeeFloor(n))
}

// NewSetRouterRequest swaps the router (a Solana program id in base58, or 32 bytes in hex) after 7 days; the old
// router's messages stay accepted for 7 days more.
func NewSetRouterRequest(cur realm, router string) Request {
	mustBeLive()
	return propose(cur, st.DraftRouter(mustKey(router), router))
}

// NewVoidRequest voids credits by message id (comma separated, up to 256; a claim, or a sweep entry as forged) or
// by a range of credits ("heights:<from>-<to>", every credit at those block heights; "since:<from>", every credit
// the verifier made from that height on), closed at the height the proposal is made and covering at most 1,000
// credits (a bigger range is split by heights), as withheld (the remainder stays booked, restorable) or as forged
// (the remainder dropped, the paid part lost; a sweep entry's amount dropped from what is owed). A credit a
// guardian's standing payouts flag names — by id, or by a range covering it — is voided the moment the proposal
// executes; the rest wait 7 days. The unpause option takes the unpause builder's parameters — the functions whose
// flags to clear (sends, credits, payouts; comma separated, "" for none) and the seats to vacate (comma separated,
// "" for none; each seat's holder now is recorded, and a seat whose occupant changed by execution is skipped) —
// applied in the same closure, after the void.
func NewVoidRequest(cur realm, ids string, forged bool, unpauseFns, removeSeats string) Request {
	mustBeLive()
	return propose(cur, st.DraftVoid(ids, forged, unpauseFns, removeSeats, runtime.ChainHeight(), hlmailbox.Seat))
}

// NewRestoreRequest restores voided claims by message id: a withheld one at once, a forged one after 7 days.
func NewRestoreRequest(cur realm, ids string) Request {
	mustBeLive()
	return propose(cur, st.DraftRestore(ids))
}

// NewCreditRequest credits a claim by hand after 7 days: amount (in ugnot) to a recipient under a message id. It
// marks the id done and refuses an id already done, unless that id's claim stands voided, in which case the claim
// is restored and its remainder replaced by this recipient and amount at the back of the recipient's queue.
func NewCreditRequest(cur realm, id string, to address, amount int64) Request {
	mustBeLive()
	if !to.IsValid() || isRealm(to) {
		panic("hlgnot: the recipient must be an address outside the bridge's realms")
	}
	return propose(cur, st.DraftCredit(id, to, amount, hlmailbox.Delivered(id) != 0))
}

// NewSweepRequest pays sweep entries, named by message id (comma separated, up to 256), to an address after 7
// days: their sum, at most the lock. The paid entries are dropped (R19), so none is ever paid, credited by id or
// voided twice; an entry voided or gone by then is skipped, the decision's note saying so.
func NewSweepRequest(cur realm, ids string, to address) Request {
	mustBeLive()
	if !to.IsValid() || isRealm(to) {
		panic("hlgnot: the recipient must be an address outside the bridge's realms")
	}
	return propose(cur, st.DraftSweep(ids, to))
}

// NewRefundRequest queues a refund of sends by message id (comma separated) to their senders, 7 days: the cure for
// sends a migration stranded undelivered — the sends imported from the predecessor, once kind 6 has enrolled this
// realm on Solana for 14 days by r/hlgov's note with the mailbox (AR1, R37: a refunded send stays deliverable
// there until the predecessor's router is replaced), checked when the proposal is made and when it applies. After
// the 7 days GovDAO applies it by NewApplyRefundRequest (AT2), never anyone by Execute.
func NewRefundRequest(cur realm, ids string) Request {
	mustBeLive()
	return propose(cur, st.DraftRefund(ids, now(), env(cur)))
}

// NewApplyRefundRequest applies a queued refund decision whose 7 days have passed, at once (AT2): GovDAO's own act,
// the member having read hlwatch's gate first — the token's router on Solana is this realm and the kind 6 is
// executed there — since this realm cannot see Solana, and a refund applied while the predecessor is still the
// router lets the refunded sender deliver his send there after it (minted twice, AR1); Execute refuses a refund.
// The apply is the delay's own: the note's 14 days asked again, the sum at most the lock; under a standing
// payouts flag it waits for the unpause like a claim (the closure refuses, the proposal retried within its 14
// days). Refused for a decision that is no refund, not pending, or not yet due; the description names the refund
// decision and carries its text, the ids included.
func NewApplyRefundRequest(cur realm, id int64) Request {
	mustBeLive()
	return propose(cur, st.DraftApplyRefund(id, now(), env(cur)))
}

// NewWriteOffRequest books refunded sends, by message id (comma separated), as lost after 7 days (AR1): a refunded
// send delivered on Solana after all (a stranger's Reemit) minted a second time against nothing, and the write-off
// closes the identity by its amount; only a refunded send, once — the member reads hlwatch's DELIVERED line for the
// id first.
func NewWriteOffRequest(cur realm, ids string) Request {
	mustBeLive()
	return propose(cur, st.DraftWriteOff(ids))
}

// NewMigrateRequest hands the lock, the claims and the send records to a successor realm after 7 days: the
// successor then calls Pull from its own code and takes them over. The successor must have announced itself to
// the mailbox from its own code first, for the GNOT route (hlmailbox.AnnounceSuccessor(cur, "GNOT"), R25 and
// AQ5), and must not be a route the mailbox registers already (R31) — checked when the proposal is made and when
// it applies, so the lock never goes to a path with no realm behind it, nor to the BUBBLE route's successor by a
// slip. A realm that succeeds another (a successor registered by its predecessor's migrate) migrates on only once
// its own import has ended (R31): before page 0 nothing has moved and the lock would be stranded for good.
func NewMigrateRequest(cur realm, to string) Request {
	mustBeLive()
	return propose(cur, st.DraftMigrate(to, pkgPath, env(cur)))
}

// NewCancelRequest cancels a pending decision of this route, at once. It is proposed before Launch too.
func NewCancelRequest(cur realm, id int64) Request {
	return propose(cur, st.DraftCancel(id))
}

// Execute applies a queued decision whose 7 days have passed. Anyone may call it; the relayers do. A sweep
// payment moves coins out of the lock, so under a standing payouts flag it waits for the unpause like a claim
// (§5.9: nothing paid under a suspect verifier). A refund is never Execute's (AT2): the state refuses the kind, and
// GovDAO applies it by NewApplyRefundRequest after hlwatch's Solana check.
func Execute(cur realm, id int64) {
	caller(cur)
	mustBeLive()
	if d := st.Ledger.Get(id); d != nil && d.Kind == hlroute.KindSweep {
		mustNotBePaused(hlmailbox.FnPayouts)
	}
	dec := st.Execute(now(), id, env(cur))
	chain.Emit("Decision", "id", itoa(dec.ID), "kind", dec.Kind, "state", dec.State())
}

// Pull is the successor's: once a migrate decision names it, the realm at that pkgpath calls Pull from its own
// code, page by page from 0, and receives the lock (paid to its address, with page 0) and the records to import,
// up to 500 a page (the snapshot's More says whether a page follows); a page pulled already hands over nothing.
// Page 0 moves the lock, so under a standing payouts flag it waits for the unpause like a sweep payment (R27, R16:
// nothing paid under a suspect verifier); the flag follows the claims to the successor (hlmailbox.AddRoute).
func Pull(cur realm, page int) *hlroute.Snapshot {
	if !cur.IsCurrent() {
		panic("hlgnot: that realm value is not live; pass your own cur")
	}
	path := cur.Previous().PkgPath()
	if st.MigratedTo == "" || path != st.MigratedTo {
		panic("hlgnot: only the successor named by a migrate decision pulls")
	}
	if page == 0 {
		mustNotBePaused(hlmailbox.FnPayouts)
	}
	snap := st.Export(page, hlroute.PullPage)
	if page == 0 {
		hlmailbox.NotePulled(cross(cur), path) // the lock moved: the mailbox answers Pulled (R35) — kind 6 may enrol the successor, and the migration is never re-pointed
	}
	if snap.Lock > 0 {
		pay(cur, chain.PackageAddress(path), snap.Lock)
	}
	chain.Emit("Migrated", "to", path, "page", strconv.Itoa(page), "lock", itoa(snap.Lock), "claims", strconv.Itoa(len(snap.Claims)), "sweeps", strconv.Itoa(len(snap.Sweeps)), "sends", strconv.Itoa(len(snap.Sends)), "more", strconv.FormatBool(snap.More))
	return snap
}

// --------------------------------------------------------------- pages --

func pausedText() string {
	var fns []string
	for _, fn := range []string{hlmailbox.FnSends, hlmailbox.FnCredits, hlmailbox.FnPayouts} {
		if hlmailbox.Paused(pkgPath, fn) {
			fns = append(fns, fn)
		}
	}
	return strings.Join(fns, ", ")
}

// Render:
//
//	""                the route's page (the first 100 waiting claims and sweep entries, the rest counted)
//	"decisions"       the decisions page: the last 100 pending and executed per kind
//	"json"            the figures for the agents
//	"decisions.json"  every decision
//	"claim/<id>"      one claim by message id, or the swept amount, or "null"
//	"claims/<from>"   up to 100 waiting claims from the <from>-th on, in the page's order, as a JSON array
//	"sweeps/<from>"   up to 100 sweep entries from the <from>-th on, by id, as a JSON array
//	"send/<id>"       one send by message id ({"id","from","amount","at","imported","refunded","writtenOff"}), or "null"
//	"refunds/<from>"  up to 100 sends refunded here from the <from>-th on, by id, as a JSON array (AQ2: what the
//	                  monitors read to drop a refunded send from what is in flight)
func Render(path string) string {
	epoch, at := hlmailbox.PayoutsEpoch(pkgPath)
	switch {
	case strings.HasPrefix(path, "claims/"):
		return st.ClaimsPage(parseFrom(path[len("claims/"):]))
	case strings.HasPrefix(path, "sweeps/"):
		return st.SweepsPage(parseFrom(path[len("sweeps/"):]))
	case strings.HasPrefix(path, "send/"):
		return st.SendJSON(path[len("send/"):])
	case strings.HasPrefix(path, "refunds/"):
		return st.RefundsPage(parseFrom(path[len("refunds/"):]))
	case path == "":
		var b strings.Builder
		b.WriteString("# GNOT across chains\n\n")
		b.WriteString("The bridge's GNOT route on gno.land. GNOT sent to Solana is locked here, and the synthetic GNOT there is backed by it one to one; a burn there is credited here as a claim, paid under the meters. Every setting moves only by a decision made with this realm's builders — the governor's own until it yields, a GovDAO proposal after.\n\n")
		if hlmailbox.Live() {
			b.WriteString("- **live** since " + itoa(hlmailbox.LaunchedAt()) + "\n")
		} else {
			b.WriteString("- **not launched**: the values below are the compiled launch values, waiting for the Launch decision\n")
		}
		b.WriteString("- " + decisions.GovernorLine(launchGovernor, hlmailbox.Yielded()) + "\n")
		b.WriteString("- balance: " + st.Amount(Balance()) + "\n")
		b.WriteString(st.Figures(now(), epoch, at, hlmailbox.LaunchedAt(), pausedText()))
		b.WriteString("\n## Decisions\n\n" + st.Ledger.Page())
		return b.String()
	case path == "decisions":
		return "# Decisions\n\n" + st.Ledger.Page()
	case path == "json":
		return "{\"address\":" + strconv.Quote(string(Address())) + ",\"live\":" + strconv.FormatBool(hlmailbox.Live()) +
			"," + decisions.GovernorJSON(launchGovernor, hlmailbox.Yielded()) +
			",\"balance\":" + itoa(Balance()) + ",\"paused\":" + strconv.Quote(pausedText()) + "," + st.JSON(now(), epoch, at, hlmailbox.LaunchedAt()) + "}"
	case path == "decisions.json":
		return st.Ledger.JSON()
	case strings.HasPrefix(path, "claim/"):
		return st.ClaimJSON(path[len("claim/"):])
	}
	return "unknown path; see the route's page"
}

// parseFrom reads a page's offset; -1 (an empty page) for anything but a number.
func parseFrom(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil || n < 0 {
		return -1
	}
	return n
}

// Package hlbubble is the BUBBLE lock: the bridge's BUBBLE route on gno.land (bridge/PLAN.md §5.2–§5.5), the same
// shape as r/hlgnot over the BUBBLE token (gno.land/r/…/bubble) instead of coins.
//
// Out. TransferRemote takes amount + fee of the caller's BUBBLE through the token's allowance (the caller approves
// this realm first), keeps the amount in the lock, pays the fee to r/hlfees, and sends a token message through
// r/hlmailbox to the synthetic BUBBLE program on Solana, which mints as much there.
//
// In. A burn on Solana comes back as a token message: Process takes it from the mailbox, checks it came from the
// enrolled router, and writes a claim in the recipient's queue; Claim pays claims in turns under the meters — a
// tenth of the lock a day (never below the floor), a quarter of that for any one recipient, the fee first. The old
// 1,000,000 BUBBLE day cap and the admin's pause are gone: the meter and the guardians' flags replace them.
//
// Who may change what. Nobody but the governor through the builders until it yields on r/hlmailbox, and GovDAO
// after (M1k); the guardians and watch keys can only pause, through r/hlmailbox. Every launch value is compiled in
// below; nothing moves until the Launch decision executes. The state machine is gno.land/p/…/hlroute/v0; this
// realm holds the BUBBLE and makes the calls.
package hlbubble

import (
	"chain"
	"chain/runtime"
	"encoding/hex"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/decisions/v0"
	"gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlroute/v0"
	hl "gno.land/p/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hyperlane/v0"
	"gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble"
	"gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/hlmailbox"
	"gno.land/r/gov/dao"
)

const (
	namespace = "gno.land/r/g1zdaz6sypk5tdsjc2fzsqrrn4ttn8qzmnl4waqp/"
	pkgPath   = namespace + "hlbubble" // must match gnomod.toml

	mailboxPath = namespace + "hlmailbox"
	feesPath    = namespace + "hlfees"
	bubblePath  = "gno.land/r/g1leu8d2vsplhehcfkjg50mwgdpxdkt8tztu95wr/bubble" // the live token realm, never redeployed
	hlgnotPath  = namespace + "hlgnot"
	hlgovPath   = namespace + "hlgov"

	one = int64(1_000_000) // one BUBBLE in base units

	// The launch values (§5.3, §5.5). The router — the synthetic BUBBLE program on Solana — is a PLACEHOLDER (the
	// test route of the vectors) until the setup step (§5.8); bridge/local/e2e.sh swaps it for its run's.
	launchFee      = 100 * one
	launchMinimum  = 200 * one
	launchFeeFloor = 40 * one
	launchCapFloor = 10_000 * one
	launchMaximum  = 25_000 * one
	launchRouter   = "c807d773013b14cee2855ca9efafeac0b3bbc3a42fd397c2fbffda6417d290f1" // the BUBBLE token program ETqUXu1uJPj8qgmw8AJMqhgWuL5QW5ymgUMiCARbXYPA

	maxI64 = uint64(1<<63 - 1)
)

// launchGovernor is the governor (M1k): the mailbox's, compiled here too so a member reads it in this realm's
// served source; init refuses a deploy with another. bridge/local/e2e.sh swaps it for gnodev's test1.
const launchGovernor = address("g1ecsuj0q572jr0dhu29q9njtnmw03hyu7tyyvv6")

var (
	st = hlroute.New(hlroute.Launch{Symbol: "BUBBLE", Fee: launchFee, Minimum: launchMinimum, FeeFloor: launchFeeFloor,
		CapFloor: launchCapFloor, Maximum: launchMaximum, Domain: hlmailbox.LaunchOrigin(), Router: mustKey(launchRouter),
		Now: time.Now().Unix()})

	// realms are the addresses a transfer may not name as its recipient on either side (§5.2).
	realms = []address{chain.PackageAddress(pkgPath), chain.PackageAddress(mailboxPath), chain.PackageAddress(feesPath),
		chain.PackageAddress(bubblePath), chain.PackageAddress(hlgnotPath), chain.PackageAddress(hlgovPath)}
)

// init refuses a deploy whose compiled governor is not the mailbox's (M1k): the bridge's realms are governed by
// one key until it yields, or by GovDAO from the first block, never a mix.
func init() {
	if launchGovernor != hlmailbox.Governor() {
		panic("hlbubble: the compiled governor " + string(launchGovernor) + " is not the mailbox's " + string(hlmailbox.Governor()))
	}
}

func mustKey(s string) [32]byte {
	k, err := hl.ParseKey32(s)
	if err != nil {
		panic(err.Error())
	}
	return k
}

func now() int64 { return time.Now().Unix() }

func u32(n uint32) string { return strconv.FormatUint(uint64(n), 10) }
func itoa(n int64) string { return strconv.FormatInt(n, 10) }

func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("hlbubble: that realm value is not live; pass your own cur")
	}
	return cur.Previous().Address()
}

func mustHex(s, what string) []byte {
	b, err := hex.DecodeString(strings.TrimPrefix(strings.TrimSpace(s), "0x"))
	if err != nil {
		panic("hlbubble: the " + what + " is not hex")
	}
	return b
}

// isRealm is whether an address is a realm of the bridge: the six compiled here, every route realm the mailbox
// registers (R39: a successor's address is refused as a recipient at send and swept at a credit, to be credited to
// its owner by id, never paid into a realm's account outside every counter) and every one it dropped (AT6: a
// re-pointed-away successor, a route no more that nothing of the line can move BUBBLE out of). A handful of reads.
func isRealm(a address) bool {
	for _, r := range realms {
		if r == a {
			return true
		}
	}
	for _, p := range hlmailbox.Routes() {
		if chain.PackageAddress(p) == a {
			return true
		}
	}
	for _, p := range hlmailbox.DroppedRoutes() {
		if chain.PackageAddress(p) == a {
			return true
		}
	}
	return false
}

func mustBeLive() {
	if !hlmailbox.Live() {
		panic("hlbubble: not launched: nothing is sent, credited or paid before the Launch decision")
	}
}

func mustNotBePaused(fn string) {
	if hlmailbox.Paused(pkgPath, fn) {
		panic("hlbubble: " + fn + " are paused by a guardian or a watch key")
	}
}

// mustNotBeDropped refuses a realm the mailbox dropped from its line (R35): its predecessor re-pointed the migration
// to another successor while this realm had pulled nothing, so it is a route no more — Solana's token may still
// name it the router until the next kind 6, and a send or a credit here would be against a lock no realm of the
// line holds. The mailbox refuses its Dispatch and its Process too; the line's last realm takes every message
// addressed to it once its import has ended.
func mustNotBeDropped() {
	if by := hlmailbox.Dropped(pkgPath); by != "" {
		panic("hlbubble: a route no more: " + by + " re-pointed its migration to another successor; the line's last realm takes every message and send")
	}
}

func syncLaunch() {
	if la := hlmailbox.LaunchedAt(); la != st.LaunchSeen {
		st.ResetMeters(la)
		st.LaunchSeen = la
	}
}

// ------------------------------------------------------------- reading --

// Address is this realm's address: the spender to approve on the bubble realm before TransferRemote, the holder
// of the lock, and (as 32 bytes) the router the Solana program enrolls.
func Address() address { return chain.PackageAddress(pkgPath) }

// Locked is the lock: what backs synthetic BUBBLE on Solana, by the counters (sent − paid).
func Locked() int64 { return st.Lock }

// Balance is the BUBBLE this realm holds; it is the lock unless someone sent BUBBLE here outside a transfer.
func Balance() int64 { return bubble.BalanceOf(Address()) }

// Router is the enrolled router on Solana, in hex.
func Router() string { return hex.EncodeToString(st.Router[:]) }

// Domain is the Solana domain this route sends to and takes from.
func Domain() uint32 { return st.Domain }

func Fee() int64      { return st.Fee }
func Minimum() int64  { return st.Minimum }
func FeeFloor() int64 { return st.FeeFloor }
func CapFloor() int64 { return st.CapFloor }
func Maximum() int64  { return st.Maximum }
func Cap() int64      { return st.Cap() }

// Counters is the identity's five counters (§5.9): sentTotal, paidTotal, owed, voided, lost.
func Counters() (sentTotal, paidTotal, owed, voided, lost int64) {
	return st.SentTotal, st.PaidTotal, st.Owed, st.Voided, st.Lost
}

// Migrated is the successor's pkgpath once a migration applied, "" before.
func Migrated() string { return st.MigratedTo }

// ---------------------------------------------------------------- out --

// TransferRemote sends amount of the caller's BUBBLE to recipient on destination (a Solana address in base58, or
// 32 bytes in hex) and returns the message id in hex. First, on the bubble realm, the caller approves THIS realm
// (bubble.Approve, spender Address()) for at least amount + fee: the amount is locked here, the fee goes to
// r/hlfees. The amount is between the minimum and the per-message maximum.
func TransferRemote(cur realm, destination uint32, recipient string, amount int64) string {
	who := caller(cur)
	mustBeLive()
	mustNotBePaused(hlmailbox.FnSends)
	mustNotBeDropped()
	st.MustSend(hlmailbox.Predecessor(pkgPath), env(cur)) // a successor takes no send before its last page is in (R35, F28) and before kind 6 names it (AT7)
	if destination != st.Domain {
		panic("hlbubble: no route to domain " + u32(destination))
	}
	st.CheckSend(amount)
	to, err := hl.ParseKey32(recipient)
	if err != nil {
		panic(err.Error())
	}
	if to == ([32]byte{}) {
		panic("hlbubble: the recipient is all zeros")
	}
	if a, err := hl.Bytes32ToAddress(to); err == nil && isRealm(a) {
		panic("hlbubble: the recipient is a realm of the bridge")
	}
	self := Address()
	before := bubble.BalanceOf(self)
	bubble.TransferFrom(cross(cur), who, self, amount+st.Fee)
	if bubble.BalanceOf(self) != before+amount+st.Fee {
		panic("hlbubble: the lock moved by the wrong amount")
	}
	bubble.Transfer(cross(cur), chain.PackageAddress(feesPath), st.Fee)
	id := hlmailbox.Dispatch(cross(cur), destination, st.Router, hl.TokenMessage(to, uint64(amount), nil))
	idHex := hex.EncodeToString(id[:])
	st.Send(now(), idHex, who, amount)
	chain.Emit("SentTransferRemote",
		"destination", u32(destination),
		"recipient", hex.EncodeToString(to[:]),
		"amount", itoa(amount),
		"fee", itoa(st.Fee),
		"from", string(who),
		"id", idHex,
	)
	return idHex
}

// ----------------------------------------------------------------- in --

// Process takes a token message from Solana and credits a claim to its recipient. Anyone may call it with the
// verifier's metadata and the message, both in hex. A refused message stays undelivered. A realm registered as a
// successor credits nothing — its own messages included (R32) — before the last page of its predecessor's
// migration is in (AQ1); a migrated realm refuses before the mailbox is asked (see hlgnot's).
func Process(cur realm, metadata, message string) {
	caller(cur)
	mustBeLive()
	mustNotBePaused(hlmailbox.FnCredits)
	mustNotBeDropped()
	msg := mustHex(message, "message")
	m, err := hl.ParseMessage(msg)
	if err != nil {
		panic(err.Error())
	}
	if st.Migrated() {
		panic("hlbubble: migrated to " + st.MigratedTo + ": the successor takes this message")
	}
	if self, err := hl.AddressToBytes32(Address()); err != nil {
		panic(err.Error())
	} else {
		st.MustTake(m.Recipient == self, hlmailbox.Predecessor(pkgPath))
	}
	t := now()
	if m.Origin != st.Domain || !st.RouterAccepts(t, m.Sender) {
		panic("hlbubble: the message is not from the router enrolled for domain " + u32(st.Domain))
	}
	rcpt, amount, _, err := hl.ParseTokenMessage(m.Body)
	if err != nil {
		panic(err.Error())
	}
	if amount > maxI64 {
		panic("hlbubble: the amount is past what BUBBLE can hold")
	}
	origin, sender, body := hlmailbox.Process(cross(cur), mustHex(metadata, "metadata"), msg)
	if origin != m.Origin || sender != m.Sender || string(body) != string(m.Body) {
		panic("hlbubble: the mailbox read the message differently") // cannot happen: the same bytes, the same parser
	}
	// a recipient that is no gno address (its top twelve bytes not zero, §13) or a realm of the bridge is swept:
	// owed, paying nobody until GovDAO credits it by id to its owner
	to, err := hl.Bytes32ToAddress(rcpt)
	recipient := string(to)
	if err != nil {
		recipient = hex.EncodeToString(rcpt[:])
	}
	idb := hl.ID(msg)
	id := hex.EncodeToString(idb[:])
	epoch, _ := hlmailbox.PayoutsEpoch(pkgPath)
	swept := st.Credit(t, runtime.ChainHeight(), epoch, id, to, int64(amount), hlroute.BySigners, err != nil || isRealm(to))
	chain.Emit("Credited",
		"origin", u32(origin),
		"recipient", recipient,
		"amount", itoa(int64(amount)),
		"id", id,
		"swept", strconv.FormatBool(swept),
	)
}

// Claim pays up to n claims (n ≤ 20) taking recipients in turns under the meters, the fee as each claim's first
// installment. Anyone may call it; the relayers do. It returns how many claims it paid something on.
func Claim(cur realm, n int) int {
	caller(cur)
	mustBeLive()
	mustNotBePaused(hlmailbox.FnPayouts)
	mustNotBeDropped()
	syncLaunch()
	epoch, at := hlmailbox.PayoutsEpoch(pkgPath)
	paid := st.Claim(now(), n, epoch, at, env(cur))
	chain.Emit("Claimed", "count", strconv.Itoa(paid))
	return paid
}

func pay(cur realm, to address, amount int64) { bubble.Transfer(cross(cur), to, amount) }

func env(cur realm) hlroute.Env {
	return hlroute.Env{
		Flagged:    func(id string, height int64, verifier bool) bool { return hlmailbox.Flagged(pkgPath, id, height, verifier) },
		ClearFlags: func(fn string) bool { return hlmailbox.ClearFlags(cross(cur), fn) },
		RemoveSeat: func(seat int, holder address) bool { return hlmailbox.VacateSeat(cross(cur), seat, holder) },
		Delivered:  func(id string) bool { return hlmailbox.Delivered(id) != 0 },
		MarkDone:   func(id string) { hlmailbox.MarkDone(cross(cur), id) },
		Epoch:      func() int64 { e, _ := hlmailbox.PayoutsEpoch(pkgPath); return e },
		Height:     func() int64 { return runtime.ChainHeight() },
		Pay:        func(to address, amount int64) { pay(cur, to, amount) },
		PayFee:     func(amount int64) { pay(cur, chain.PackageAddress(feesPath), amount) },
		AddRoute:     func(path string) { hlmailbox.AddRoute(cross(cur), path) },
		AnnouncedFor: func(path string) string { return hlmailbox.SuccessorFor(path) },
		Predecessor:  func() string { return hlmailbox.Predecessor(pkgPath) },
		IsRoute:      func(path string) bool { return hlmailbox.IsRoute(path) },
		Enrolled:     func() (int64, int64) { return hlmailbox.Enrolled(pkgPath) },
	}
}

// ------------------------------------------------------------ builders --

// The builders (§5.3): the same as r/hlgnot's, amounts in BUBBLE base units. A decision made with one of them —
// the governor's through Govern until it yields on r/hlmailbox, a GovDAO proposal's after (M1k) — is the only way
// a setting changes; see hlgnot's for the clocks and the Request.

// Request is what a builder returns (M1k): the proposal GovDAO's proxy executes after the yield (Proposal), and
// the same decision the governor runs directly before it (Govern); see hlgnot's.
type Request struct {
	proposal dao.ProposalRequest
	text     string
	decide   func(cur realm) error
}

// Proposal is the request as a GovDAO proposal: `dao.MustCreateProposal(cross(cur), req.Proposal())`.
func (r Request) Proposal() dao.ProposalRequest { return r.proposal }

// Description is the proposal's: the parameters as the builder wrote them.
func (r Request) Description() string { return r.text }

// who names a previous realm in a refusal: its pkgpath, or a user's address.
func who(path string, a address) string {
	if path != "" {
		return path
	}
	return string(a)
}

// mustBeGovernor is a decision's identity check (M1k), read from the closure's own live cur: the governor's own
// call until it yields on r/hlmailbox, gno.land/r/gov/dao's proxy exactly after (or from the first block, when no
// governor was compiled); see hlgnot's.
func mustBeGovernor(cur realm) {
	prev := cur.Previous()
	if decisions.DAOGoverns(launchGovernor, hlmailbox.Yielded()) {
		if p := prev.PkgPath(); p != decisions.DAOPath {
			panic("hlbubble: only " + decisions.DAOPath + " executes a decision, not " + who(prev.PkgPath(), prev.Address()))
		}
		return
	}
	if !prev.IsUser() || prev.Address() != launchGovernor {
		panic("hlbubble: until the governor yields, " + string(launchGovernor) + " alone decides, by Govern from its own key: not " + who(prev.PkgPath(), prev.Address()) + " (a GovDAO proposal is refused until the yield)")
	}
}

func propose(cur realm, d hlroute.Draft) Request {
	if !cur.IsCurrent() {
		panic("hlbubble: that realm value is not live; pass your own cur")
	}
	made := now()
	cb := func(cur realm) error {
		mustBeGovernor(cur)
		t := now()
		if err := decisions.Expired(made, t); err != nil {
			return err
		}
		if d.Kind != hlroute.KindCancel {
			mustBeLive()
		}
		if d.Kind == hlroute.KindApplyRefund {
			mustNotBePaused(hlmailbox.FnPayouts) // a refund moves BUBBLE out of the lock: under a standing payouts flag it waits like a claim (§5.9; the proposal survives for a retry)
		}
		dec := st.Decide(made, t, d, env(cur))
		chain.Emit("Decision", "id", itoa(dec.ID), "kind", dec.Kind, "state", dec.State())
		return nil
	}
	return Request{proposal: dao.NewProposalRequest("hlbubble: "+d.Kind, d.Text, dao.NewSimpleExecutor(0, cur, cb, d.Text)), text: d.Text, decide: cb}
}

// Govern is the governor's way in before the yield (M1k): the same closure GovDAO's proxy runs after it, called
// non-crossing in this frame so it reads the governor from cur.Previous(); refused for anyone else and for
// everyone once the governor yielded on r/hlmailbox (or when none was compiled); see hlgnot's.
func Govern(cur realm, r Request) {
	if !cur.IsCurrent() {
		panic("hlbubble: that realm value is not live; pass your own cur")
	}
	if r.decide == nil {
		panic("hlbubble: not a builder's request")
	}
	if yielded := hlmailbox.Yielded(); decisions.DAOGoverns(launchGovernor, yielded) {
		if launchGovernor == "" {
			panic("hlbubble: no governor was compiled, " + decisions.DAOPath + " governs from the first block: a decision is a GovDAO proposal, never Govern")
		}
		panic("hlbubble: the governor yielded at height " + itoa(yielded) + ", " + decisions.DAOPath + " governs since: a decision is a GovDAO proposal, never Govern")
	}
	mustBeGovernor(cur)
	if err := r.decide(cur); err != nil {
		panic("hlbubble: " + err.Error())
	}
}

